// Pitwall: the pit wall for Claude Code.
//
// Claude Code's mod rules keep `$` inside the hooks: it is never passed to a
// function. So the effects live here, in one controller (`serve`, built in
// session.start and kept in `mem.serve` so every other hook and every button
// calls it as a plain function), and everything that can be decided from plain
// data lives in src/ and is tested on its own.

import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Core, Layer, Live, Nav, Prefs, Scope, Tab, Talk } from '../types'
import { buildPrompt, CONFIGURATOR, describeSetup, isApproval, MARKER } from '../src/chat'
import { fmtTok, setDecimal } from '../src/format'
import { decimalFor, LANGS, pickLang, translate, type Key, type Lang, type T } from '../src/i18n'
import { judge, mutates, NEEDS_GO, settingsEditRisk } from '../src/guard'
import { bestMatch } from '../src/hints'
import { emptyLedger, mergeLedger, revive, unused } from '../src/ledger'
import { digestPrompt, needsDigest, parseDigest, SYSTEM as DIGEST_SYSTEM, type DigestInput } from '../src/digest'
import { buildItems, friendlyName, jobChange } from '../src/items'
import { buildSnapshot } from '../src/model'
import { guessKind, hasOwnSettings, localSettings, projectKey, projectName } from '../src/project'
import {
  classifyUpdate,
  clearTools,
  describeCall,
  diffPending,
  firstLine,
  marketplaceRepo,
  nextUndo,
  parseDescription,
  fingerprint,
  parseManifest,
  parsePluginMeta,
  parseSkillMeta,
  planSkillModes,
  PLUGIN_ID,
  pluginKey,
  SKILL_NAME,
  revertKeys,
  setPluginEnabled,
  skillKeys,
  toolKeys,
  SNAPSHOT_FILES,
  snapshotDir,
  toReq,
  type KeyChange,
  type SnapshotInfo,
} from '../src/plan'
import { CHAT_MAX, liveRuns, mem, RECENT_MAX, takeDirty, track, type Serve } from '../src/session'
import { makeAct } from '../src/views/act'
import { Band } from '../src/views/band'
import { Broken } from '../src/views/broken'
import type { Data } from '../src/views/context'
import { Pane } from '../src/views/pane'

// The values the drawings read. They live in the host (`$.state`), so a hot
// reload loses nothing. The mod rules want each ref's `plugin` and `key` as
// literals in this file.
const sNav = atom({ plugin: 'pitwall', key: 'nav' } as const, { tab: 'home', open: null, info: null, adv: null, tech: null, more: null, advOn: false, find: '', opt: false, keep: [], gtools: false } as Nav)
const sCore = atom(
  { plugin: 'pitwall', key: 'core' } as const,
  { snap: null, pending: [], prefs: { showBand: true, hints: true, summaries: true, autopilot: false, lang: 'auto' }, notice: null, busy: null, hint: null, digest: {}, digesting: false, layers: null, project: null, projects: [] } as Core,
)
const sTalk = atom({ plugin: 'pitwall', key: 'talk' } as const, { chat: [], isChatBusy: false, sent: 0, trace: [] } as Talk)
const sLive = atom({ plugin: 'pitwall', key: 'live' } as const, { recent: [] } as Live)

export const register: Register = on => {
  const t: T = (key, vars) => translate(mem.lang, key, vars)
  // What changes the person's files runs one request at a time, in the order the presses came: two
  // quick presses on Undo must undo two changes, not the same one twice.
  // The requests that write a settings file say where: the tab that sends them decides.
  const SCOPED = new Set(['plugin', 'skill', 'set', 'dim', 'undo'])
  const MUTATING = new Set(['plugin', 'skill', 'set', 'dim', 'undo', 'update', 'status', 'inherit', 'autopilot', 'decline'])
  const call: Serve = req => {
    const serve = mem.serve
    if (!serve) return Promise.resolve({ text: t('msg.starting') })
    if (!MUTATING.has(req.op)) return serve(req)
    const run = (mem.queue ?? Promise.resolve()).then(() => serve(req))
    mem.queue = run.then(
      () => undefined,
      () => undefined,
    )
    return run
  }

  on('session.start', async ($, e, next) => {
    mem.home = ((await $.env.get('USERPROFILE')) ?? (await $.env.get('HOME')) ?? '').replace(/\\/g, '/')
    mem.tmp = ((await $.env.get('TEMP')) ?? (await $.env.get('TMPDIR')) ?? '/tmp').replace(/\\/g, '/')
    const configured = ((await $.env.get('CLAUDE_CONFIG_DIR')) ?? '').replace(/\\/g, '/').replace(/\/+$/, '')
    mem.claudeDir = configured || `${mem.home}/.claude`
    const base = mem.claudeDir

    const note = async (kind: 'tool' | 'skill' | 'agent' | 'turn' | 'change', label: string) => {
      const at = await $.clock.now()
      await update($, sLive, s => ({ ...s, recent: (list => [...list, { at, kind, label }].slice(-RECENT_MAX))(s.recent) }))
    }

    // A snapshot that cannot be completed is a failure, never a partial copy: every
    // caller stops when it fails, so nothing changes without a way back.
    // Where a change is written. A project keeps its own setup in its .claude/settings.local.json,
    // which Claude Code reads for that folder and keeps out of git; with no project, or on the Global
    // tab, the file is ~/.claude/settings.json. `file` is how a change names its file in a backup.
    const targetOf = (scope: Scope | undefined): { path: string; file: string; scope: Scope; key: string } => {
      const project = mem.project
      if (scope !== 'global' && project) return { path: localSettings(project.root), file: localSettings(project.root), scope: 'project', key: project.key }
      return { path: `${base}/settings.json`, file: 'settings.json', scope: 'global', key: 'global' }
    }
    const readOr = async (path: string): Promise<string> => {
      try {
        return (await $.fs.read(path)) as string
      } catch {
        // No file yet: the edit creates it.
        return ''
      }
    }
    // A project's own settings file is private to the person, like the one Claude Code itself makes.
    // Claude Code only ignores it when it creates the file, so when Pitwall does, the line goes into
    // .git/info/exclude: local to this clone, nothing in the repository changes.
    const keepOutOfGit = async (root: string) => {
      try {
        if (!(await $.fs.exists(`${root}/.git/HEAD`))) return
        const path = `${root}/.git/info/exclude`
        const line = '.claude/settings.local.json'
        const text = await readOr(path)
        if (text.split(/\r?\n/).some(l => l.trim() === line)) return
        await $.fs.write(path, `${text}${text === '' || text.endsWith('\n') ? '' : '\n'}${line}\n`)
      } catch {
        // Not a plain clone: the file simply shows up as untracked.
      }
    }
    // What one settings source sets on its own, as the engine reads it.
    const layerOf = async (source: 'user' | 'project' | 'local'): Promise<Layer> => {
      const s = ((await $.settings.read({ source }).catch(() => ({}))) ?? {}) as { enabledPlugins?: Record<string, unknown>; skillOverrides?: Record<string, unknown> }
      const plugins: Record<string, boolean> = {}
      for (const [k, v] of Object.entries(s.enabledPlugins ?? {})) if (typeof v === 'boolean') plugins[k] = v
      const skills: Record<string, string> = {}
      for (const [k, v] of Object.entries(s.skillOverrides ?? {})) if (typeof v === 'string') skills[k] = v
      return { plugins, skills }
    }
    // After a write to a project's file: how many of the values it holds are overridden by a higher
    // source (managed or command-line settings), so the person is told rather than left to wonder.
    const overridden = async (plugins: { id: string; isOn: boolean }[], skills: { name: string; mode: string }[]): Promise<number> => {
      const local = await layerOf('local')
      const merged = ((await $.settings.read().catch(() => ({}))) ?? {}) as { enabledPlugins?: Record<string, unknown>; skillOverrides?: Record<string, string> }
      const lost = [
        ...plugins.filter(p => local.plugins[p.id] === p.isOn && (merged.enabledPlugins?.[p.id] === true) !== p.isOn),
        ...skills.filter(s => (local.skills[s.name] ?? 'on') === s.mode && (merged.skillOverrides?.[s.name] ?? 'on') !== s.mode),
      ]
      return lost.length
    }
    const snapshot = async (reason: string, changes: KeyChange[] = [], scope = 'global'): Promise<{ ok: boolean; dir: string }> => {
      const now = await $.clock.now()
      const dir = snapshotDir(base, now, mem.snapSeq++ % 1000)
      try {
        const saved: string[] = []
        for (const file of SNAPSHOT_FILES) {
          if (!(await $.fs.exists(`${base}/${file}`))) continue
          await $.fs.write(`${dir}/${file}`, (await $.fs.read(`${base}/${file}`)) as string)
          saved.push(file)
        }
        await $.fs.write(`${dir}/manifest.json`, JSON.stringify({ reason, at: now, scope, files: saved, changes, after: {} }, null, 2))
        return { ok: true, dir }
      } catch {
        return { ok: false, dir }
      }
    }

    // What the files are now, so Undo can tell a file edited since from one it left as it was.
    const fingerprints = async (): Promise<Record<string, string>> => {
      const out: Record<string, string> = {}
      for (const file of SNAPSHOT_FILES) {
        try {
          if (await $.fs.exists(`${base}/${file}`)) out[file] = fingerprint((await $.fs.read(`${base}/${file}`)) as string)
        } catch {
          // Unreadable now: left out, and Undo then restores it as it was.
        }
      }
      return out
    }

    // The language: the person's choice in Setup, else what Claude Code is set to, else the system's.
    const detect = async (): Promise<Lang> => {
      const settings = (await $.settings.read().catch(() => ({}))) as Record<string, unknown>
      let locale = ''
      try {
        locale = Intl.DateTimeFormat().resolvedOptions().locale
      } catch {
        // No Intl: the environment variables below have to do.
      }
      return pickLang([
        String(settings.language ?? ''),
        await $.env.get('LC_ALL'),
        await $.env.get('LC_MESSAGES'),
        await $.env.get('LANGUAGE'),
        await $.env.get('LANG'),
        locale,
      ])
    }
    const setLanguage = async (choice: string) => {
      mem.autoLang = await detect()
      mem.lang = choice === 'auto' ? mem.autoLang : (choice as Lang)
      setDecimal(decimalFor(mem.lang))
      await showDigest()
    }

    // The summaries in the language in use, as the drawings read them.
    const showDigest = async () => {
      const have = mem.digest[mem.lang] ?? {}
      const shown = Object.fromEntries(Object.entries(have).map(([k, v]) => [k, { s: v.s, c: v.c }]))
      await update($, sCore, s => ({ ...s, digest: shown }))
    }

    // One small model call per twenty tools writes each one's plain summary and set, in the person's
    // language. It is made once per tool and language and kept in the store, so it costs next to nothing.
    const digestRun = async () => {
      const core = await read($, sCore)
      if (!core.prefs.summaries || !core.snap || mem.digestBusy) return
      const lang = mem.lang
      const have = (mem.digest[lang] ??= {})
      const inputs: DigestInput[] = [
        ...core.snap.plugins.map(p => ({ key: `plugin:${p.id}`, name: p.name, description: p.description ?? '', skills: p.skillNames?.length ? p.skillNames : mem.names[p.id] })),
        ...core.snap.skills.filter(s => s.isOwn).map(s => ({ key: `skill:${s.name}`, name: s.name, description: s.description ?? '' })),
      ]
      if (needsDigest(inputs, have).length === 0) return
      mem.digestBusy = true
      try {
        await update($, sCore, s => ({ ...s, digesting: true }))
        // As many batches as it takes, and a second and third pass for the tools a reply left out.
        for (let pass = 0; pass < 3; pass++) {
          const todo = needsDigest(inputs, have)
          let wrote = 0
          for (let i = 0; i < todo.length; i += 25) {
            const batch = todo.slice(i, i + 25)
            const reply = await $.model.complete({ model: 'haiku', system: DIGEST_SYSTEM, prompt: digestPrompt(t(`lang.assistant.${lang}` as Key), batch), maxTokens: 4000 }).catch(() => undefined)
            if (!reply || !reply.isAnswered) {
              wrote = -1
              break
            }
            const got = parseDigest(reply.text, batch)
            wrote += Object.keys(got).length
            Object.assign(have, got)
            await $.store.set('digest', mem.digest).catch(() => undefined)
            if (lang === mem.lang) await showDigest()
          }
          if (wrote <= 0) break
        }
      } finally {
        mem.digestBusy = false
        await update($, sCore, s => ({ ...s, digesting: false }))
      }
    }

    // What an installed plugin or one of the person's skills says about itself, read once.
    const learn = async (key: string, path: string, kind: 'plugin' | 'skill', fromMarketplace?: string) => {
      const cached = mem.meta.get(key)
      if (cached) return cached
      let raw = ''
      try {
        raw = (await $.fs.read(path)) as string
      } catch {
        // Not readable: the row simply has nothing to say.
      }
      const meta = kind === 'plugin' ? parsePluginMeta(raw, fromMarketplace) : parseSkillMeta(raw)
      const entry = { ...meta, text: raw ? parseDescription(path, raw) : '' }
      mem.meta.set(key, entry)
      return entry
    }

    // A light measurement asks only for the usage (the context and the plan limits) and the settings:
    // what is installed does not change between two turns, and the usage does.
    const measure = async (light = false) => {
      const errors: string[] = []
      const now = await $.clock.now()
      mem.lastMeasure = now
      const usage = await $.session.usage({ breakdown: 'summary' }).catch(() => {
        errors.push('context usage')
        return undefined
      })
      const settings: Record<string, any> = await $.settings.read().catch(() => {
        errors.push('settings')
        return {}
      })
      let installed: Record<string, any[]> = {}
      let ownSkills: string[] = []
      let meta: Record<string, { description?: string; repo?: string }> = {}
      let layers: { user: Layer; project: Layer; local: Layer } = { user: { plugins: {}, skills: {} }, project: { plugins: {}, skills: {} }, local: { plugins: {}, skills: {} } }
      if (light && mem.inputs) {
        ;({ installed, ownSkills, meta, layers } = mem.inputs)
      } else {
        // What each source sets on its own, so a project's own setup can be told from what it inherits.
        const empty: Layer = { plugins: {}, skills: {} }
        layers = { user: await layerOf('user'), project: mem.project ? await layerOf('project') : empty, local: mem.project ? await layerOf('local') : empty }
        try {
          installed = JSON.parse((await $.fs.read(`${base}/plugins/installed_plugins.json`)) as string).plugins ?? {}
        } catch {
          errors.push('installed plugins')
        }
        ownSkills = []
        try {
          for (const entry of await $.fs.list(`${base}/skills`)) {
            const isDir = entry.kind === 'dir' || entry.isLink
            if (!isDir || !/^[A-Za-z0-9._:-]+$/.test(entry.name)) continue
            // Each question to the host costs a round trip: a folder already known to hold a skill is not asked about again.
            if (mem.skillOk.has(entry.name) || (await $.fs.exists(`${base}/skills/${entry.name}/SKILL.md`))) {
              mem.skillOk.add(entry.name)
              ownSkills.push(entry.name)
            }
          }
        } catch {
          // No skills folder: nothing of the user's own to list.
        }
        let known: Record<string, unknown> = {}
        try {
          known = JSON.parse((await $.fs.read(`${base}/plugins/known_marketplaces.json`)) as string)
        } catch {
          // No marketplaces file: a plugin's own plugin.json is then the only source of a link.
        }
        meta = {}
        for (const [id, entries] of Object.entries(installed)) {
          const where = entries[0]?.installPath
          if (!where) continue
          const m = await learn(`plugin:${id}`, `${where}/.claude-plugin/plugin.json`, 'plugin', marketplaceRepo(known, id.split('@')[1] ?? ''))
          meta[`plugin:${id}`] = { description: m.description, repo: m.repo }
        }
        for (const name of ownSkills) {
          const m = await learn(`skill:${name}`, `${base}/skills/${name}/SKILL.md`, 'skill')
          meta[`skill:${name}`] = { description: m.description, repo: m.repo }
        }
        mem.inputs = { installed, ownSkills, meta, layers }
      }
      const snap = buildSnapshot({ now, usage, settings, installed, ownSkills, meta, errors })
      // Remember what each plugin cost while it was on, so an off one can say what turning it on adds.
      mem.costs ??= ((await $.store.get('costs')) as Record<string, number> | undefined) ?? {}
      const costs = mem.costs
      let costsChanged = false
      for (const p of snap.plugins) {
        if (p.isOn && p.tokens > 0 && costs[p.id] !== p.tokens) {
          costs[p.id] = p.tokens
          costsChanged = true
        }
        if (!p.isOn && costs[p.id]) p.lastTokens = costs[p.id]
      }
      for (const s of snap.skills) {
        if (!s.isOwn) continue
        const key = `skill:${s.name}`
        if (s.tokens > 0 && costs[key] !== s.tokens) {
          costs[key] = s.tokens
          costsChanged = true
        }
        if (s.tokens === 0 && costs[key]) s.lastTokens = costs[key]
      }
      if (costsChanged) await $.store.set('costs', costs).catch(() => undefined)
      // The skills an add-on carries, remembered so its set does not change when it is switched off.
      let namesChanged = false
      for (const p of snap.plugins) {
        if (p.skillNames?.length && mem.names[p.id]?.join() !== p.skillNames.join()) {
          mem.names[p.id] = p.skillNames
          namesChanged = true
        }
      }
      if (namesChanged) await $.store.set('names', mem.names).catch(() => undefined)
      mem.baseline ??= { enabled: { ...(settings.enabledPlugins ?? {}) }, overrides: { ...(settings.skillOverrides ?? {}) } }

      // What a hint can match: the words describing whatever is switched off.
      const candidates = []
      for (const p of snap.plugins) {
        if (p.isOn) continue
        candidates.push({ id: `plugin:${p.id}`, kind: 'plugin' as const, target: p.id, text: `${p.name} ${mem.meta.get(`plugin:${p.id}`)?.text ?? ''}` })
      }
      for (const s of snap.skills) {
        if (!s.isOwn || s.mode === 'on') continue
        candidates.push({ id: `skill:${s.name}`, kind: 'skill' as const, target: s.name, text: `${s.name} ${mem.meta.get(`skill:${s.name}`)?.text ?? ''}` })
      }
      mem.candidates = candidates
      const pending = diffPending(mem.baseline, settings)
      await update($, sCore, s => ({ ...s, snap, pending, layers }))
      if (!light) void digestRun().catch(() => undefined)
    }

    // One measurement at a time; a request that comes in mid-way runs after it.
    const refresh = (light = false) => (mem.refreshing = (mem.refreshing ?? Promise.resolve()).then(() => measure(light), () => measure(light)))

    // Written into a backup once its change is done, so Undo can tell later edits from the change itself.
    const recordAfter = async (dir: string) => {
      try {
        const manifest = parseManifest((await $.fs.read(`${dir}/manifest.json`)) as string)
        if (manifest) await $.fs.write(`${dir}/manifest.json`, JSON.stringify({ ...manifest, after: await fingerprints() }, null, 2))
      } catch {
        // Without it Undo restores the files as they were, which is still the right default.
      }
    }

    const finish = async (result: { ok: boolean; message: string }, label: string) => {
      await update($, sCore, s => ({ ...s, notice: result.message, busy: null }))
      if (result.ok) await note('change', label)
      else $.ui.toast(result.message)
      await refresh()
    }

    const finishChat = async (text: string, role: 'assistant' | 'system') => {
      const at = await $.clock.now()
      await update($, sTalk, s => ({ ...s, chat: (list => [...list, { role, text: text.slice(0, 8000), at }].slice(-CHAT_MAX))(s.chat) }))
      await update($, sTalk, s => ({ ...s, isChatBusy: false }))
      await update($, sTalk, s => ({ ...s, trace: [] }))
      await $.store.set('chat', ((await read($, sTalk)).chat).slice(-CHAT_MAX)).catch(() => undefined)
    }

    // What Pitwall keeps about the projects it has seen, in the store: where, when, and the profile set.
    const rememberProject = async (patch: { profile?: { job: string; at: number }; declined?: boolean }) => {
      const project = mem.project
      if (!project) return
      const all = ((await $.store.get('projects')) as Record<string, any> | undefined) ?? {}
      const row = { ...(all[project.key] ?? {}), root: project.root, name: project.name, last: await $.clock.now(), ...patch }
      if (patch.profile === undefined && 'profile' in patch) delete row.profile
      all[project.key] = row
      await $.store.set('projects', all).catch(() => undefined)
      mem.project = { ...project, profile: row.profile, declined: row.declined }
      const list = Object.entries(all).map(([key, v]) => ({ key, name: String(v.name ?? ''), last: Number(v.last) || 0 })).sort((a, b) => b.last - a.last).slice(0, 40)
      await update($, sCore, s => ({ ...s, project: mem.project, projects: list }))
    }

    const serve: Serve = async req => {
      switch (req.op) {
        case 'init': {
          const now = await $.clock.now()
          mem.ledger = revive(await $.store.get('ledger'), now)
          const savedDigest = await $.store.get('digest')
          if (savedDigest && typeof savedDigest === 'object') mem.digest = savedDigest as typeof mem.digest
          const savedNames = await $.store.get('names')
          if (savedNames && typeof savedNames === 'object') mem.names = savedNames as Record<string, string[]>
          try {
            mem.version = String(JSON.parse((await $.fs.read(`${$.plugin.root}/.claude-plugin/plugin.json`)) as string).version ?? '')
          } catch {
            // Without a version the About line simply leaves it out.
          }
          // The project: the folder this chat runs in, unless it cannot have settings of its own.
          const cwd = ((await $.session.cwd().catch(() => '')) ?? '').replace(/\\/g, '/').replace(/\/+$/, '')
          if (cwd && hasOwnSettings(cwd, base, mem.home)) {
            const key = projectKey(cwd)
            const all = ((await $.store.get('projects')) as Record<string, any> | undefined) ?? {}
            const known = all[key] ?? {}
            mem.project = { root: cwd, name: projectName(cwd), key, profile: known.profile, declined: known.declined }
            mem.pledger = revive(await $.store.get(`ledger:${key}`), now)
            try {
              const entries = await $.fs.list(cwd)
              mem.project.guess = guessKind(entries.map(e => (e.kind === 'dir' ? `${e.name}/` : e.name)))
            } catch {
              // An unreadable folder simply gets no guess.
            }
            await rememberProject({})
          }
          const saved = await $.store.get('chat')
          if (Array.isArray(saved)) await update($, sTalk, s => ({ ...s, chat: saved.slice(-CHAT_MAX) }))
          const prefs = (await $.store.get('prefs')) as Partial<Prefs> | undefined
          const chosen = prefs?.lang && (prefs.lang === 'auto' || (LANGS as readonly string[]).includes(prefs.lang)) ? prefs.lang : 'auto'
          await update($, sCore, s => ({ ...s, prefs: ({ showBand: prefs?.showBand !== false, hints: prefs?.hints !== false, summaries: prefs?.summaries !== false, autopilot: prefs?.autopilot === true, lang: chosen }) }))
          await setLanguage(chosen)
          await refresh()
          // Autopilot: a project starts with the setup its work needs, and with tools nobody opened there for a month light.
          if (prefs?.autopilot === true) void call({ op: 'autopilot' }).catch(() => undefined)
          return { text: 'ready' }
        }

        case 'refresh':
          await refresh(req.light === true)
          return { text: 'ok' }

        case 'flush':
          if (takeDirty()) {
            // Other sessions write this store too: add this session's counts to what is there now.
            const merged = mergeLedger(revive(await $.store.get('ledger'), await $.clock.now()), mem.delta)
            mem.delta = emptyLedger(0)
            mem.ledger = merged
            await $.store.set('ledger', merged).catch(() => undefined)
            if (mem.project) {
              const mine = mergeLedger(revive(await $.store.get(`ledger:${mem.project.key}`), await $.clock.now()), mem.pdelta)
              mem.pdelta = emptyLedger(0)
              mem.pledger = mine
              await $.store.set(`ledger:${mem.project.key}`, mine).catch(() => undefined)
            }
          }
          return { text: 'ok' }

        case 'snapshot': {
          const taken = await snapshot(req.reason)
          if (taken.ok && req.agentId) mem.runDirs.set(req.agentId, taken.dir)
          return { text: taken.ok ? 'ok' : 'failed' }
        }

        case 'open':
          await $.ui.open({ id: 'pitwall', title: 'Pitwall', focus: true, closeOnEscape: true, rows: 22 })
          void refresh().catch(() => undefined)
          void digestRun().catch(() => undefined)
          return { text: t('msg.opened') }

        case 'plugin': {
          if (!PLUGIN_ID.test(req.id)) {
            await finish({ ok: false, message: t('msg.notPlugin') }, '')
            return { text: 'refused' }
          }
          const tgt = targetOf(req.scope)
          const verb = req.isOn ? 'on' : 'off'
          const state = t(req.isOn ? 'word.on' : 'word.off')
          const name = friendlyName(req.id)
          await update($, sCore, s => ({ ...s, busy: t(req.isOn ? 'msg.busyOn' : 'msg.busyOff', { name }) }))
          const before = await readOr(tgt.path)
          const backup = await snapshot(`plugin ${verb}: ${req.id}`, pluginKey(before, req.id, tgt.file), tgt.key)
          if (!backup.ok) {
            await finish({ ok: false, message: t('msg.noBackup') }, '')
            return { text: 'failed' }
          }
          // The switch is one key in a settings file, edited here and not through the `claude` on
          // PATH (which may be another version, or absent), so Undo reverts exactly this edit.
          const edited = setPluginEnabled(await readOr(tgt.path), req.id, req.isOn)
          if ('error' in edited) {
            await finish({ ok: false, message: edited.error }, '')
            return { text: 'refused' }
          }
          try {
            await $.fs.write(tgt.path, edited.text)
          } catch {
            await finish({ ok: false, message: t('msg.cannotWrite', { name }) }, '')
            return { text: 'failed' }
          }
          if (tgt.scope === 'project' && before === '' && mem.project) await keepOutOfGit(mem.project.root)
          // A higher setting can still say otherwise: say so rather than claim a change that does not hold.
          const effective = ((await $.settings.read().catch(() => ({}))) as { enabledPlugins?: Record<string, unknown> }).enabledPlugins?.[req.id]
          const held = tgt.scope === 'project' ? (await overridden([{ id: req.id, isOn: req.isOn }], [])) === 0 : effective === undefined || effective === req.isOn
          await finish(
            held
              ? { ok: true, message: t('msg.pluginSwitched', { name, state }) }
              : { ok: true, message: t('msg.overridden', { name, state, other: t(effective ? 'word.on' : 'word.off') }) },
            `${name} ${verb}`,
          )
          return { text: 'ok' }
        }

        case 'skill':
        case 'dim': {
          const tgt = targetOf(req.scope)
          const core = await read($, sCore)
          let changes: { name: string; mode: string }[]
          if (req.op === 'skill') {
            changes = [{ name: req.name, mode: req.mode }]
          } else {
            const now = await $.clock.now()
            // Unused is judged where the change lands: in this project's own count for a project.
            const ledger = tgt.scope === 'project' ? mem.pledger : mem.ledger
            changes = (core.snap ? unused(core.snap.skills, ledger, now) : []).map(s => ({ name: s.name, mode: 'name-only' }))
            if (changes.length === 0) {
              // Autopilot runs at every start: nothing to do is not worth a message.
              if (!('auto' in req && req.auto)) await finish({ ok: false, message: t('msg.nothingDim') }, '')
              return { text: 'nothing' }
            }
          }
          // In a project's file "on" has to be written when the global setting would otherwise show through.
          const keepOn = tgt.scope === 'project' ? changes.filter(c => c.mode === 'on' && core.layers?.user.skills[c.name] !== undefined).map(c => c.name) : []
          const current = await readOr(tgt.path)
          const draft = planSkillModes(current, changes, keepOn)
          if ('error' in draft) {
            await finish({ ok: false, message: draft.error }, '')
            return { text: 'refused' }
          }
          const backup = await snapshot(draft.reason, skillKeys(current, changes.map(c => c.name), tgt.file), tgt.key)
          if (!backup.ok) {
            await finish({ ok: false, message: t('msg.noBackup') }, '')
            return { text: 'failed' }
          }
          // Read again right before writing, so an edit made while the backup ran is kept.
          const plan = planSkillModes(await readOr(tgt.path), changes, keepOn)
          if ('error' in plan) {
            await finish({ ok: false, message: plan.error }, '')
            return { text: 'refused' }
          }
          try {
            await $.fs.write(tgt.path, plan.text)
          } catch {
            await finish({ ok: false, message: t('msg.cannotWriteMany') }, '')
            return { text: 'failed' }
          }
          if (tgt.scope === 'project' && current === '' && mem.project) await keepOutOfGit(mem.project.root)
          const lost = tgt.scope === 'project' ? await overridden([], changes) : 0
          await finish(
            {
              ok: true,
              message: lost > 0 ? t('msg.notHeld', { n: lost }) : changes.length === 1 ? t('msg.skillNow', { name: changes[0].name, mode: t(`mode.${changes[0].mode}` as Key) }) : t('msg.skillsUpdated', { n: changes.length }),
            },
            req.op === 'dim' ? t('msg.dimmed', { n: changes.length }) : `${changes[0].name}: ${t(`mode.${changes[0].mode}` as Key)}`,
          )
          return { text: 'ok' }
        }

        case 'set': {
          // Several tools at once, from one press on a set: one backup, one write, one Undo.
          const tgt = targetOf(req.scope)
          const plugins = req.plugins.filter(p => PLUGIN_ID.test(p.id)).slice(0, 300)
          const skills = req.skills.filter(s => SKILL_NAME.test(s.name)).slice(0, 300)
          const total = plugins.length + skills.length
          if (total === 0) {
            await finish({ ok: false, message: t('msg.nothingToChange') }, '')
            return { text: 'nothing' }
          }
          await update($, sCore, s => ({ ...s, busy: t('msg.busySet', { n: total }) }))
          const core = await read($, sCore)
          const keepOn = tgt.scope === 'project' ? skills.filter(s => s.mode === 'on' && core.layers?.user.skills[s.name] !== undefined).map(s => s.name) : []
          const before = await readOr(tgt.path)
          const changes: KeyChange[] = [...plugins.flatMap(p => pluginKey(before, p.id, tgt.file)), ...skillKeys(before, skills.map(s => s.name), tgt.file)]
          const backup = await snapshot(req.label.slice(0, 80) || 'set', changes, tgt.key)
          if (!backup.ok) {
            await finish({ ok: false, message: t('msg.noBackup') }, '')
            return { text: 'failed' }
          }
          // Read again right before writing, so an edit made while the backup ran is kept.
          let text = await readOr(tgt.path)
          for (const p of plugins) {
            const edited = setPluginEnabled(text, p.id, p.isOn)
            if ('error' in edited) {
              await finish({ ok: false, message: edited.error }, '')
              return { text: 'refused' }
            }
            text = edited.text
          }
          if (skills.length > 0) {
            const plan = planSkillModes(text, skills, keepOn)
            if ('error' in plan) {
              await finish({ ok: false, message: plan.error }, '')
              return { text: 'refused' }
            }
            text = plan.text
          }
          try {
            await $.fs.write(tgt.path, text)
          } catch {
            await finish({ ok: false, message: t('msg.cannotWriteMany') }, '')
            return { text: 'failed' }
          }
          if (tgt.scope === 'project' && before === '' && mem.project) await keepOutOfGit(mem.project.root)
          if (tgt.scope === 'project' && req.profile && mem.project) await rememberProject({ profile: { job: req.profile, at: await $.clock.now() } })
          const lost = tgt.scope === 'project' ? await overridden(plugins, skills) : 0
          await finish({ ok: true, message: lost > 0 ? t('msg.notHeld', { n: lost }) : t(tgt.scope === 'project' ? 'msg.setHere' : 'msg.setDone', { n: total }) }, req.label)
          return { text: 'ok' }
        }

        case 'undo': {
          // Undo walks back one scope at a time: in a project, that project's last change.
          const scope: Scope = req.scope ?? (mem.project ? 'project' : 'global')
          const scopeKey = scope === 'project' && mem.project ? mem.project.key : 'global'
          const found: SnapshotInfo[] = []
          try {
            for (const entry of await $.fs.list(`${base}/pitwall/snapshots`)) {
              if (entry.kind !== 'dir') continue
              const dir = `${base}/pitwall/snapshots/${entry.name}`
              try {
                const m = parseManifest((await $.fs.read(`${dir}/manifest.json`)) as string)
                if (m) found.push({ dir, ...m, isRestored: await $.fs.exists(`${dir}/restored.json`) })
              } catch {
                // Not one of ours.
              }
            }
          } catch {
            // No snapshot folder yet.
          }
          if (liveRuns(await $.clock.now()) > 0) {
            await finish({ ok: false, message: t('msg.undoBusy') }, '')
            return { text: 'busy' }
          }
          const target = nextUndo(found, scopeKey)
          if (!target) {
            await finish({ ok: false, message: t('msg.nothingUndo') }, '')
            return { text: 'nothing' }
          }
          const safety = await snapshot(`before undoing "${target.reason}"`, [], scopeKey)
          if (!safety.ok) {
            await finish({ ok: false, message: t('msg.noBackupUndo') }, '')
            return { text: 'failed' }
          }
          // The safety copy is not something Undo walks back to, or a second Undo would redo the change.
          const at = await $.clock.now()
          await $.fs.write(`${safety.dir}/restored.json`, JSON.stringify({ at }))

          const left: string[] = []
          if (target.changes.length > 0) {
            // A switch Pitwall made: put back its keys in each file as it is now, nothing else. A project
            // file is only touched when it is this project's own settings file.
            for (const file of [...new Set(target.changes.map(c => c.file))]) {
              const own = file === 'settings.json' ? `${base}/settings.json` : mem.project && file === localSettings(mem.project.root) ? file : ''
              if (!own) {
                left.push(file)
                continue
              }
              const reverted = revertKeys(await readOr(own), target.changes, file)
              if ('error' in reverted) {
                await finish({ ok: false, message: reverted.error }, '')
                return { text: 'refused' }
              }
              await $.fs.write(own, reverted.text)
            }
          } else {
            // A configurator run: restore each file, unless it was edited after the run.
            for (const file of target.files) {
              if (!SNAPSHOT_FILES.includes(file)) continue
              const expected = target.after[file]
              const exists = await $.fs.exists(`${base}/${file}`)
              if (expected !== undefined && exists && fingerprint((await $.fs.read(`${base}/${file}`)) as string) !== expected) {
                left.push(file)
                continue
              }
              await $.fs.write(`${base}/${file}`, (await $.fs.read(`${target.dir}/${file}`)) as string)
            }
          }
          await $.fs.write(`${target.dir}/restored.json`, JSON.stringify({ at }))
          const kept = left.length ? t('msg.keptFile', { files: left.map(f => f.split('/').pop()).join(', ') }) : ''
          await finish({ ok: true, message: t('msg.undone', { what: target.reason || t('msg.lastChange'), kept }) }, 'undo')
          return { text: 'ok' }
        }

        case 'inherit': {
          // Back to the global setup: drop this project's own value of the tools named, or of all of them.
          const project = mem.project
          if (!project) return { text: 'nothing' }
          const tgt = targetOf('project')
          const local = (await read($, sCore)).layers?.local
          const keys = req.keys ?? [...Object.keys(local?.plugins ?? {}).map(id => `plugin:${id}`), ...Object.keys(local?.skills ?? {}).map(name => `skill:${name}`)]
          if (keys.length === 0) {
            await finish({ ok: false, message: t('msg.nothingToChange') }, '')
            return { text: 'nothing' }
          }
          const before = await readOr(tgt.path)
          const backup = await snapshot(t('proj.back'), toolKeys(before, keys, tgt.file), tgt.key)
          if (!backup.ok) {
            await finish({ ok: false, message: t('msg.noBackup') }, '')
            return { text: 'failed' }
          }
          const cleared = clearTools(await readOr(tgt.path), keys)
          if ('error' in cleared) {
            await finish({ ok: false, message: cleared.error }, '')
            return { text: 'refused' }
          }
          try {
            await $.fs.write(tgt.path, cleared.text)
          } catch {
            await finish({ ok: false, message: t('msg.cannotWriteMany') }, '')
            return { text: 'failed' }
          }
          if (!req.keys) await rememberProject({ profile: undefined })
          await finish({ ok: true, message: t('msg.inherited') }, t('proj.back'))
          return { text: 'ok' }
        }

        case 'decline':
          await rememberProject({ declined: true })
          return { text: 'ok' }

        case 'autopilot': {
          // Autopilot sets a project up by itself: the first time from the kind of work its files suggest,
          // afterwards by making the tools nobody opened there for a month light.
          const core = await read($, sCore)
          const project = mem.project
          if (!project) return serve({ op: 'dim', auto: true, scope: 'global' })
          const hasOwn = Object.keys(core.layers?.local.plugins ?? {}).length + Object.keys(core.layers?.local.skills ?? {}).length > 0
          if (core.snap && !project.profile && !project.declined && !hasOwn && project.guess) {
            const items = buildItems(core.snap, mem.names, core.digest, { scope: 'project', layers: core.layers })
            const change = jobChange(items, project.guess.job as never)
            if (change.plugins.length + change.skills.length > 0) {
              return serve({ op: 'set', ...change, label: t(`job.${project.guess.job}` as Key), scope: 'project', profile: project.guess.job })
            }
          }
          return serve({ op: 'dim', auto: true, scope: 'project' })
        }

        case 'lighter':
          await update($, sNav, s => ({ ...s, tab: 'chat' }))
          return serve({
            op: 'ask',
            text:
              'Make my setup lighter without losing anything I actually use. Use the usage history and costs you were given. ' +
              'Switch off or dim what is clearly unused (these changes are reversible: just do them). ' +
              'List what you would remove but could not undo, and wait for my go on those. Say in plain words how much of the memory this frees, without the word tokens. ' +
              `Answer in ${t(`lang.assistant.${mem.lang}` as Key)}.`,
          })

        case 'tighten':
          await update($, sNav, s => ({ ...s, tab: 'chat' }))
          return serve({
            op: 'ask',
            text:
              'Tighten my instructions so Claude carries less of them in every chat, without losing a single rule. ' +
              'Work only on ~/.claude/CLAUDE.md, the one instruction file that Undo can restore. Read all of it first. ' +
              'Merge duplicates, shorten the wording, drop examples that only repeat a rule and notes that are clearly out of date, ' +
              'and keep every rule, name, path, command, number and code block exactly as it is. ' +
              'Write the tighter version to ~/.claude/CLAUDE.proposal.md and do not touch CLAUDE.md yet. ' +
              'Tell me in at most six lines how much shorter it is and what kinds of things you changed, without the word tokens, then wait for my go. ' +
              'If it is already tight (less than a tenth to gain), say so and change nothing. ' +
              `Answer in ${t(`lang.assistant.${mem.lang}` as Key)}.`,
          })

        case 'ask': {
          const line = req.text.trim()
          if (!line) return { text: 'empty' }
          const at = await $.clock.now()
          if (((await read($, sTalk)).isChatBusy) || liveRuns(at) > 0) {
            $.ui.toast(t('msg.stillWorking'))
            return { text: 'busy' }
          }
          await update($, sTalk, s => ({ ...s, chat: (list => [...list, { role: 'user' as const, text: line, at }].slice(-CHAT_MAX))(s.chat) }))
          await update($, sTalk, s => ({ ...s, isChatBusy: true }))
          await update($, sTalk, s => ({ ...s, sent: (n => n + 1)(s.sent) }))
          await update($, sTalk, s => ({ ...s, trace: [] }))
          const prompt = buildPrompt(line, (await read($, sTalk)).chat, (await read($, sCore)).snap, mem.ledger, at, mem.claudeDir, mem.tmp, $.plugin.root)
          try {
            const started = await $.agent.spawn({ subagentType: CONFIGURATOR, prompt, description: MARKER })
            if (started.deny) throw new Error(started.deny)
            if (started.agentId) {
              mem.configuratorIds.add(started.agentId)
              mem.activeRuns.set(started.agentId, at)
              if (isApproval(line)) mem.approvedRuns.add(started.agentId)
            }
            return { text: 'started' }
          } catch (error) {
            await finishChat(t('msg.cantStart', { why: String((error as Error)?.message ?? error) }), 'system')
            return { text: 'failed' }
          }
        }

        case 'answer': {
          // The run is over: record what the files became, so Undo can tell later edits from its own.
          const dir = req.agentId ? mem.runDirs.get(req.agentId) : undefined
          if (dir) await recordAfter(dir)
          if (req.agentId) {
            mem.activeRuns.delete(req.agentId)
            mem.runDirs.delete(req.agentId)
            mem.approvedRuns.delete(req.agentId)
            mem.snappedRuns.delete(req.agentId)
          }
          if (!req.isCancelled) {
            const failed = req.reason === 'error' || req.reason === 'aborted'
            await finishChat(failed ? t('msg.endedEarly', { reason: req.reason }) : req.text || t('msg.noAnswer'), failed ? 'system' : 'assistant')
          }
          await refresh()
          return { text: 'ok' }
        }

        case 'cancel':
          for (const id of mem.configuratorIds) mem.cancelledIds.add(id)
          await finishChat(t('msg.stopped'), 'system')
          return { text: 'ok' }

        case 'pref': {
          const changed = { ...((await read($, sCore)).prefs), [req.key]: req.value }
          await update($, sCore, s => ({ ...s, prefs: changed }))
          await $.store.set('prefs', changed).catch(() => undefined)
          if (!changed.hints) await update($, sCore, s => ({ ...s, hint: null }))
          if (req.key === 'summaries' && req.value) void digestRun().catch(() => undefined)
          if (req.key === 'autopilot' && req.value) void call({ op: 'autopilot' }).catch(() => undefined)
          return { text: 'ok' }
        }

        case 'lang': {
          const choice = req.lang === 'auto' || (LANGS as readonly string[]).includes(req.lang) ? req.lang : 'auto'
          const changed = { ...((await read($, sCore)).prefs), lang: choice as Prefs['lang'] }
          await update($, sCore, s => ({ ...s, prefs: changed }))
          await $.store.set('prefs', changed).catch(() => undefined)
          await setLanguage(choice)
          await update($, sCore, s => ({ ...s, notice: null }))
          await refresh()
          return { text: 'ok' }
        }

        case 'update': {
          const snap = (await read($, sCore)).snap
          const ids = req.id ? [req.id] : (snap?.plugins ?? []).map(p => p.id)
          if (ids.length === 0) {
            await finish({ ok: false, message: t('upd.none') }, '')
            return { text: 'nothing' }
          }
          const backup = await snapshot(req.id ? `update ${req.id}` : 'update all plugins')
          if (!backup.ok) {
            await finish({ ok: false, message: t('msg.noBackup') }, '')
            return { text: 'failed' }
          }
          // The one place Pitwall starts a program, and only when the person pressed Update: the
          // marketplace and plugin machinery lives in `claude`, so it is asked to do it.
          const run = async (args: string[]) => {
            const go = (argv: string[]) =>
              $.process.run(argv, { timeoutMs: 120_000 }).catch((err: Error) => ({ exitCode: -1, stdout: '', stderr: String(err?.message ?? err) }))
            let result = await go(['claude', ...args])
            if (result.exitCode === -1 && (await $.env.get('OS')) === 'Windows_NT') result = await go(['cmd', '/c', 'claude', ...args])
            return result
          }
          if (!req.id) await run(['plugin', 'marketplace', 'update'])
          let changed = 0
          let same = 0
          const failures: string[] = []
          for (let i = 0; i < ids.length; i++) {
            const name = friendlyName(ids[i])
            await update($, sCore, s => ({ ...s, busy: t('busy.updating', { i: i + 1, n: ids.length, name }) }))
            const result = await run(['plugin', 'update', ids[i]])
            if (result.exitCode === -1) {
              await finish({ ok: false, message: t('upd.noCli') }, '')
              return { text: 'failed' }
            }
            const outcome = classifyUpdate(result.exitCode, `${result.stdout}\n${result.stderr}`)
            if (outcome === 'changed') changed++
            else if (outcome === 'same') same++
            else failures.push(t('upd.failure', { name, why: firstLine(result.stderr || result.stdout) }))
          }
          await recordAfter(backup.dir)
          const message = req.id
            ? failures[0] ?? t('upd.one', { name: friendlyName(ids[0]), result: changed ? '✔' : '=' })
            : `${t('upd.result', { changed, same, failed: failures.length })}${failures.length ? ` ${failures.slice(0, 2).join(' · ')}` : ''}`
          await finish({ ok: failures.length < ids.length, message }, req.id ? `update ${friendlyName(ids[0])}` : `update ${changed}`)
          return { text: 'ok' }
        }

        case 'clear':
          await update($, sTalk, s => ({ ...s, chat: [] }))
          await $.store.set('chat', []).catch(() => undefined)
          return { text: 'ok' }

        case 'accept':
        case 'dismiss': {
          const h = (await read($, sCore)).hint
          if (!h) return { text: 'none' }
          await update($, sCore, s => ({ ...s, hint: null }))
          if (req.op === 'dismiss') {
            const dismissed = ((await $.store.get('dismissed')) as string[] | undefined) ?? []
            await $.store.set('dismissed', [...dismissed, h.id].slice(-200))
            return { text: 'ok' }
          }
          return call(h.kind === 'plugin' ? { op: 'plugin', id: h.target, isOn: true } : { op: 'skill', name: h.target, mode: 'on' })
        }

        case 'status': {
          await refresh()
          const snap = (await read($, sCore)).snap
          if (!snap) return { text: t('msg.status.nothing') }
          const active = snap.plugins.filter(p => p.isOn)
          const heaviest = [...active].sort((a, b) => b.tokens - a.tokens).slice(0, 3)
          return {
            text: [
              t('msg.status.context', { pct: Math.round(snap.percent), used: fmtTok(snap.usedTokens), window: fmtTok(snap.window) }),
              t('msg.status.setup', { plugins: active.length, tokens: fmtTok(active.reduce((sum, p) => sum + p.tokens, 0)), listed: snap.skillTotals.listed, total: snap.skillTotals.total }),
              heaviest.length ? t('msg.status.heaviest', { list: heaviest.map(p => `${p.name} ${fmtTok(p.tokens)}`).join(', ') }) : '',
              describeSetup(snap).split('\n')[0] ?? '',
            ]
              .filter(Boolean)
              .join('\n'),
          }
        }
      }
    }

    mem.serve = serve
    await $.command.register({
      name: 'pitwall',
      description: 'Open Pitwall: what is loaded, what it costs, and the setup assistant',
      argumentHint: '[status | undo]',
    })
    // The first measurement runs in the background, so the session starts at once.
    void serve({ op: 'init' }).catch(() => undefined)
    $.clock.every(30_000, () => void serve({ op: 'flush' }))
    // The numbers on screen follow the chat: while it is in use the usage is read again every twenty
    // seconds, and a chat nobody has touched for ten minutes is left alone.
    $.clock.every(20_000, () => {
      void (async () => {
        const now = await $.clock.now()
        if (now - mem.activity < 10 * 60_000 && now - mem.lastMeasure > 15_000) await refresh(true)
      })().catch(() => undefined)
    })
    return next(e)
  })

  on('command.run', { command: 'pitwall' }, async (_$, e) => {
    const req = toReq(e.args)
    if ('error' in req) return { text: req.error }
    return call(req)
  })

  // The configurator is Pitwall's to start; the main model should not delegate to it.
  on('agent.offer', { agent: 'pitwall:configurator' }, () => ({ isOffered: false }))

  // ---- keeping the configurator on a short leash --------------------------

  on('tool.call', async ($, e, next) => {
    const agentId = (e as any).agentId as string | undefined
    if (agentId && (mem.configuratorIds.has(agentId) || !mem.otherIds.has(agentId))) {
      // Anything that goes wrong in here ends in a refusal for a call that writes: a hook
      // that throws is skipped by the engine, and the call would run without the leash.
      const writes = e.tool === 'Write' || e.tool === 'Edit' || e.tool === 'Bash'
      const refuse = (why: string) => ({ deny: `Pitwall: ${why}` })
      try {
        let isMine = mem.configuratorIds.has(agentId)
        if (!isMine) {
          // Asked of the engine, not remembered: a reload must not lose the leash.
          const known = await $.agent.list()
          isMine = known.some(a => a.id === agentId && a.type === CONFIGURATOR)
          if (isMine) mem.configuratorIds.add(agentId)
          else mem.otherIds.add(agentId)
        }
        if (isMine) {
          const verdict = judge(String(e.tool), e as any, { home: mem.home, tmp: mem.tmp, claudeDir: mem.claudeDir, approved: mem.approvedRuns.has(agentId) })
          if ('deny' in verdict) {
            await update($, sTalk, s => ({ ...s, trace: (list => [...list, `blocked: ${verdict.deny}`].slice(-6))(s.trace) }))
            return refuse(verdict.deny)
          }
          // An Edit of settings.json is judged on what the file becomes: a change inside an
          // existing hooks or permissions block counts as much as a new key.
          const target = String((e as any).file_path ?? '').replace(/\\/g, '/')
          if (e.tool === 'Edit' && !mem.approvedRuns.has(agentId) && /(^|\/)settings(\.local)?\.json$/i.test(target) && target.toLowerCase().startsWith(`${mem.claudeDir.toLowerCase()}/`)) {
            const current = (await $.fs.read(target)) as string
            const from = String((e as any).old_string ?? '')
            const to = String((e as any).new_string ?? '')
            const result = from === '' ? current : (e as any).replace_all ? current.split(from).join(to) : current.replace(from, () => to)
            const risk = result === current ? null : settingsEditRisk(current, result)
            if (risk) {
              await update($, sTalk, s => ({ ...s, trace: (list => [...list, 'blocked: that edit needs your go'].slice(-6))(s.trace) }))
              return refuse(`${risk} ${NEEDS_GO}`)
            }
          }
          if (mutates(String(e.tool), e as any) && !mem.snappedRuns.has(agentId)) {
            // No backup, no change: a call that would write is refused until the snapshot exists.
            const backup = await call({ op: 'snapshot', reason: 'configurator run', agentId }).catch(() => ({ text: 'failed' }))
            if (backup.text !== 'ok') {
              await update($, sTalk, s => ({ ...s, trace: (list => [...list, 'blocked: could not back up your settings first'].slice(-6))(s.trace) }))
              return refuse('your settings could not be backed up first, so this change was refused. Tell the user.')
            }
            mem.snappedRuns.add(agentId)
          }
          await update($, sTalk, s => ({ ...s, trace: (list => [...list, describeCall(e as any)].slice(-6))(s.trace) }))
        }
      } catch {
        if (writes) return refuse('this call could not be checked, so it was refused. Try again.')
      }
    }

    // Count it, in memory only: every call of the main conversation passes here, so it costs the host nothing.
    const now = await $.clock.now()
    mem.activity = now
    // A long turn grows the context call by call: read it again at most every twenty seconds.
    if (now - mem.lastMeasure > 20_000) void call({ op: 'refresh', light: true }).catch(() => undefined)
    track('tools', String(e.tool), now)
    if (e.tool === 'Agent' || e.tool === 'Task') track('agents', String((e as any).subagent_type ?? (e as any).subagentType ?? ''), now)
    return next(e)
  })

  on('skill.prompt', async ($, e, next) => {
    track('skills', e.skill, await $.clock.now())
    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    // The configurator ran as a background agent; its completion notice would wake
    // the main conversation. Its answer is in the Pitwall chat, so the notice stops here.
    if (e.origin.kind === 'task-notification' && e.text.includes(MARKER)) {
      return { drop: 'Pitwall: the configurator finished. Its answer is in the Pitwall chat.' }
    }
    mem.activity = await $.clock.now()
    if (e.origin.kind === 'composer' && ((await read($, sCore)).prefs).hints) {
      const match = bestMatch(e.text, mem.candidates)
      if (!match) {
        await update($, sCore, s => ({ ...s, hint: null }))
      } else {
        const dismissed = ((await $.store.get('dismissed')) as string[] | undefined) ?? []
        if (!dismissed.includes(match.candidate.id)) {
          const name = friendlyName(match.candidate.target)
          await update($, sCore, s => ({ ...s, hint: ({
            id: match.candidate.id,
            kind: match.candidate.kind,
            target: match.candidate.target,
            text: t('hint.text', { name, words: match.words.slice(0, 3).join(', ') }),
          }) }))
        }
      }
    }
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const agentId = (e as any).agentId as string | undefined
    if (agentId) {
      const isCancelled = mem.cancelledIds.delete(agentId)
      let isMine = mem.configuratorIds.has(agentId)
      if (!isMine && !mem.otherIds.has(agentId)) {
        isMine = (await $.agent.list()).some(a => a.id === agentId && a.type === CONFIGURATOR)
        if (isMine) mem.configuratorIds.add(agentId)
        else mem.otherIds.add(agentId)
      }
      if (isMine) await call({ op: 'answer', reason: e.reason, text: e.answer ?? '', agentId, isCancelled }).catch(() => undefined)
    } else {
      mem.activity = await $.clock.now()
      void call({ op: 'refresh' }).catch(() => undefined)
    }
    return next(e)
  })

  on('session.end', async (_$, e, next) => {
    await call({ op: 'flush' }).catch(() => undefined)
    return next(e)
  })

  // ---- drawing ------------------------------------------------------------

  // A desktop or a phone may give no column count: a sensible one stands in for it.
  const widthOf = (columns: unknown, fallback: number): number => (typeof columns === 'number' && Number.isFinite(columns) ? Math.max(20, columns) : fallback)

  // The fewest reads that draw the screen: a read is a round trip to the host, and a drawing
  // that waits on many of them gets slower with every press.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const core = await read($, sCore)
    if (e.props.hasSurvey || !core.prefs.showBand) return next(e)
    const act = makeAct(
      req => void call(req).catch(() => undefined),
      go => void update($, sNav, s => go(s)),
    )
    const data = { core, lang: mem.lang } as Data
    return Band({ ui: $.ui.resolve(e), width: widthOf(e.props.bodyColumns, 100), data, act, t, surface: e.surface, scope: 'global' })
  })

  on('ui.render', { component: 'Pane', requestId: 'pitwall' }, async ($, e) => {
    const ui = $.ui.resolve(e)
    try {
      const nav = await read($, sNav)
      const core = await read($, sCore)
      // Where this tab's changes land: a project tab writes the project's own settings, the Global tab
      // (and a chat with no project folder) the global ones.
      const scope: Scope = nav.tab === 'global' || !core.project ? 'global' : 'project'
      // Only the tabs that show the conversation or the activity read them.
      const talk = nav.tab === 'chat' ? await read($, sTalk) : { chat: [], isChatBusy: false, sent: 0, trace: [] }
      const live = nav.tab === 'activity' ? await read($, sLive) : { recent: [] }
      const data: Data = {
        nav,
        core,
        talk,
        live,
        lang: mem.lang,
        autoLang: mem.autoLang,
        ledger: scope === 'project' ? mem.pledger : mem.ledger,
        now: await $.clock.now(),
        version: mem.version,
        names: mem.names,
      }
      // Looking at the pane is activity, and a number older than half a minute is read again at once.
      mem.activity = data.now
      if (data.now - mem.lastMeasure > 30_000) void call({ op: 'refresh', light: true }).catch(() => undefined)
      const act = makeAct(
        req => void call(SCOPED.has(req.op) && !('scope' in req) ? ({ ...req, scope } as typeof req) : req).catch(() => undefined),
        go => void update($, sNav, s => go(s)),
      )
      return Pane({ ui, width: widthOf(e.props.bodyColumns, 72), data, act, t, surface: e.surface, scope })
    } catch (error) {
      // A drawing that throws would leave an empty pane. Say why, and offer a way back to a clean state.
      return Broken({
        ui,
        message: String((error as Error)?.message ?? error),
        t,
        onReset: () => void update($, sNav, () => ({ tab: 'home' as Tab, open: null, info: null, adv: null, tech: null, more: null, advOn: false, find: '', opt: false, keep: [], gtools: false })),
      })
    }
  })
}

