// What the configurator is told with each message. The agent itself (its
// rules, tools and limits) is defined in agents/configurator.md.

import type { ChatLine, Snapshot, UsageLedger } from '../types'
import { ago, fmtTok } from './format'

export const CONFIGURATOR = 'pitwall:configurator'
/** The agent's task label, which is also how its completion notice is recognised. */
export const MARKER = 'Pitwall configurator'

/**
 * Whether a message is a bare "go" to the assistant's proposal. Only such a
 * message lets the next run install code or change MCP servers; a request that
 * merely mentions installing something does not.
 */
export const isApproval = (text: string): boolean =>
  /^\s*(go|go ahead|yes|y|ok|okay|do it|proceed|approved?|vai|si|procedi)\s*[.!]*\s*$/i.test(text)

const clip = (text: string, max: number): string => (text.length > max ? `${text.slice(0, max)}…` : text)

/** What the history says, so "unused" is a fact the assistant was given and not a guess. */
export function describeUsage(snap: Snapshot | null, ledger: UsageLedger | undefined, now: number): string {
  if (!ledger) return ''
  const days = Math.floor((now - ledger.since) / 86_400_000)
  const used = Object.entries(ledger.skills)
    .sort((a, b) => b[1].n - a[1].n)
    .slice(0, 12)
    .map(([name, v]) => `${name} x${v.n} (${ago(v.last, now)} ago)`)
  const own = (snap?.skills ?? []).filter(s => s.isOwn)
  const never = own.filter(s => !ledger.skills[s.name]).map(s => s.name)
  const lines = [`Usage history: watched for ${days < 1 ? 'less than a day' : `${days} day${days === 1 ? '' : 's'}`}${days < 7 ? ' (too short to call anything unused)' : ''}.`]
  if (used.length) lines.push(`Skills used: ${used.join(', ')}.`)
  if (never.length) lines.push(`Own skills not used since watching began: ${never.join(', ')}.`)
  const limits = (snap?.limits ?? []).map(l => `${l.kind.replace('_', '-')} ${Math.round(l.percent)}%`)
  if (limits.length) lines.push(`Usage limits: ${limits.join(', ')}.`)
  return lines.join('\n')
}

export function describeSetup(snap: Snapshot | null): string {
  if (!snap) return 'Current setup: not measured yet.'
  const on = snap.plugins.filter(p => p.isOn)
  const off = snap.plugins.filter(p => !p.isOn)
  const lines = [
    `Context window: ${Math.round(snap.percent)}% used of ${fmtTok(snap.window)} (${snap.model || 'unknown model'}).`,
    `Plugins on (${on.length}): ${on.map(p => `${p.name} ~${fmtTok(p.tokens)}`).join(', ') || 'none'}.`,
    `Plugins off (${off.length}): ${off.map(p => p.name).join(', ') || 'none'}.`,
  ]
  const own = snap.skills.filter(s => s.isOwn)
  if (own.length) lines.push(`Own skills (${own.length}): ${own.map(s => `${s.name}[${s.mode}] ~${fmtTok(s.tokens)}`).join(', ')}.`)
  if (snap.mcp.length) lines.push(`MCP servers: ${snap.mcp.map(m => `${m.server} ~${fmtTok(m.tokens)}`).join(', ')}.`)
  const dupes = snap.plugins.filter(p => p.isDuplicate).map(p => p.id)
  if (dupes.length) lines.push(`Same plugin installed twice: ${dupes.join(', ')}.`)
  return lines.join('\n')
}

export function buildPrompt(
  text: string,
  history: ChatLine[],
  snap: Snapshot | null,
  ledger: UsageLedger | undefined,
  now: number,
  claudeDir: string,
  tmp: string,
  root: string,
): string {
  const tail = history
    .filter(l => l.role !== 'system')
    .slice(-6)
    .map(l => `${l.role === 'user' ? 'User' : 'You'}: ${clip(l.text, 500)}`)
  return [
    `User request:\n${text}`,
    describeSetup(snap),
    describeUsage(snap, ledger, now),
    `Config folder: ${claudeDir}`,
    `Temp folder (the only other place you may write, and where to clone repos): ${tmp}`,
    `Catalog of vetted add-ons: ${root}/catalog/catalog.json (read it before searching elsewhere).`,
    tail.length > 1 ? `Conversation so far:\n${tail.slice(0, -1).join('\n')}` : '',
  ]
    .filter(Boolean)
    .join('\n\n')
}

