// Small pure helpers for turning numbers into short, stable text.

let mark = '.'
/** The decimal mark fmtTok writes: "." in English, "," in the languages that write 9,6k. */
export const setDecimal = (decimal: string): void => {
  mark = decimal
}

/** 950 -> "950", 1234 -> "1.2k", 12400 -> "12k". */
export const fmtTok = (n: number): string => {
  if (!Number.isFinite(n) || n <= 0) return '0'
  if (n >= 10_000) return `${Math.round(n / 1000)}k`
  if (n >= 1000) return `${(n / 1000).toFixed(1).replace('.', mark)}k`
  return String(Math.round(n))
}

/** A share of the window for people: 0.04 -> "<0.1", 0.34 -> "0.3", 4.6 -> "5". */
export const fmtPct = (pct: number): string => {
  if (!Number.isFinite(pct) || pct <= 0) return '0'
  if (pct < 0.1) return '<0.1'
  if (pct < 1) return pct.toFixed(1).replace('.', mark)
  return String(Math.round(pct))
}

/** A fixed-width bar: `bar(40, 10)` -> "████░░░░░░". */
export const bar = (percent: number, width: number): string => {
  const clamped = Math.max(0, Math.min(100, percent))
  const filled = Math.round((clamped / 100) * width)
  return '█'.repeat(filled) + '░'.repeat(Math.max(0, width - filled))
}

/** How many terminal cells one character takes: CJK, Hangul and full-width forms take two. */
const cell = (code: number): number =>
  (code >= 0x1100 && code <= 0x115f) ||
  (code >= 0x2e80 && code <= 0xa4cf) ||
  (code >= 0xac00 && code <= 0xd7a3) ||
  (code >= 0xf900 && code <= 0xfaff) ||
  (code >= 0xfe30 && code <= 0xfe6f) ||
  (code >= 0xff00 && code <= 0xff60) ||
  (code >= 0xffe0 && code <= 0xffe6) ||
  (code >= 0x1f300 && code <= 0x1faff) ||
  (code >= 0x20000 && code <= 0x3fffd)
    ? 2
    : 1

/** The width of a text in terminal cells. */
export const cells = (text: string): number => {
  let n = 0
  for (const ch of text) n += cell(ch.codePointAt(0) ?? 0)
  return n
}

/** Cuts to `max` cells with an ellipsis. Counts cells, so a line of Chinese is cut where it fits. */
export const trunc = (text: string, max: number): string => {
  if (max <= 1) return [...text].slice(0, Math.max(0, max)).join('')
  if (cells(text) <= max) return text
  let out = ''
  let used = 0
  for (const ch of text) {
    const w = cell(ch.codePointAt(0) ?? 0)
    if (used + w > max - 1) break
    out += ch
    used += w
  }
  return `${out}…`
}

export const padEnd = (text: string, width: number): string => {
  const w = cells(text)
  return w >= width ? text : text + ' '.repeat(width - w)
}

export const padStart = (text: string, width: number): string => {
  const w = cells(text)
  return w >= width ? text : ' '.repeat(width - w) + text
}

/** "3s", "4m", "2h", "5d" since `then`. */
export const ago = (then: number, now: number): string => {
  const s = Math.max(0, Math.round((now - then) / 1000))
  if (s < 60) return `${s}s`
  if (s < 3600) return `${Math.round(s / 60)}m`
  if (s < 86_400) return `${Math.round(s / 3600)}h`
  return `${Math.round(s / 86_400)}d`
}

/** "2h10m", "45m", "3d": how long until an ISO time, or '' when it is unknown or past. */
export const until = (iso: string | undefined, now: number): string => {
  const at = iso ? Date.parse(iso) : NaN
  const s = Math.round((at - now) / 1000)
  if (!Number.isFinite(s) || s <= 0) return ''
  if (s < 3600) return `${Math.max(1, Math.round(s / 60))}m`
  if (s < 86_400) return `${Math.floor(s / 3600)}h${String(Math.round((s % 3600) / 60)).padStart(2, '0')}m`
  return `${Math.round(s / 86_400)}d`
}

export const plural = (n: number, one: string, many = `${one}s`): string => `${n} ${n === 1 ? one : many}`

export type Seg = { t: string; color?: string }

/** A stacked bar: each part gets cells in proportion to its tokens, whatever is left stays empty. */
/** The meters are drawn as lines: a heavy one for what is used over a light one for what is left. */
const FILL = '━'
const TRACK = '─'

export function stackBar(parts: { tokens: number; color: string }[], total: number, width: number): Seg[] {
  if (width <= 0) return []
  if (total <= 0) return [{ t: TRACK.repeat(width), color: 'subtle' }]
  const out: Seg[] = []
  let used = 0
  for (const part of parts) {
    if (part.tokens <= 0 || used >= width) continue
    const cells = Math.min(width - used, Math.max(1, Math.round((part.tokens / total) * width)))
    out.push({ t: FILL.repeat(cells), color: part.color })
    used += cells
  }
  if (used < width) out.push({ t: TRACK.repeat(width - used), color: 'subtle' })
  return out
}

/** A small meter: miniBar(3, 10, 5) -> "━──── " (a heavy line over a light one). At least one cell when there is anything. */
export const miniBar = (value: number, max: number, width: number): string => {
  const cells = value <= 0 || max <= 0 ? 0 : Math.max(1, Math.min(width, Math.round((value / max) * width)))
  return FILL.repeat(cells) + TRACK.repeat(width - cells)
}

/**
 * A repository as people write it ("owner/repo", "git+https://...git",
 * "git@github.com:o/r.git") turned into the one https URL a Link accepts, or
 * undefined. A bad URL would make the engine refuse the whole drawing.
 */
export function repoUrl(raw: unknown): string | undefined {
  if (typeof raw !== 'string') return undefined
  let s = raw.trim()
  // Plain ASCII only: a look-alike letter in a host name would pass for another site in a panel people trust.
  if (s === '' || !/^[!-~]+$/.test(s)) return undefined
  s = s.replace(/^git\+/, '')
  const ssh = s.match(/^git@([\w.-]+):(.+?)(?:\.git)?$/)
  if (ssh) s = `https://${ssh[1]}/${ssh[2]}`
  else if (/^github:/.test(s)) s = `https://github.com/${s.slice(7)}`
  else if (/^[\w.-]+\/[\w.-]+$/.test(s)) s = `https://github.com/${s}`
  s = s.replace(/\.git$/, '')
  try {
    const url = new URL(s)
    if (url.protocol !== 'https:' || url.username || url.password) return undefined
    const href = url.href
    return href.length <= 2048 && /^[!-~]+$/.test(href) ? href : undefined
  } catch {
    return undefined
  }
}

