// The configurator agent may reshape the user's Claude Code setup, so what it
// may run is decided here, before a tool runs. This is defense in depth, not a
// sandbox: it works on the text of a call. Shell commands are held to an
// allowlist (so an unknown program, an interpreter or a one-liner never runs),
// every file a command writes must be named by an absolute path under
// ~/.claude or the temp folder, and a refusal says why.

export type GuardContext = {
  /** The user's home folder, as the OS spells it. */
  home: string
  /** The temp folder. */
  tmp: string
  /** Claude Code's config folder when it is not ~/.claude (CLAUDE_CONFIG_DIR). */
  claudeDir?: string
  /** The person answered "go" to this run's proposal, so code from outside may be brought in. */
  approved?: boolean
}

const claudeDirOf = (ctx: GuardContext): string => ctx.claudeDir || `${ctx.home}/.claude`

export type Verdict = { allow: true } | { deny: string }

const norm = (path: string): string => path.replace(/\\/g, '/').replace(/\/+/g, '/')

/** Resolves `.` and `..` segments without touching the disk. */
const flatten = (path: string): string => {
  const out: string[] = []
  for (const part of norm(path).split('/')) {
    if (part === '..') out.pop()
    else if (part !== '.' && part !== '') out.push(part)
  }
  return (path.startsWith('/') ? '/' : '') + out.join('/')
}

const same = (a: string, b: string): boolean => a.toLowerCase() === b.toLowerCase()

const isUnder = (path: string, root: string): boolean => {
  const p = flatten(path)
  const r = flatten(root).replace(/\/$/, '')
  return p.length > r.length && same(p.slice(0, r.length), r) && p[r.length] === '/'
}

const SECRET_NAME = /(^|\/)(\.credentials(\.json)?|credentials(\.json)?|\.env(\..*)?|id_rsa|id_ed25519|\.netrc)$/i

/** Folders and files that hold other people's keys, not Claude Code's setup. */
const SENSITIVE = /(^|\/)(\.ssh|\.aws|\.gnupg|\.kube|\.azure|\.docker\/config\.json|\.config\/(gh|gcloud)|\.git-credentials|\.npmrc|\.pypirc|\.netrc|\.claude\.json|id_rsa|id_ed25519|Login Data|Cookies|Local State)(\/|$)/i

// ---- paths -----------------------------------------------------------------

/**
 * Turns a path as written into one that can be compared, or says why it cannot
 * be trusted: variables, UNC and device paths, alternate data streams, 8.3 short
 * names and names Windows trims all let a path mean something else than it says.
 */
function resolve(raw: string, ctx: GuardContext): { path: string } | { relative: true } | { deny: string } {
  let p = raw.trim()
  if (p === '') return { deny: 'No path given.' }
  if (/^\\\\|^\/\/|\\\\[?.]\\/.test(p)) return { deny: 'Network and device paths are not allowed.' }
  if (p === '~' || p.startsWith('~/') || p.startsWith('~\\')) p = ctx.home + p.slice(1)
  if (/[$%]|`/.test(p)) return { deny: 'Variables in paths are blocked: write the literal path.' }
  p = norm(p)
  // Git Bash spells C:\Users as /c/Users.
  p = p.replace(/^\/([a-zA-Z])\//, (_m, letter: string) => `${letter.toUpperCase()}:/`)
  if (/^[A-Za-z]:(?!\/)/.test(p)) return { deny: 'Drive-relative paths are not allowed.' }
  const rest = p.replace(/^[A-Za-z]:/, '')
  if (rest.includes(':')) return { deny: 'Alternate data streams are not allowed.' }
  for (const segment of p.split('/')) {
    if (/~\d/.test(segment)) return { deny: 'Short (8.3) names are not allowed: write the full name.' }
    if (segment !== '.' && segment !== '..' && /[. ]$/.test(segment)) return { deny: 'Names ending in a dot or a space are not allowed.' }
  }
  if (!p.startsWith('/') && !/^[A-Za-z]:\//.test(p)) return { relative: true }
  return { path: flatten(p) }
}

const roots = (ctx: GuardContext): string[] => [claudeDirOf(ctx), ctx.tmp, '/tmp']

/** Where a file may be written: under ~/.claude or the temp folder, by an absolute path. */
export function judgePath(path: string, ctx: GuardContext): Verdict {
  if (typeof path !== 'string' || path === '') return { deny: 'No path given.' }
  const r = resolve(path, ctx)
  if ('deny' in r) return r
  if ('relative' in r) return { deny: `Use an absolute path under ${norm(claudeDirOf(ctx))} or the temp folder.` }
  if (SECRET_NAME.test(r.path)) return { deny: 'Credential files are off limits.' }
  if (!roots(ctx).some(root => isUnder(r.path, root))) {
    return { deny: `Writes are limited to ${norm(claudeDirOf(ctx))} and the temp folder.` }
  }
  return { allow: true }
}

export const NEEDS_GO =
  'This brings in or removes code the user has not approved. Tell them what you would do, why, and the exact reverse command, then stop. It runs once they answer go.'

/** Folders in the config folder whose contents run, or steer the model, in later sessions. */
const CODE_DIRS = /^(hooks|plugins|skills|agents|commands|output-styles)(\/|$)/i
/** Settings keys that run programs, add permissions or reroute credentials. */
const RUNS_CODE_KEY = /"(hooks|statusLine|apiKeyHelper|mcpServers|env|permissions|enabledMcpjsonServers|extraKnownMarketplaces|awsAuthRefresh|awsCredentialExport|otelHeadersHelper)"\s*:/

/**
 * Where and what a call may write. On top of judgePath: Pitwall's own backups
 * are never editable, and without a go the call may not touch the folders that
 * hold code (hooks, plugins, skills, agents, commands), nor put a key that runs
 * code or widens permissions into settings.json. settings.json is changed with
 * a small Edit, never rewritten whole or by a shell command.
 */
export function judgeWrite(path: string, ctx: GuardContext, how: 'Write' | 'Edit' | 'shell', content = ''): Verdict {
  const base = judgePath(path, ctx)
  if ('deny' in base) return base
  const r = resolve(path, ctx)
  if (!('path' in r)) return base
  const dir = flatten(claudeDirOf(ctx))
  if (!isUnder(r.path, dir)) return { allow: true }
  const rel = r.path.slice(dir.length + 1)
  if (/^pitwall(\/|$)/i.test(rel)) return { deny: "Pitwall's own backups cannot be edited." }
  if (ctx.approved) return { allow: true }
  if (CODE_DIRS.test(rel)) return { deny: NEEDS_GO }
  if (/^settings(\.local)?\.json$/i.test(rel)) {
    if (how !== 'Edit') return { deny: 'Change settings.json with the Edit tool and a minimal edit, never by rewriting it or from a shell command.' }
    if (RUNS_CODE_KEY.test(content)) return { deny: NEEDS_GO }
  }
  return { allow: true }
}

/**
 * Reads are free inside the setup and the temp folder. Elsewhere only what a
 * configurator has no reason to want is refused, because it reads READMEs from
 * the internet, and a README can try to talk it into fetching a secret.
 */
export function judgeRead(path: string): Verdict {
  if (typeof path !== 'string' || path === '') return { allow: true }
  const flat = flatten(path)
  if (SECRET_NAME.test(flat) || SENSITIVE.test(flat)) return { deny: 'Keys, tokens and browser data are off limits.' }
  return { allow: true }
}

/** What a web fetch may carry: the page it asks for, not data it picked up on the way. */
export function judgeUrl(url: string): Verdict {
  let parsed: URL
  try {
    parsed = new URL(url)
  } catch {
    return { deny: 'Not a URL.' }
  }
  if (parsed.protocol !== 'https:') return { deny: 'Only https pages may be fetched.' }
  if (parsed.username || parsed.password) return { deny: 'URLs with credentials are blocked.' }
  if (/^(localhost|127\.|10\.|0\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.|\[?::|\[?f[cde])/i.test(parsed.hostname)) {
    return { deny: 'Local addresses are blocked.' }
  }
  if (parsed.search.length > 120 || /[A-Za-z0-9+/_-]{60,}/.test(`${parsed.pathname}${parsed.search}`)) {
    return { deny: 'A fetch that carries a long encoded string looks like data leaving, so it is blocked.' }
  }
  return { allow: true }
}

// ---- shell commands --------------------------------------------------------

/** Named refusals, checked first so the reason is specific. The allowlist below is the real gate. */
const BLOCKED: [RegExp, string][] = [
  [/\brm\s+(-\S+\s+)*-\S*[rR]/, 'Recursive deletes are blocked.'],
  [/\b(Remove-Item|ri|rd|rmdir|del|erase)\b[^\n]*(-Recurse|\/[sS]\b)/i, 'Recursive deletes are blocked.'],
  [/\bformat\s+[a-zA-Z]:/i, 'Formatting drives is blocked.'],
  [/\b(curl|wget|iwr|irm|Invoke-WebRequest|Invoke-RestMethod)\b[^|;&\n]*\|\s*(sh|bash|zsh|iex|Invoke-Expression|powershell|pwsh)\b/i, 'Piping a download into a shell is blocked.'],
  [/\b(iex|Invoke-Expression)\b/i, 'Invoke-Expression is blocked.'],
  [/\b(powershell|pwsh)(\.exe)?\b[^\n]*\s-(enc|encodedcommand|e)\b/i, 'Encoded PowerShell is blocked.'],
  [/\bsudo\b|\bsu\s+-|Start-Process\b[^\n]*-Verb\s+RunAs/i, 'Elevated commands are blocked.'],
  [/\bgit\s+(push|reset\s+--hard|clean\s+-\S*f|filter-branch)\b/i, 'Destructive or publishing git commands are blocked.'],
  [/\bnpm\s+publish\b|\bgh\s+(repo\s+delete|release\s+(create|delete)|pr\s+merge|api\s+(-X|--method)\s*(POST|PUT|PATCH|DELETE))/i, 'Publishing and remote writes are blocked.'],
  [/\b(npm|pnpm|yarn)\s+(i|install|add)\b[^\n]*(\s-g\b|--global)|\bnpx\b|\bpip3?\s+install\b|\bpipx\b|\buv\s+(tool|pip)\s+install\b/i, 'Package installers run unvetted code, so they are blocked: give the user the exact command instead.'],
  [/\breg\s+(add|delete|import)\b|\bsetx\b|\bnetsh\b|\bschtasks\s+\/create\b|\bcrontab\b|\bchmod\s+-R\b|\bchown\b/i, 'System configuration commands are blocked.'],
  [/\.credentials|gh\s+auth\s+token|printenv\b[^\n]*(KEY|TOKEN|SECRET)|\bcat\b[^\n]*\.claude\.json/i, 'Reading credentials is blocked.'],
  [/(\.ssh|\.aws|\.gnupg|\.kube|\.azure|\.git-credentials|\.npmrc|\.pypirc|\.netrc|id_rsa|id_ed25519)\b/i, 'Keys, tokens and browser data are off limits.'],
]

type Segment = { words: string[]; reads: string[]; writes: string[] }

/**
 * Splits a command into simple commands, respecting quotes, and refuses what
 * cannot be judged from text: variables, substitutions, subshells, heredocs,
 * background jobs and unbalanced quotes.
 */
function parse(command: string): { segments: Segment[] } | { error: string } {
  if (/[`$]|%[A-Za-z_]+%/.test(command)) return { error: 'Variables and substitutions are blocked: write the literal value.' }
  const segments: Segment[] = []
  let words: string[] = []
  let reads: string[] = []
  let writes: string[] = []
  let word = ''
  let hasWord = false
  let quote: string | null = null
  let pending: '>' | '<' | null = null

  const endWord = () => {
    if (!hasWord) return
    if (pending === '>') writes.push(word)
    else if (pending === '<') reads.push(word)
    else words.push(word)
    pending = null
    word = ''
    hasWord = false
  }
  const endSegment = () => {
    endWord()
    if (words.length || reads.length || writes.length) segments.push({ words, reads, writes })
    words = []
    reads = []
    writes = []
    pending = null
  }

  for (let i = 0; i < command.length; i++) {
    const c = command[i]
    if (quote) {
      if (c === quote) quote = null
      else word += c
      continue
    }
    if (c === '"' || c === "'") {
      quote = c
      hasWord = true
      continue
    }
    if (c === '(' || c === ')') return { error: 'Subshells and grouping are blocked.' }
    if (c === '\n') {
      endSegment()
      continue
    }
    if (/\s/.test(c)) {
      endWord()
      continue
    }
    if (c === ';') {
      endSegment()
      continue
    }
    if (c === '|') {
      endSegment()
      if (command[i + 1] === '|') i++
      continue
    }
    if (c === '&') {
      if (command[i + 1] === '&') {
        endSegment()
        i++
        continue
      }
      if (command[i + 1] !== '>') return { error: 'Background jobs are blocked.' }
      i++
      endWord()
      pending = '>'
      continue
    }
    if (c === '>' || c === '<') {
      if (c === '<' && command[i + 1] === '<') return { error: 'Heredocs are blocked: use the Write tool for file content.' }
      // A file descriptor glued to the operator ("2>") is not an argument.
      if (hasWord && /^\d+$/.test(word)) {
        word = ''
        hasWord = false
      } else endWord()
      while (command[i + 1] === c) i++
      if (c === '>' && command[i + 1] === '&') {
        i++
        while (/[\d-]/.test(command[i + 1] ?? '')) i++
        continue
      }
      pending = c
      continue
    }
    word += c
    hasWord = true
  }
  if (quote) return { error: 'Unbalanced quotes.' }
  endSegment()
  return { segments }
}

// Not here, because each can write a file of its own choosing: sort -o, uniq IN OUT, tree -o, file -C.
const READ_ONLY = new Set([
  'ls', 'dir', 'cat', 'type', 'head', 'tail', 'grep', 'rg', 'wc', 'echo', 'printf', 'pwd', 'diff',
  'jq', 'stat', 'which', 'where', 'cut', 'tr', 'basename', 'dirname', 'realpath', 'cd', 'true',
])
/** Commands that write: every path they name must be absolute and inside the allowed roots. */
const WRITERS = new Set(['cp', 'mv', 'mkdir', 'touch', 'rm', 'rmdir', 'tee'])
const FIND_BAD = new Set(['-delete', '-exec', '-execdir', '-ok', '-okdir', '-fprint', '-fprint0', '-fprintf', '-fls'])
const GIT_READ = new Set(['clone', 'ls-remote', 'log', 'show', 'ls-tree', 'rev-parse', 'status', 'diff', 'describe', 'cat-file', 'shortlog', 'rev-list', 'remote', 'tag', 'branch'])
const GIT_LIST_FLAGS = /^-(l|a|r|v|vv|-list|-all|-remotes|-verbose)$/
const CLAUDE_PLUGIN = new Set(['list', 'details', 'install', 'enable', 'disable', 'uninstall', 'update', 'validate', 'marketplace'])
const CLAUDE_MARKETPLACE = new Set(['add', 'list', 'update', 'remove'])
const CLAUDE_MCP = new Set(['list', 'get', 'add', 'remove'])

const flags = (args: string[]): string[] => args.filter(a => a.startsWith('-'))
const positional = (args: string[]): string[] => args.filter(a => !a.startsWith('-'))

function judgeGit(args: string[], ctx: GuardContext): Verdict {
  if (args.some(a => /^(-c|-C|--config|--config-env|--upload-pack|--receive-pack|--exec-path|--template|--git-dir|--work-tree|--output|--textconv|--ext-diff)(=|$)/.test(a))) {
    return { deny: 'That git option can run code or write elsewhere, so it is blocked.' }
  }
  const sub = args[0]
  if (!sub || !GIT_READ.has(sub)) return { deny: 'Only read-only git commands and `git clone` into the temp folder are allowed.' }
  const rest = args.slice(1)
  if ((sub === 'tag' || sub === 'branch' || sub === 'remote') && positional(rest).length > 0 && !rest.some(a => GIT_LIST_FLAGS.test(a))) {
    return { deny: `git ${sub} can only list here.` }
  }
  if (sub === 'clone') {
    const urls = rest.filter(a => /:\/\/|::/.test(a))
    if (urls.length !== 1 || !urls[0].startsWith('https://')) return { deny: 'git clone takes exactly one https:// URL.' }
    const last = rest[rest.length - 1]
    if (last === urls[0]) return { deny: 'git clone needs an explicit destination under the temp folder.' }
    return judgeWrite(last, ctx, 'shell')
  }
  return { allow: true }
}

function judgeGh(args: string[]): Verdict {
  const [sub, next] = args
  if (sub === 'api') {
    if (args.some(a => /^(-X|--method|-f|-F|--field|--raw-field|--input|-H|--header|--hostname)(=|$)/.test(a))) {
      return { deny: 'gh api is read-only here: no method, field, header or input options.' }
    }
    // A full URL would send the stored GitHub token to whatever host it names.
    if (args.some(a => /:\/\//.test(a))) return { deny: 'gh api takes an endpoint path, not a URL.' }
    return { allow: true }
  }
  const readOnly: Record<string, string[]> = { repo: ['view', 'list'], release: ['view', 'list'], issue: ['view', 'list'], pr: ['view', 'list'], search: ['repos', 'code', 'issues', 'prs'] }
  if (sub && readOnly[sub]?.includes(next)) return { allow: true }
  return { deny: 'Only read-only gh commands are allowed.' }
}

function judgeClaude(args: string[], ctx: GuardContext): Verdict {
  const [sub, next] = args
  if (sub === '--version' || sub === '-v') return { allow: true }
  if (sub === 'plugin' && CLAUDE_PLUGIN.has(next)) {
    if (next === 'marketplace' && !CLAUDE_MARKETPLACE.has(args[2])) return { deny: 'Unknown marketplace command.' }
    // Installing, removing or adding a source changes what code runs next session: that needs a go.
    const brings =
      next === 'install' || next === 'uninstall' || next === 'update' || (next === 'marketplace' && (args[2] === 'add' || args[2] === 'remove' || args[2] === 'update'))
    return brings && !ctx.approved ? { deny: NEEDS_GO } : { allow: true }
  }
  if (sub === 'mcp' && CLAUDE_MCP.has(next)) {
    return (next === 'add' || next === 'remove') && !ctx.approved ? { deny: NEEDS_GO } : { allow: true }
  }
  return { deny: 'Only `claude plugin ...` and `claude mcp ...` are allowed.' }
}

function judgeSegment(seg: Segment, ctx: GuardContext): Verdict {
  for (const target of seg.writes) {
    if (/^(\/dev\/null|nul)$/i.test(target)) continue
    const v = judgeWrite(target, ctx, 'shell')
    if ('deny' in v) return { deny: `Output redirect to "${target}" refused. ${v.deny}` }
  }
  for (const source of seg.reads) {
    const v = judgeRead(source)
    if ('deny' in v) return v
  }
  const [first, ...args] = seg.words
  if (first === undefined) return { allow: true }
  if (first.includes('=')) return { deny: 'Environment assignments before a command are blocked.' }
  const name = first.toLowerCase().replace(/^.*[\\/]/, '').replace(/\.(exe|cmd|bat)$/, '')

  for (const w of seg.words) {
    const v = judgeRead(w)
    if ('deny' in v) return v
  }

  if (name === 'grep' || name === 'rg') {
    // A recursive search from the config folder or above would read .credentials.json on the way.
    const dir = flatten(claudeDirOf(ctx))
    for (const p of positional(args).slice(1)) {
      const r = resolve(p, ctx)
      if ('path' in r && (r.path === '/' || r.path.toLowerCase() === dir.toLowerCase() || dir.toLowerCase().startsWith(`${r.path.toLowerCase().replace(/\/$/, '')}/`))) {
        return { deny: 'Search a subfolder, not the whole config folder or its parents: they hold credentials.' }
      }
    }
  }
  if (name === 'find') {
    return args.some(a => FIND_BAD.has(a)) ? { deny: 'find may not delete, execute or write.' } : { allow: true }
  }
  if (name === 'git') return judgeGit(args, ctx)
  if (name === 'gh') return judgeGh(args)
  if (name === 'claude') return judgeClaude(args, ctx)
  if (name === 'rg' && args.some(a => /^--pre(-glob)?(=|$)/.test(a))) return { deny: 'rg --pre runs a program for every file, so it is blocked.' }
  if (WRITERS.has(name)) {
    if (flags(args).some(a => a.includes('='))) return { deny: 'Write each path as its own argument, not as --option=path.' }
    // A short option takes the rest of its word as its value: -t/dir is --target-directory=/dir.
    for (const flag of flags(args)) {
      const glued = flag.startsWith('--') ? undefined : flag.match(/^-[A-Za-z]*?t(.+)$/)?.[1]
      if (glued !== undefined) {
        const v = judgeWrite(glued, ctx, 'shell')
        if ('deny' in v) return v
      }
    }
    for (const p of positional(args)) {
      const v = judgeWrite(p, ctx, 'shell')
      if ('deny' in v) return v
    }
    return { allow: true }
  }
  if (READ_ONLY.has(name)) return { allow: true }
  return { deny: `"${name}" is not on the configurator's list of commands. Use the Read, Edit and Write tools, or give the user the command to run.` }
}

export function judgeCommand(command: string, ctx: GuardContext): Verdict {
  if (typeof command !== 'string' || command.trim() === '') return { deny: 'Empty command.' }
  for (const [pattern, reason] of BLOCKED) {
    if (pattern.test(command)) return { deny: reason }
  }
  const parsed = parse(command)
  if ('error' in parsed) return { deny: parsed.error }
  for (const segment of parsed.segments) {
    const v = judgeSegment(segment, ctx)
    if ('deny' in v) return v
  }
  return { allow: true }
}

/**
 * Compares settings.json before and after an Edit and names the keys that run code
 * or widen what the model may do. The check is on the result of the edit, so a
 * change tucked inside an existing block is seen as well as a new key.
 */
export function settingsEditRisk(beforeText: string, afterText: string): string | null {
  let before: Record<string, unknown>
  let after: Record<string, unknown>
  try {
    before = JSON.parse(beforeText.trim() === '' ? '{}' : beforeText)
    after = JSON.parse(afterText)
  } catch {
    return 'The edit would leave settings.json unreadable.'
  }
  const risky = ['hooks', 'statusLine', 'apiKeyHelper', 'mcpServers', 'env', 'permissions', 'enabledMcpjsonServers', 'extraKnownMarketplaces', 'awsAuthRefresh', 'awsCredentialExport', 'otelHeadersHelper']
  const changed = risky.filter(k => JSON.stringify(before?.[k]) !== JSON.stringify(after?.[k]))
  return changed.length ? `It changes ${changed.join(', ')}, which run code or widen permissions.` : null
}

/** Whether a call can change anything on disk or in the plugin set: the cue to snapshot first. */
export function mutates(tool: string, input: Record<string, unknown>): boolean {
  if (tool === 'Write' || tool === 'Edit') return true
  if (tool !== 'Bash') return false
  const command = String(input.command ?? '').replace(/\d?>&\d|\d?>\s*\/dev\/null|\d?>\s*\$null/g, '')
  return (
    />/.test(command) ||
    /\b(cp|mv|mkdir|touch|tee|rm|rmdir|sed\s+-i|ln)\b/.test(command) ||
    /\bclaude\s+(plugin|mcp)\s+(install|uninstall|remove|enable|disable|update|add|marketplace)\b/.test(command)
  )
}

/** The one entry point: what the configurator asked to run. */
export function judge(tool: string, input: Record<string, unknown>, ctx: GuardContext): Verdict {
  if (tool === 'Bash') return judgeCommand(String(input.command ?? ''), ctx)
  if (tool === 'Write' || tool === 'Edit') {
    return judgeWrite(String(input.file_path ?? ''), ctx, tool, String(input.content ?? input.new_string ?? ''))
  }
  if (tool === 'Read') return judgeRead(String(input.file_path ?? ''))
  if (tool === 'Grep' || tool === 'Glob') return judgeRead(String(input.path ?? ''))
  if (tool === 'WebFetch') return judgeUrl(String(input.url ?? ''))
  return { allow: true }
}

