// "This prompt looks like something you switched off." Local and deterministic:
// no model call, nothing leaves the machine. It only fires when the match is
// strong, because a noisy hint teaches people to ignore hints.

export type Candidate = {
  id: string
  kind: 'plugin' | 'skill'
  target: string
  /** Name and description of the thing that is off. */
  text: string
}

export type Match = { candidate: Candidate; score: number; words: string[] }

const STOP = new Set(
  (
    'the a an and or of to in on for with without from by at as is are be this that these those it its you your ' +
    'can could should would will do does did not no yes use used using make made get got set add new all any ' +
    'how what why when where which who please help need want like just also than then there here into out over ' +
    'il lo la le gli un una uno di del della dei delle da in con su per tra fra che chi come cosa cui quando dove ' +
    'perche non si no ho ha hai hanno fai fare fammi puoi puo vorrei voglio questo questa questi queste quello quella'
  ).split(/\s+/),
)

export const tokenize = (text: string): string[] =>
  [
    ...new Set(
      text
        .toLowerCase()
        .normalize('NFD')
        .replace(/[̀-ͯ]/g, '')
        .split(/[^a-z0-9]+/)
        .filter(w => w.length >= 4 && !STOP.has(w)),
    ),
  ]

/**
 * Picks the candidate that shares the most words with the prompt, if it shares
 * enough: at least `minShared` and at least 30% of the prompt's (first twelve)
 * words. With four or more candidates, a word most of them contain says
 * nothing about any one and is ignored.
 */
export function bestMatch(prompt: string, candidates: Candidate[], minShared = 3): Match | null {
  const words = tokenize(prompt)
  const need = Math.max(minShared, Math.ceil(0.3 * Math.min(words.length, 12)))
  if (words.length < need || candidates.length === 0) return null
  const docs = candidates.map(c => new Set(tokenize(c.text)))
  const df = new Map<string, number>()
  for (const doc of docs) for (const w of doc) df.set(w, (df.get(w) ?? 0) + 1)

  let best: Match | null = null
  candidates.forEach((candidate, i) => {
    const shared = words.filter(w => docs[i].has(w) && (candidates.length < 4 || (df.get(w) ?? 0) <= candidates.length / 2))
    if (shared.length >= need && (!best || shared.length > best.score)) best = { candidate, score: shared.length, words: shared }
  })
  return best
}

