// What was used and when. Kept in `$.store`, never sent anywhere.

import type { SkillRow, UsageLedger } from '../types'

export type LedgerKind = 'skills' | 'agents' | 'tools'

const DAY = 86_400_000

export const emptyLedger = (now: number): UsageLedger => ({ since: now, skills: {}, agents: {}, tools: {} })

export function bump(ledger: UsageLedger, kind: LedgerKind, name: string, now: number): UsageLedger {
  const row = ledger[kind][name] ?? { n: 0, last: 0 }
  return { ...ledger, [kind]: { ...ledger[kind], [name]: { n: row.n + 1, last: now } } }
}

/** Reads a stored value back, tolerating a missing or older shape. */
export function revive(value: unknown, now: number): UsageLedger {
  const v = value as Partial<UsageLedger> | undefined
  if (!v || typeof v !== 'object') return emptyLedger(now)
  return {
    since: typeof v.since === 'number' ? v.since : now,
    skills: v.skills ?? {},
    agents: v.agents ?? {},
    tools: v.tools ?? {},
  }
}

/**
 * Adds what this session counted to what is stored. Other sessions write the same
 * store, so a session never writes back its whole ledger: it merges its own delta
 * into whatever is there now (counts add, the latest time wins, the earliest start stays).
 */
export function mergeLedger(stored: UsageLedger, delta: UsageLedger): UsageLedger {
  const merge = (a: UsageLedger[LedgerKind], b: UsageLedger[LedgerKind]) => {
    const out = { ...a }
    for (const [name, v] of Object.entries(b)) {
      const row = out[name]
      out[name] = row ? { n: row.n + v.n, last: Math.max(row.last, v.last) } : { ...v }
    }
    return out
  }
  return {
    since: Math.min(stored.since, delta.since || stored.since),
    skills: merge(stored.skills, delta.skills),
    agents: merge(stored.agents, delta.agents),
    tools: merge(stored.tools, delta.tools),
  }
}

/** Counts, most used first. */
export function top(ledger: UsageLedger, kind: LedgerKind, limit: number): { name: string; n: number; last: number }[] {
  return Object.entries(ledger[kind])
    .map(([name, v]) => ({ name, n: v.n, last: v.last }))
    .sort((a, b) => b.n - a.n || b.last - a.last)
    .slice(0, limit)
}

/**
 * The user's own skills that cost tokens and were not used for `days` days.
 * Returns nothing until the ledger has watched for `minWatchDays`: before that
 * every skill looks unused, and saying so would be a guess.
 */
export function unused(
  skills: SkillRow[],
  ledger: UsageLedger,
  now: number,
  days = 30,
  minWatchDays = 7,
): SkillRow[] {
  if (now - ledger.since < minWatchDays * DAY) return []
  // Only as far back as Pitwall has actually been watching.
  const window = Math.min(days, Math.floor((now - ledger.since) / DAY))
  return skills
    .filter(s => s.isOwn && s.mode === 'on' && s.tokens > 0)
    .filter(s => {
      const seen = ledger.skills[s.name]
      return !seen || now - seen.last > window * DAY
    })
    .sort((a, b) => b.tokens - a.tokens)
}

