// A plain-language summary of each tool, written once by a small model in the person's language and
// kept on their computer. The model also says which set a tool belongs to, which beats guessing from
// keywords. Pure: this builds the request and reads the reply; the hook makes the call.

import { CATEGORY_IDS, type CategoryId } from './categories'

export type DigestEntry = { /** the summary, one sentence */ s: string; /** the set */ c?: CategoryId; /** a hash of what it was written from */ h: string }
export type Digest = Record<string, DigestEntry>
export type DigestInput = { key: string; name: string; description: string; skills?: string[] }

/** A short stable hash (FNV-1a): enough to know that a description changed. */
export function hashOf(text: string): string {
  let h = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return h.toString(36)
}

const source = (item: DigestInput): string => `${item.name}|${item.description}|${(item.skills ?? []).slice(0, 12).join(',')}`

/** The tools that have no summary yet, or whose description changed since it was written. */
export const needsDigest = (items: DigestInput[], have: Digest): DigestInput[] => items.filter(item => have[item.key]?.h !== hashOf(source(item)))

export const SYSTEM =
  'You write short plain-language summaries of software tools for people who are not technical. ' +
  'You answer with one JSON object and nothing else: no code fence, no comment.'

/** The request for one batch of tools, in the language the person reads. */
export function digestPrompt(language: string, items: DigestInput[]): string {
  const tools = items.map(item => ({
    k: item.key,
    n: item.name,
    d: item.description.replace(/\s+/g, ' ').slice(0, 400),
    ...(item.skills?.length ? { skills: item.skills.slice(0, 12) } : {}),
  }))
  return (
    `Language of the summaries: ${language}.\n` +
    'For every tool below give:\n' +
    '- "s": one plain sentence, at most 90 characters, that says what the tool helps a person do. No jargon, no product words like plugin, MCP or token. Do not repeat the name.\n' +
    `- "c": the one set it fits best, exactly one of: ${CATEGORY_IDS.join(', ')}.\n` +
    'Answer as {"<k>": {"s": "...", "c": "..."}, ...} with every k from the list.\n\n' +
    `Tools:\n${JSON.stringify(tools)}`
  )
}

/** What a reply says, kept only for the tools that were asked about and only when it is well formed. */
export function parseDigest(text: string, asked: DigestInput[]): Digest {
  const out: Digest = {}
  const start = text.indexOf('{')
  const end = text.lastIndexOf('}')
  if (start < 0 || end <= start) return out
  let parsed: any
  try {
    parsed = JSON.parse(text.slice(start, end + 1))
  } catch {
    return out
  }
  for (const item of asked) {
    const entry = parsed?.[item.key]
    const s = typeof entry?.s === 'string' ? entry.s.replace(/\s+/g, ' ').trim() : ''
    if (s.length < 3 || s.length > 220) continue
    const c = (CATEGORY_IDS as readonly string[]).includes(entry?.c) ? (entry.c as CategoryId) : undefined
    out[item.key] = { s, c, h: hashOf(source(item)) }
  }
  return out
}

