// The "tools" a person sees: every add-on and every skill of their own, with a clean name, a
// plain size and the set it belongs to. Pure: it turns a snapshot into rows and groups, so the
// panel never shows a raw id, a token count or a flat list of forty lines.

import type { Layers, Scope, SkillMode, Snapshot } from '../types'
import { categorize, CATEGORY_IDS, JOBS, type CategoryId } from './categories'

/** What the model wrote about each tool: a summary, and the set it fits. */
export type Written = Record<string, { s: string; c?: string }>

export type Size = 'small' | 'medium' | 'large' | 'unknown'

export type Item = {
  /** `plugin:<id>` or `skill:<name>`, unique and stable. */
  key: string
  kind: 'plugin' | 'skill'
  /** The plugin id (`name@marketplace`) or the skill's folder name: what the switches act on. */
  id: string
  /** Fit to read: "Claude SEO", not "claude-seo@community". */
  name: string
  /** What to show: the plain summary when there is one, else what the tool says about itself. */
  description: string
  /** What the tool says about itself, untouched. */
  original: string
  repo?: string
  version?: string
  source?: string
  isOn: boolean
  /** `project` when this project's own settings set this tool; `global` when it follows the global setting. */
  origin: 'project' | 'global'
  /** Only for a skill of the person's own: how Claude may use it. */
  mode?: SkillMode
  /** What it takes now (0 while off), and what it takes when on, as far as it is known. */
  tokens: number
  weight: number
  /** `weight` as a percent of Claude's memory. */
  share: number
  size: Size
  skills: number
  agents: number
  category: CategoryId
}

export type Group = {
  id: CategoryId
  items: Item[]
  on: number
  /** What the items that are on take together, as a percent of Claude's memory. */
  share: number
}

/** Words that stay in capitals when a name is made readable. */
const ACRONYMS = new Set(['seo', 'ui', 'ux', 'ai', 'mcp', 'api', 'pdf', 'sql', 'css', 'html', 'tdd', 'cv', 'ocr', 'llm', 'sdk', 'cli', 'gsap', 'adhd', 'soc', 'siem', 'crm', 'hr', 'ios', 'json', 'csv', 'ssh', 'gpu', 'ml', 'cpu', 'ide', 'qa', 'ci', 'cd'])

/** "claude-seo@community" -> "Claude SEO"; "no-ai-slop" -> "No AI slop". */
export function friendlyName(raw: string): string {
  const parts = raw.split('@')[0].split(/[-_.\s]+/).filter(Boolean)
  if (parts.length === 0) return raw
  return parts
    .map((part, i) => {
      if (ACRONYMS.has(part.toLowerCase())) return part.toUpperCase()
      return i === 0 ? part.charAt(0).toUpperCase() + part.slice(1) : part.toLowerCase()
    })
    .join(' ')
}

const asSet = (c: string | undefined): CategoryId | undefined => ((CATEGORY_IDS as readonly string[]).includes(c ?? '') ? (c as CategoryId) : undefined)

/** Small, medium or large by the share of Claude's memory it takes; unknown when nothing is known. */
export function sizeOf(weight: number, window: number): Size {
  if (!(weight > 0)) return 'unknown'
  const pct = window > 0 ? (weight / window) * 100 : weight / 2000
  return pct < 0.3 ? 'small' : pct < 1.2 ? 'medium' : 'large'
}

const rank: Record<Size, number> = { large: 3, medium: 2, small: 1, unknown: 0 }
export const isHeavier = (a: Size, b: Size): boolean => rank[a] > rank[b]

/** Which settings a list of tools is read from: what this chat will get, or what every project inherits. */
export type View = { scope: Scope; layers: Layers | null }

/**
 * Every add-on and every skill of the person's own as one kind of row. `names` holds the skill
 * names an add-on carried the last time it was on, so a set stays the same while it is off. The
 * state is what this chat gets (the merged settings) unless the view is the global one, which reads
 * what the user's own settings say. `origin` says whether the project sets a tool itself.
 */
export function buildItems(snap: Snapshot, names: Record<string, string[]> = {}, written: Written = {}, view?: View): Item[] {
  const items: Item[] = []
  const layers = view?.layers ?? null
  const global = view?.scope === 'global' && layers !== null
  const setHere = (group: 'plugins' | 'skills', key: string): boolean => !global && layers !== null && (layers.local[group][key] !== undefined || layers.project[group][key] !== undefined)
  for (const p of snap.plugins) {
    const weight = p.isOn ? p.tokens : (p.lastTokens ?? 0)
    const isOn = global ? layers!.user.plugins[p.id] === true : p.isOn
    const carried = (p.skillNames && p.skillNames.length ? p.skillNames : names[p.id] ?? []).join(' ')
    const original = p.description ?? ''
    const w = written[`plugin:${p.id}`]
    items.push({
      key: `plugin:${p.id}`,
      kind: 'plugin',
      id: p.id,
      name: friendlyName(p.name),
      description: w?.s ?? original,
      original,
      repo: p.repo,
      version: p.version || undefined,
      source: p.marketplace || undefined,
      isOn,
      origin: setHere('plugins', p.id) ? 'project' : 'global',
      tokens: isOn ? p.tokens || weight : 0,
      weight,
      share: snap.window > 0 ? (weight / snap.window) * 100 : 0,
      size: sizeOf(weight, snap.window),
      skills: p.skills,
      agents: p.agents,
      category: asSet(w?.c) ?? categorize(p.name, original, carried),
    })
  }
  for (const s of snap.skills) {
    if (!s.isOwn) continue
    const weight = s.tokens > 0 ? s.tokens : (s.lastTokens ?? 0)
    const mode = (global ? layers!.user.skills[s.name] ?? 'on' : s.mode) as SkillMode
    const original = s.description ?? ''
    const w = written[`skill:${s.name}`]
    items.push({
      key: `skill:${s.name}`,
      kind: 'skill',
      id: s.name,
      name: friendlyName(s.name),
      description: w?.s ?? original,
      original,
      repo: s.repo,
      isOn: mode !== 'off',
      origin: setHere('skills', s.name) ? 'project' : 'global',
      mode,
      tokens: global ? (mode !== 'off' ? s.tokens || weight : 0) : s.tokens,
      weight,
      share: snap.window > 0 ? (weight / snap.window) * 100 : 0,
      size: sizeOf(weight, snap.window),
      skills: 0,
      agents: 0,
      category: asSet(w?.c) ?? categorize(s.name, original),
    })
  }
  return items
}

/** The sets, in a fixed order with "everything else" last, each with its items on top first. */
export function groupItems(items: Item[]): Group[] {
  const groups: Group[] = []
  for (const id of CATEGORY_IDS) {
    const mine = items
      .filter(item => item.category === id)
      .sort((a, b) => Number(b.isOn) - Number(a.isOn) || b.weight - a.weight || a.name.localeCompare(b.name))
    if (mine.length === 0) continue
    const on = mine.filter(item => item.isOn)
    groups.push({ id, items: mine, on: on.length, share: on.reduce((total, item) => total + item.share, 0) })
  }
  return groups
}

/** How many tools there are and how many are on. */
export const tally = (items: Item[]): { on: number; total: number } => ({ on: items.filter(i => i.isOn).length, total: items.length })

/** The tool that takes the most room of those that are on, if it takes enough to be worth saying. */
export function heaviest(items: Item[], minShare = 1): Item | undefined {
  const on = items.filter(i => i.isOn && i.kind === 'plugin')
  const top = on.sort((a, b) => b.share - a.share)[0]
  return top && top.share >= minShare ? top : undefined
}

/**
 * What switching to a kind of work changes: the tools whose state differs from what the job
 * wants, so the backup holds only what moves. A skill that is on is set to "on", one that is off to "off".
 */
export function jobChange(items: Item[], job: keyof typeof JOBS): { plugins: { id: string; isOn: boolean }[]; skills: { name: string; mode: 'on' | 'off' }[] } {
  const sets = JOBS[job] as readonly CategoryId[]
  const plugins: { id: string; isOn: boolean }[] = []
  const skills: { name: string; mode: 'on' | 'off' }[] = []
  for (const item of items) {
    // Whatever the job, the panel that sets it up stays on.
    if (item.kind === 'plugin' && item.id.startsWith('pitwall@')) continue
    const want = sets.includes(item.category)
    if (item.kind === 'plugin' && item.isOn !== want) plugins.push({ id: item.id, isOn: want })
    if (item.kind === 'skill' && (want ? item.mode !== 'on' : item.mode !== 'off')) skills.push({ name: item.id, mode: want ? 'on' : 'off' })
  }
  return { plugins, skills }
}

