// Turns what Claude Code reports (context breakdown, settings, installed
// plugins) into the plain-data snapshot every view draws. Pure: no `$` here,
// so it is tested with literals.

import type {
  Category,
  HookRow,
  LimitRow,
  McpRow,
  MemoryRow,
  PluginRow,
  SkillMode,
  SkillRow,
  Snapshot,
} from '../types'

export type RawInput = {
  now: number
  /** `$.session.usage({ breakdown })`. */
  usage?: any
  /** `$.settings.read()`. */
  settings?: Record<string, any>
  /** `installed_plugins.json` -> `plugins`. */
  installed?: Record<string, unknown[]>
  /** Directory names under ~/.claude/skills that hold a SKILL.md. */
  ownSkills?: string[]
  /** What each plugin (`plugin:<id>`) and skill (`skill:<name>`) says about itself. */
  meta?: Record<string, { description?: string; repo?: string }>
  errors?: string[]
}

const MODES: readonly SkillMode[] = ['on', 'name-only', 'user-invocable-only', 'off']
const sum = (rows: { tokens: number }[]): number => rows.reduce((total, row) => total + (row.tokens || 0), 0)

const asMode = (value: unknown): SkillMode =>
  MODES.includes(value as SkillMode) ? (value as SkillMode) : 'on'

export function buildSnapshot(raw: RawInput): Snapshot {
  const breakdown = raw.usage?.context?.breakdown
  const settings = raw.settings ?? {}
  const enabled: Record<string, unknown> = settings.enabledPlugins ?? {}
  const overrides: Record<string, unknown> = settings.skillOverrides ?? {}
  const listed: any[] = breakdown?.skills?.skillFrontmatter ?? []
  const agentRows: any[] = breakdown?.agents ?? []
  const mcpTools: any[] = breakdown?.mcpTools ?? []

  const ids = [...new Set([...Object.keys(raw.installed ?? {}), ...Object.keys(enabled)])].sort()
  const nameCount: Record<string, number> = {}
  for (const id of ids) nameCount[id.split('@')[0]] = (nameCount[id.split('@')[0]] ?? 0) + 1

  const plugins: PluginRow[] = ids.map(id => {
    const [name, marketplace = ''] = id.split('@')
    const mine = listed.filter(s => s.pluginName === name)
    const agents = agentRows.filter(a => String(a.agentType).startsWith(`${name}:`))
    const first: any = (raw.installed?.[id] ?? [])[0] ?? {}
    const isOn = enabled[id] === true
    return {
      id,
      name,
      marketplace,
      version: String(first.version ?? ''),
      isOn,
      skills: isOn ? mine.length : 0,
      agents: isOn ? agents.length : 0,
      tokens: isOn ? sum(mine) + sum(agents) : 0,
      skillNames: isOn ? mine.slice(0, 60).map(s => String(s.name)) : [],
      isDuplicate: nameCount[name] > 1,
      ...raw.meta?.[`plugin:${id}`],
    }
  })

  const own = new Set(raw.ownSkills ?? [])
  const skills: SkillRow[] = []
  const seen = new Set<string>()
  for (const s of listed) {
    if (s.pluginName) continue
    seen.add(s.name)
    skills.push({
      name: s.name,
      source: s.source,
      tokens: s.tokens || 0,
      mode: asMode(overrides[s.name]),
      isOwn: own.has(s.name),
      ...(own.has(s.name) ? raw.meta?.[`skill:${s.name}`] : undefined),
    })
  }
  // A skill switched off is no longer listed, but it must stay on screen to be switched back on.
  for (const name of own) {
    if (seen.has(name)) continue
    skills.push({ name, source: 'userSettings', tokens: 0, mode: asMode(overrides[name]), isOwn: true, ...raw.meta?.[`skill:${name}`] })
  }
  skills.sort((a, b) => b.tokens - a.tokens || a.name.localeCompare(b.name))

  const categories: Category[] = (breakdown?.categories ?? [])
    .filter((c: any) => c.kind === 'used' || c.kind === 'deferred' || c.kind === 'free')
    .map((c: any) => ({ name: String(c.name), tokens: c.tokens || 0, kind: String(c.kind) }))

  const byServer = new Map<string, McpRow>()
  for (const t of mcpTools) {
    const row = byServer.get(t.serverName) ?? { server: String(t.serverName), tools: 0, tokens: 0, deferred: 0 }
    row.tools += 1
    // A tool whose schema loads on demand costs nothing until it is searched for.
    if (t.isLoaded === false) row.deferred += 1
    else row.tokens += t.tokens || 0
    byServer.set(t.serverName, row)
  }

  const memory: MemoryRow[] = (breakdown?.memoryFiles ?? []).map((m: any) => ({
    path: String(m.path),
    kind: String(m.type),
    tokens: m.tokens || 0,
  }))

  const hooks: HookRow[] = []
  for (const [event, groups] of Object.entries<any>(settings.hooks ?? {})) {
    for (const group of Array.isArray(groups) ? groups : []) {
      for (const hook of group?.hooks ?? []) {
        hooks.push({ event, matcher: String(group?.matcher ?? ''), command: String(hook?.command ?? hook?.type ?? '') })
      }
    }
  }

  const limits: LimitRow[] = (raw.usage?.rateLimits ?? []).map((r: any) => ({
    kind: String(r.kind),
    percent: Number(r.percentUsed) || 0,
    resetsAt: r.resetsAt,
  }))

  return {
    at: raw.now,
    model: String(breakdown?.model ?? ''),
    window: breakdown?.rawMaxTokens ?? raw.usage?.context?.window ?? 0,
    usedTokens: breakdown?.totalTokens ?? raw.usage?.context?.tokens ?? 0,
    percent: breakdown?.percentage ?? raw.usage?.context?.percent ?? 0,
    categories,
    plugins,
    skills,
    skillTotals: {
      total: breakdown?.skills?.totalSkills ?? listed.length,
      listed: breakdown?.skills?.includedSkills ?? listed.length,
      tokens: breakdown?.skills?.tokens ?? sum(listed),
    },
    agents: agentRows.map(a => ({ name: String(a.agentType), source: String(a.source), tokens: a.tokens || 0 })),
    mcp: [...byServer.values()].sort((a, b) => b.tokens - a.tokens),
    memory,
    hooks,
    limits,
    costUsd: raw.usage?.cost?.usd,
    hasUsage: breakdown !== undefined,
    errors: raw.errors ?? [],
  }
}

/** The tokens every enabled plugin adds to each session, in total. */
export const pluginTokens = (snap: Snapshot): number => sum(snap.plugins)

/** What the person's own setup adds to every session: plugins, their skills, MCP servers and memory files. */
export const setupTokens = (snap: Snapshot): number =>
  pluginTokens(snap) + sum(snap.memory) + sum(snap.mcp) + sum(snap.skills.filter(s => s.isOwn))

/** Skills a user can reasonably switch: their own files, not a plugin's. */
export const ownSkills = (snap: Snapshot): SkillRow[] => snap.skills.filter(s => s.isOwn)

