// Where a chat runs: the project folder, who it is, and what kind of work it looks like.
//
// A project is the folder `$.session.cwd()` names. Its setup lives in the project's own
// `.claude/settings.local.json`, the file Claude Code reads for that folder and keeps out of git.
// Everything here is pure: the controller hands it paths and file names and gets plain answers.

import type { JobId } from './categories'
import { hashOf } from './digest'

const slashes = (path: string): string => path.replace(/\\/g, '/').replace(/\/+$/, '')

/** A short, stable id for a folder, the same on every OS and for either slash. */
export const projectKey = (root: string): string => hashOf(slashes(root).toLowerCase())

/** The name a person knows the folder by. */
export const projectName = (root: string): string => slashes(root).split('/').pop() || root

/** The settings file that holds a project's own setup. */
export const localSettings = (root: string): string => `${slashes(root)}/.claude/settings.local.json`

/**
 * Whether a folder can have settings of its own. The home folder and Claude Code's own config
 * folder cannot: their `.claude/settings.json` *is* the global file, so there is no project there.
 */
export function hasOwnSettings(root: string, configDir: string, home = ''): boolean {
  const r = slashes(root).toLowerCase()
  const c = slashes(configDir).toLowerCase()
  if (r === '' || r === c || `${r}/.claude` === c) return false
  if (home !== '' && r === slashes(home).toLowerCase()) return false
  return true
}

export type Guess = { job: JobId; evidence: string[] }

type Rule = { job: JobId; names?: string[]; ext?: string[]; dirs?: string[]; weight: number }

// Each rule is a marker and what it is worth. A file name, an extension or a folder counts once
// per kind of marker, so a thousand source files do not outweigh one manifest.
const CODE: Rule[] = [
  { job: 'coding', weight: 3, names: ['package.json', 'tsconfig.json', 'pyproject.toml', 'requirements.txt', 'setup.py', 'cargo.toml', 'go.mod', 'pom.xml', 'build.gradle', 'build.gradle.kts', 'gemfile', 'composer.json', 'makefile', 'cmakelists.txt', 'deno.json', 'mix.exs', 'pubspec.yaml', 'dockerfile', 'package.swift'] },
  { job: 'coding', weight: 2, ext: ['.py', '.ts', '.tsx', '.js', '.jsx', '.rs', '.go', '.java', '.rb', '.php', '.c', '.cpp', '.cs', '.kt', '.swift', '.sln', '.csproj'] },
  { job: 'coding', weight: 1, dirs: ['src', 'lib', 'app', 'tests', 'test', 'cmd', 'pkg'] },
]
const WEB: Rule[] = [
  { job: 'web', weight: 3, names: ['index.html', 'next.config.js', 'next.config.mjs', 'next.config.ts', 'astro.config.mjs', 'astro.config.ts', 'gatsby-config.js', '_config.yml', 'hugo.toml', 'wp-config.php'] },
  { job: 'web', weight: 2, ext: ['.html', '.css', '.scss'] },
  { job: 'web', weight: 2, dirs: ['wp-content', 'public', 'static'] },
]
const WRITING: Rule[] = [
  { job: 'writing', weight: 3, ext: ['.tex', '.docx', '.odt', '.rtf'] },
  { job: 'writing', weight: 2, dirs: ['chapters', 'manuscript', 'thesis', 'tesi', 'capitoli', 'draft', 'drafts'] },
  { job: 'writing', weight: 1, ext: ['.md', '.txt'] },
]
const RESEARCH: Rule[] = [
  { job: 'research', weight: 3, ext: ['.ipynb', '.bib', '.parquet', '.rds', '.sav'] },
  { job: 'research', weight: 2, names: ['environment.yml', 'renv.lock'] },
  { job: 'research', weight: 1, ext: ['.csv'], dirs: ['data', 'dataset', 'datasets', 'papers', 'notebooks'] },
]
const DESIGN: Rule[] = [
  { job: 'design', weight: 3, ext: ['.fig', '.sketch', '.psd', '.ai', '.xd', '.indd'] },
  { job: 'design', weight: 2, dirs: ['mockups', 'assets', 'design', 'brand'] },
  { job: 'design', weight: 1, ext: ['.svg'] },
]
const BUSINESS: Rule[] = [
  { job: 'business', weight: 3, ext: ['.xlsx', '.xls', '.pptx', '.key', '.numbers'] },
  { job: 'business', weight: 1, ext: ['.docx'] },
]

const RULES = [...CODE, ...WEB, ...WRITING, ...RESEARCH, ...DESIGN, ...BUSINESS]
/** When two kinds tie, the first one here wins. */
const ORDER: JobId[] = ['coding', 'web', 'research', 'writing', 'design', 'business']
/** A guess needs at least this much evidence, or nothing is said. */
const MIN_SCORE = 3

/**
 * What kind of work the files in a project's root suggest, or nothing when they do not say. Folders
 * come with a trailing slash. A website often has a package.json too, so web wins over coding once
 * it has real evidence of its own: the web set carries the coding set with it.
 */
export function guessKind(entries: string[]): Guess | undefined {
  const names = entries.map(e => e.toLowerCase())
  const score: Record<string, { points: number; evidence: string[] }> = {}
  for (const rule of RULES) {
    const hits = entries.filter((raw, i) => {
      const n = names[i]
      const isDir = n.endsWith('/')
      const bare = isDir ? n.slice(0, -1) : n
      if (rule.names?.includes(bare) && !isDir) return true
      if (rule.dirs?.includes(bare) && isDir) return true
      return !isDir && !!rule.ext?.some(e => bare.endsWith(e))
    })
    if (hits.length === 0) continue
    const row = (score[rule.job] ??= { points: 0, evidence: [] })
    row.points += rule.weight
    for (const h of hits) if (row.evidence.length < 3 && !row.evidence.includes(h)) row.evidence.push(h.replace(/\/$/, ''))
  }
  const ranked = ORDER.filter(job => score[job]).sort((a, b) => score[b].points - score[a].points || ORDER.indexOf(a) - ORDER.indexOf(b))
  const top = ranked[0]
  if (!top || score[top].points < MIN_SCORE) return undefined
  if (top === 'coding' && score.web && score.web.points >= MIN_SCORE) return { job: 'web', evidence: score.web.evidence }
  return { job: top, evidence: score[top].evidence }
}

