// Planning, without effects. Claude Code's mod rules keep `$` inside the hooks,
// so everything that can be decided from plain data is decided here and tested
// with literals; the hooks only read, ask this file what to do, and write.

import type { SkillMode } from '../types'
import { repoUrl } from './format'
import type { Req } from './session'

export type Plan<T> = { error: string } | T

export const SKILL_NAME = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,100}$/
export const PLUGIN_ID = /^[A-Za-z0-9][A-Za-z0-9._-]{0,80}@[A-Za-z0-9][A-Za-z0-9._-]{0,80}$/
export const MODES: readonly SkillMode[] = ['on', 'name-only', 'user-invocable-only', 'off']

/** Files a snapshot keeps: what Pitwall's own actions, and the configurator, can change. */
export const SNAPSHOT_FILES = ['settings.json', 'CLAUDE.md', 'plugins/installed_plugins.json', 'plugins/known_marketplaces.json']

export const parseSub = (args: string): { sub: string; rest: string } => {
  const text = args.trim()
  const space = text.search(/\s/)
  return space < 0 ? { sub: text.toLowerCase(), rest: '' } : { sub: text.slice(0, space).toLowerCase(), rest: text.slice(space + 1).trim() }
}

// ---------- skills ------------------------------------------------------

export type SkillPlan = { text: string; reason: string; message: string }

/**
 * What a settings file becomes when these skills change mode. Leaves everything else as it was.
 * "On" is the default, so it normally removes the key; in a project file it has to be written when
 * the global setting would otherwise show through (`keepOn` names those skills).
 */
export function planSkillModes(settingsText: string, changes: { name: string; mode: string }[], keepOn: string[] = []): Plan<SkillPlan> {
  if (changes.length === 0) return { error: 'Nothing to change.' }
  for (const c of changes) {
    if (!SKILL_NAME.test(c.name)) return { error: `"${c.name}" is not a skill name.` }
    if (!MODES.includes(c.mode as SkillMode)) return { error: `"${c.mode}" is not a skill mode.` }
  }
  let current: any
  try {
    current = JSON.parse(settingsText === '' ? '{}' : settingsText)
  } catch {
    return { error: 'Could not read settings.json as JSON, so it was left alone.' }
  }
  if (current === null || typeof current !== 'object' || Array.isArray(current)) {
    return { error: 'settings.json is not an object, so it was left alone.' }
  }
  const overrides: Record<string, string> = { ...(current.skillOverrides ?? {}) }
  for (const c of changes) {
    if (c.mode === 'on' && !keepOn.includes(c.name)) delete overrides[c.name]
    else overrides[c.name] = c.mode
  }
  if (Object.keys(overrides).length === 0) delete current.skillOverrides
  else current.skillOverrides = overrides
  const label = changes.map(c => `${c.name}=${c.mode}`).join(', ')
  return {
    text: serialize(settingsText, current),
    reason: `skills: ${label.length > 160 ? `${label.slice(0, 157)}...` : label}`,
    message: changes.length === 1 ? `${changes[0].name} is now ${changes[0].mode}.` : `${changes.length} skills updated.`,
  }
}

// ---------- plugins -----------------------------------------------------


// ---------- snapshots ---------------------------------------------------

/**
 * One key a change touched, so Undo can put back that key and nothing else. `file` is `settings.json`
 * for the global file, or the absolute path of a project's own settings file.
 */
export type KeyChange = { file: string; path: string[]; had: boolean; before?: unknown }

export type Manifest = {
  reason: string
  at: number
  /** `global`, or the key of the project the change was made in: Undo walks back one scope at a time. */
  scope: string
  files: string[]
  /** Set for a switch Pitwall made itself: Undo reverts these keys in the file as it is now. */
  changes: KeyChange[]
  /** Fingerprints of the files when the change was done; Undo leaves a file edited since alone. */
  after: Record<string, string>
}

export type SnapshotInfo = Manifest & { dir: string; isRestored: boolean }

export const snapshotDir = (claudeDir: string, now: number, seq = 0): string =>
  `${claudeDir}/pitwall/snapshots/${new Date(now).toISOString().replace(/[:.]/g, '-')}${seq > 0 ? `-${String(seq).padStart(3, '0')}` : ''}`

export function parseManifest(text: string): Manifest | null {
  try {
    const m = JSON.parse(text)
    return {
      reason: String(m.reason ?? ''),
      at: Number(m.at) || 0,
      scope: typeof m.scope === 'string' && m.scope !== '' ? m.scope : 'global',
      files: Array.isArray(m.files) ? m.files.map(String) : [],
      changes: Array.isArray(m.changes) ? m.changes.filter((c: any) => c && typeof c.file === 'string' && Array.isArray(c.path)) : [],
      after: m.after && typeof m.after === 'object' ? m.after : {},
    }
  } catch {
    return null
  }
}

/** A short fingerprint, enough to notice that a file changed. */
export function fingerprint(text: string): string {
  let h = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return `${text.length}:${h.toString(16)}`
}

// ---------- editing settings.json without rewriting it ------------------

/** The indent, line ending and final newline a file already uses. */
function detectFormat(text: string): { indent: string; eol: string; finalNewline: boolean } {
  const indent = text.match(/^([ \t]+)"/m)?.[1] ?? '  '
  return { indent, eol: text.includes('\r\n') ? '\r\n' : '\n', finalNewline: /\n$/.test(text) || text.trim() === '' }
}

/** Writes an edited object back in the file's own style, so a diff shows only what changed. */
export function serialize(original: string, value: unknown): string {
  const { indent, eol, finalNewline } = detectFormat(original)
  const body = JSON.stringify(value, null, indent).replace(/\n/g, eol)
  return finalNewline ? `${body}${eol}` : body
}

const readObject = (text: string): Record<string, any> | null => {
  try {
    const v = JSON.parse(text)
    return v !== null && typeof v === 'object' && !Array.isArray(v) ? v : null
  } catch {
    return null
  }
}

/** What a plugin switch will touch: the one key in `enabledPlugins`. */
export function pluginKey(settingsText: string, id: string, file = 'settings.json'): KeyChange[] {
  const had = readObject(settingsText)?.enabledPlugins?.[id]
  return [{ file, path: ['enabledPlugins', id], had: had !== undefined, before: had }]
}

/** settings.json with one plugin switched, in the file's own style. Nothing else in it moves. */
export function setPluginEnabled(settingsText: string, id: string, isOn: boolean): Plan<{ text: string }> {
  if (!PLUGIN_ID.test(id)) return { error: 'Not a plugin id.' }
  const root = readObject(settingsText === '' ? '{}' : settingsText)
  if (!root) return { error: 'Could not read settings.json as a JSON object, so it was left alone.' }
  const enabled = root.enabledPlugins && typeof root.enabledPlugins === 'object' ? root.enabledPlugins : {}
  root.enabledPlugins = { ...enabled, [id]: isOn }
  return { text: serialize(settingsText, root) }
}

/** What a skill-mode change will touch: one key per skill in `skillOverrides`. */
export function skillKeys(settingsText: string, names: string[], file = 'settings.json'): KeyChange[] {
  const overrides = readObject(settingsText)?.skillOverrides ?? {}
  return names.map(name => ({ file, path: ['skillOverrides', name], had: overrides[name] !== undefined, before: overrides[name] }))
}

/** The keys a set of tools touches in a file: `plugin:<id>` and `skill:<name>`, as an Item names them. */
export function toolKeys(settingsText: string, keys: string[], file = 'settings.json'): KeyChange[] {
  const ids = keys.filter(k => k.startsWith('plugin:')).map(k => k.slice(7))
  const names = keys.filter(k => k.startsWith('skill:')).map(k => k.slice(6))
  return [...ids.flatMap(id => pluginKey(settingsText, id, file)), ...skillKeys(settingsText, names, file)]
}

/** The file with those tool keys removed, so the project follows the global value again. Nothing else moves. */
export function clearTools(settingsText: string, keys: string[]): Plan<{ text: string }> {
  const root = readObject(settingsText === '' ? '{}' : settingsText)
  if (!root) return { error: 'The settings file is not a JSON object, so it was left alone.' }
  for (const key of keys) {
    const group = key.startsWith('plugin:') ? 'enabledPlugins' : key.startsWith('skill:') ? 'skillOverrides' : ''
    const name = key.slice(key.indexOf(':') + 1)
    if (group && root[group] && typeof root[group] === 'object') delete root[group][name]
  }
  for (const group of ['skillOverrides', 'enabledPlugins']) {
    const value = root[group]
    if (value && typeof value === 'object' && Object.keys(value).length === 0) delete root[group]
  }
  return { text: serialize(settingsText, root) }
}

/** Puts each key back as it was in the file as it is now, leaving every other key alone. */
export function revertKeys(settingsText: string, changes: KeyChange[], file = 'settings.json'): Plan<{ text: string }> {
  const root = readObject(settingsText === '' ? '{}' : settingsText)
  if (!root) return { error: 'The settings file is not a JSON object, so it was left alone.' }
  for (const c of changes) {
    if (c.file !== file || c.path.length < 1 || c.path.some(k => k === '__proto__' || k === 'constructor' || k === 'prototype')) continue
    const leaf = c.path[c.path.length - 1]
    let at: Record<string, any> = root
    let reachable = true
    for (const key of c.path.slice(0, -1)) {
      if (at[key] === null || typeof at[key] !== 'object') {
        if (!c.had) {
          reachable = false
          break
        }
        at[key] = {}
      }
      at = at[key]
    }
    if (!reachable) continue
    if (c.had) at[leaf] = c.before
    else delete at[leaf]
  }
  for (const group of ['skillOverrides', 'enabledPlugins']) {
    const value = root[group]
    if (value && typeof value === 'object' && Object.keys(value).length === 0) delete root[group]
  }
  return { text: serialize(settingsText, root) }
}

/** The snapshot an Undo restores: the newest that has files and was not already restored. */
export const nextUndo = (list: SnapshotInfo[], scope = 'global'): SnapshotInfo | undefined =>
  [...list].sort((a, b) => b.at - a.at || (a.dir < b.dir ? 1 : -1)).find(s => !s.isRestored && s.files.length > 0 && (s.scope ?? 'global') === scope)

// ---------- activity ----------------------------------------------------

const baseName = (path: unknown): string => String(path ?? '').split(/[\\/]/).pop() ?? ''

export function describeCall(e: Record<string, any>): string {
  switch (e.tool) {
    case 'Bash':
      return `Bash ${String(e.command ?? '').trim().slice(0, 40)}`
    case 'Read':
    case 'Edit':
    case 'Write':
      return `${e.tool} ${baseName(e.file_path)}`
    case 'Agent':
    case 'Task':
      return `Agent ${e.subagent_type ?? e.subagentType ?? ''}`.trim()
    default:
      return String(e.tool ?? 'tool')
  }
}

/** What changed since the session started, and so waits for the next one. */
export function diffPending(
  baseline: { enabled: Record<string, unknown>; overrides: Record<string, unknown> } | null,
  settings: Record<string, any>,
): string[] {
  if (!baseline) return []
  const out: string[] = []
  const enabled: Record<string, unknown> = settings.enabledPlugins ?? {}
  for (const id of new Set([...Object.keys(baseline.enabled), ...Object.keys(enabled)])) {
    if ((baseline.enabled[id] === true) !== (enabled[id] === true)) out.push(`${id.split('@')[0]} ${enabled[id] === true ? 'on' : 'off'}`)
  }
  const overrides: Record<string, unknown> = settings.skillOverrides ?? {}
  for (const name of new Set([...Object.keys(baseline.overrides), ...Object.keys(overrides)])) {
    if (baseline.overrides[name] !== overrides[name]) out.push(`skill ${name} ${overrides[name] ?? 'on'}`)
  }
  return out
}

/** The words a hint matches against, from a plugin.json or the top of a SKILL.md. */
export function parseDescription(path: string, raw: string): string {
  try {
    if (path.endsWith('.json')) {
      const d = JSON.parse(raw)
      return `${d.description ?? ''} ${Array.isArray(d.keywords) ? d.keywords.join(' ') : ''}`.trim()
    }
    return (raw.match(/^---\r?\n([\s\S]*?)\r?\n---/)?.[1] ?? '').replace(/\s+/g, ' ').slice(0, 600)
  } catch {
    return ''
  }
}

// ---------- what a plugin or a skill says about itself ------------------

/** One value from a SKILL.md frontmatter block: plain, quoted, or folded with ">" or "|". */
export function frontmatterValue(raw: string, key: string): string | undefined {
  const block = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/)?.[1]
  if (!block) return undefined
  const lines = block.split(/\r?\n/)
  const head = new RegExp(`^${key}\\s*:\\s*`)
  const at = lines.findIndex(l => head.test(l))
  if (at < 0) return undefined
  let value = lines[at].replace(head, '')
  if (/^[>|][+-]?$/.test(value)) {
    const parts: string[] = []
    for (const l of lines.slice(at + 1)) {
      if (l.trim() !== '' && /^\S/.test(l)) break
      parts.push(l.trim())
    }
    value = parts.join(' ')
  }
  value = value.replace(/^(["'])([\s\S]*)\1$/, '$2').replace(/\s+/g, ' ').trim()
  return value || undefined
}

export type Meta = { description?: string; repo?: string }

/** A skill's description and, when its frontmatter names one, its repository. */
export function parseSkillMeta(raw: string): Meta {
  const repo = repoUrl(
    frontmatterValue(raw, 'repository') ?? frontmatterValue(raw, 'homepage') ?? frontmatterValue(raw, 'source') ?? frontmatterValue(raw, 'url'),
  )
  return { description: frontmatterValue(raw, 'description')?.slice(0, 400), repo }
}

/** A plugin's description and repository from its plugin.json, else the marketplace it came from. */
export function parsePluginMeta(raw: string, marketplaceRepo?: string): Meta {
  try {
    const d = JSON.parse(raw)
    const repo = repoUrl(typeof d.repository === 'string' ? d.repository : d.repository?.url) ?? repoUrl(d.homepage) ?? marketplaceRepo
    return { description: typeof d.description === 'string' ? d.description.slice(0, 400) : undefined, repo }
  } catch {
    return { repo: marketplaceRepo }
  }
}

/** Where a marketplace came from, as one https URL, from known_marketplaces.json. */
export function marketplaceRepo(known: Record<string, any>, name: string): string | undefined {
  const source = known?.[name]?.source
  if (!source) return undefined
  if (source.source === 'github') return repoUrl(source.repo)
  return repoUrl(source.url ?? source.repo)
}

export type UpdateOutcome = 'changed' | 'same' | 'failed'

/** What `claude plugin update <id>` did, from its exit code and what it printed. */
export function classifyUpdate(exitCode: number, output: string): UpdateOutcome {
  if (exitCode !== 0 || /✘|failed to/i.test(output)) return 'failed'
  return /already|up to date|latest/i.test(output) ? 'same' : 'changed'
}

/** The first line that says something, cut short. */
export const firstLine = (text: string): string => text.split(/\r?\n/).map(l => l.trim()).find(Boolean)?.slice(0, 160) ?? ''

/** `/pitwall <words>` as a request, or why it is not one. */
export function toReq(args: string): Plan<Req> {
  const { sub, rest } = parseSub(args)
  switch (sub) {
    case '':
    case 'open':
      return { op: 'open' }
    case 'refresh':
      return rest === 'light' ? { op: 'refresh', light: true } : { op: 'refresh' }
    case 'init':
    case 'flush':
    case 'status':
    case 'undo':
    case 'dim':
    case 'cancel':
    case 'clear':
    case 'accept':
    case 'dismiss':
      return { op: sub }
    case 'plugin': {
      const [verb = '', id = ''] = rest.split(/\s+/)
      if ((verb !== 'on' && verb !== 'off') || !PLUGIN_ID.test(id)) return { error: 'Usage: /pitwall plugin on|off <name@marketplace>' }
      return { op: 'plugin', id, isOn: verb === 'on' }
    }
    case 'skill': {
      const [name = '', mode = ''] = rest.split(/\s+/)
      if (!SKILL_NAME.test(name) || !MODES.includes(mode as SkillMode)) return { error: 'Usage: /pitwall skill <name> on|name-only|user-invocable-only|off' }
      return { op: 'skill', name, mode }
    }
    case 'ask':
      return rest ? { op: 'ask', text: rest } : { error: 'Usage: /pitwall ask <what you want changed>' }
    case 'update': {
      if (rest === '') return { op: 'update' }
      return PLUGIN_ID.test(rest) ? { op: 'update', id: rest } : { error: 'Usage: /pitwall update [name@marketplace]' }
    }
    default:
      return { error: 'Usage: /pitwall [status | undo | update | plugin on|off <id> | skill <name> <mode> | ask <text>]' }
  }
}

