// What Pitwall remembers between two events of one session, without `$`.
//
// A hot reload of the module resets this; everything that matters is in
// `$.state` or `$.store`, and these are caches the next refresh rebuilds.

import type { Layers, ProjectInfo, Scope, UsageLedger } from '../types'
import type { Lang } from './i18n'
import type { Candidate } from './hints'
import { bump, emptyLedger, type LedgerKind } from './ledger'

/** What the rest of the mod asks the controller to do. See `serve` in hooks/register.tsx. */
export type Req =
  | { op: 'refresh'; light?: boolean }
  | { op: 'dim'; auto?: boolean; scope?: Scope }
  | { op: 'tighten' }
  | { op: 'undo'; scope?: Scope }
  | { op: 'init' | 'flush' | 'status' | 'cancel' | 'clear' | 'accept' | 'dismiss' | 'open' }
  | { op: 'plugin'; id: string; isOn: boolean; scope?: Scope }
  | { op: 'skill'; name: string; mode: string; scope?: Scope }
  | { op: 'set'; plugins: { id: string; isOn: boolean }[]; skills: { name: string; mode: string }[]; label: string; scope?: Scope; profile?: string }
  /** Go back to the global setup: drop the project's own value of these tools, or of all of them. */
  | { op: 'inherit'; keys?: string[] }
  /** The person said the starting profile does not fit this project. */
  | { op: 'decline' }
  | { op: 'ask'; text: string }
  | { op: 'lighter' }
  | { op: 'update'; id?: string }
  | { op: 'lang'; lang: string }
  | { op: 'pref'; key: 'showBand' | 'hints' | 'summaries' | 'autopilot'; value: boolean }
  | { op: 'snapshot'; reason: string; agentId?: string }
  | { op: 'answer'; reason: string; text: string; agentId?: string; isCancelled?: boolean }

export type Serve = (req: Req) => Promise<{ text: string }>

export const mem = {
  /** The controller. Set by session.start; a hot reload clears it until session.start runs again. */
  serve: null as Serve | null,
  home: '',
  tmp: '',
  /** The language the mod speaks, decided at session.start and changed in Setup. */
  lang: 'en' as Lang,
  /** What the system asked for, which "Automatic" in Setup means. */
  autoLang: 'en' as Lang,
  /** What each plugin and skill says about itself, read once per file. */
  meta: new Map<string, { description?: string; repo?: string; text: string }>(),
  /** Pitwall's own version, for the About line. */
  version: '',
  /** What each plugin and skill cost the last time it was counted, kept in the store. */
  costs: null as Record<string, number> | null,
  /** The skill names each add-on carried the last time it was on, kept in the store. */
  names: {} as Record<string, string[]>,
  /** What the model wrote about each tool, per language, as stored. */
  digest: {} as Record<string, Record<string, { s: string; c?: string; h: string }>>,
  digestBusy: false,
  /** Skill folders already known to hold a SKILL.md, so a refresh does not ask again for each. */
  skillOk: new Set<string>(),
  /** `~/.claude`, or CLAUDE_CONFIG_DIR when set: the one folder Pitwall reads and writes. */
  claudeDir: '',
  /** The snapshot each configurator run took, so its end can record what the files became. */
  runDirs: new Map<string, string>(),
  /** Runs started by a "go": only these may install, uninstall or change MCP servers. */
  approvedRuns: new Set<string>(),
  /** Configurator runs that have not reported back (id to start time), even if the person stopped waiting. */
  activeRuns: new Map<string, number>(),
  /** What the store held when read, plus this session's counts: what History shows. */
  ledger: emptyLedger(0) as UsageLedger,
  /** Only what this session counted since the last flush: the part it may add to the store. */
  delta: emptyLedger(0) as UsageLedger,
  isLedgerDirty: false,
  /** The folder this chat runs in; null when it cannot have settings of its own. */
  project: null as ProjectInfo | null,
  /** What the store holds for this project, plus this session's counts, and only this session's part. */
  pledger: emptyLedger(0) as UsageLedger,
  pdelta: emptyLedger(0) as UsageLedger,
  candidates: [] as Candidate[],
  baseline: null as { enabled: Record<string, unknown>; overrides: Record<string, unknown> } | null,
  /** What the last full measurement found, so a light one only asks for the usage again. */
  inputs: null as { installed: Record<string, any[]>; ownSkills: string[]; meta: Record<string, { description?: string; repo?: string }>; layers: Layers } | null,
  /** When the last measurement started, and the last time anything happened in this chat. */
  lastMeasure: 0,
  activity: 0,
  /** The refreshes run one after the other; this is the last one queued. */
  refreshing: null as Promise<void> | null,
  /** The requests that change files run one after the other; this is the last one queued. */
  queue: null as Promise<void> | null,
  snapSeq: 0,
  descriptions: new Map<string, string>(),
  snappedRuns: new Set<string>(),
  configuratorIds: new Set<string>(),
  otherIds: new Set<string>(),
  cancelledIds: new Set<string>(),
}

export function track(kind: LedgerKind, name: string, now: number): void {
  if (!name) return
  mem.ledger = bump(mem.ledger, kind, name, now)
  mem.delta = bump(mem.delta.since ? mem.delta : emptyLedger(now), kind, name, now)
  if (mem.project) {
    mem.pledger = bump(mem.pledger, kind, name, now)
    mem.pdelta = bump(mem.pdelta.since ? mem.pdelta : emptyLedger(now), kind, name, now)
  }
  mem.isLedgerDirty = true
}

/** A run counts as live for a quarter of an hour: a run whose end was never seen must not block Undo for good. */
export const RUN_TTL = 15 * 60_000
export function liveRuns(now: number): number {
  for (const [id, started] of mem.activeRuns) if (now - started > RUN_TTL) mem.activeRuns.delete(id)
  return mem.activeRuns.size
}

/** True once, when there is something to write. */
export function takeDirty(): boolean {
  const was = mem.isLedgerDirty
  mem.isLedgerDirty = false
  return was
}

export const RECENT_MAX = 30
export const CHAT_MAX = 40

