// What the person sees when a drawing throws: the reason, and a way back. Without it a drawing
// that fails leaves an empty pane, and a bad state (a group that cannot draw) would trap them there.

import type { T } from '../i18n'

export function Broken({ ui, message, t, onReset }: { ui: any; message: string; t: T; onReset: () => void }) {
  const { Box, Text, Button } = ui
  return (
    <Box flexDirection="column">
      <Text wrap="wrap">{t('broken.text')}</Text>
      <Text dimColor wrap="wrap">{message.slice(0, 300)}</Text>
      <Text> </Text>
      <Button key="reset" label={t('broken.reset')} onPress={onReset} />
    </Box>
  )
}

