// What a drawing is given. Views are pure: they get plain data and a set of
// closures (`act`) built by the hook, so none of them ever holds `$`.

import type { Core, Live, Nav, Scope, SkillMode, Tab, Talk, UsageLedger } from '../../types'
import type { Lang, T } from '../i18n'

export type Data = {
  nav: Nav
  core: Core
  talk: Talk
  live: Live
  /** The language in use, and the one the system asked for, for the Auto choice. */
  lang: Lang
  autoLang: Lang
  /** What the tab being drawn counts: this project's usage on a project tab, everyone's on the Global tab. */
  ledger: UsageLedger
  now: number
  /** Pitwall's own version, for the About line. */
  version: string
  /** The skill names each add-on carried the last time it was on, so its set stays put while it is off. */
  names: Record<string, string[]>
}

export type Act = {
  tab: (tab: Tab) => void
  /** Open one set of tools, or close it when it is the open one. */
  open: (id: string) => void
  /** Show or hide the details of one tool. */
  info: (key: string) => void
  /** Open one advanced section, or close it. */
  adv: (id: string) => void
  /** Open or close the Optimize plan on Home. */
  opt: (open: boolean) => void
  /** Leave one step of the plan out, or put it back. */
  keep: (key: string) => void
  /** Ask the assistant to propose a shorter version of the instructions. */
  tighten: () => void
  /** Expand or fold the advanced part of Settings. */
  advAll: () => void
  /** Search the tools by name or by what they do; an empty text ends the search. */
  find: (text: string) => void
  /** Show a set in full, or only its first tools. */
  more: (id: string) => void
  /** Show or hide a tool's technical details. */
  tech: (key: string) => void
  plugin: (id: string, isOn: boolean) => void
  skill: (name: string, mode: SkillMode) => void
  /** Switch several tools at once: one backup, one change, one Undo. */
  set: (change: { plugins: { id: string; isOn: boolean }[]; skills: { name: string; mode: SkillMode }[]; label: string; profile?: string }) => void
  /** Go back to the global setup: drop this project's own value of these tools, or of all of them. */
  inherit: (keys?: string[]) => void
  /** The starting profile does not fit this project. */
  decline: () => void
  /** Show or hide the tools of every project on the Global tab. */
  gtools: () => void
  dim: () => void
  undo: () => void
  ask: (text: string) => void
  cancel: () => void
  clear: () => void
  accept: () => void
  dismiss: () => void
  /** Open the panel. */
  show: () => void
  pref: (key: 'showBand' | 'hints' | 'summaries' | 'autopilot', value: boolean) => void
  /** Open Chat and ask the assistant to make the setup lighter. */
  lighter: () => void
