  update: (id?: string) => void
  lang: (lang: string) => void
}

/** `scope` is where this tab's changes land: the project's own settings, or the global ones. */
export type ViewContext = { ui: any; width: number; data: Data; act: Act; t: T; surface: string; scope: Scope }

