// The pane: five tabs, one body, one footer. Opened by the line above the prompt, `/pitwall`, or a tip.
//
// The tab you are on is the one accent-colored button on the terminal; the others are plain dim
// text that light up under the pointer. A desktop draws its own buttons, so there the tab you
// are on is marked with a dot and the others are dim. Below the tabs, each tab is a stack of
// rounded cards (see kit.tsx), and the footer is a hairline (on the terminal) with the status and
// Undo under it. The tabs wrap onto a second line when the pane is narrow.

import type { Tab } from '../../types'
import { trunc } from '../format'
import type { Key } from '../i18n'
import { C } from '../theme'
import { Activity } from './activity'
import { Chat } from './chat'
import type { ViewContext } from './context'
import { Home } from './home'
import { flow, rule } from './kit'
import { Global } from './global'
import { primary } from './style'
import { Tools } from './tools'

const TABS: { id: Tab; label: Key }[] = [
  { id: 'home', label: 'tab.home' },
  { id: 'tools', label: 'tab.tools' },
  { id: 'chat', label: 'tab.chat' },
  { id: 'activity', label: 'tab.activity' },
  { id: 'global', label: 'tab.global' },
]

export function Pane(ctx: ViewContext) {
  const { Box, Text, Button } = ctx.ui
  const { nav, core } = ctx.data
  const { busy, notice, pending } = core
  const { t, width, surface } = ctx
  const body =
    nav.tab === 'tools' ? Tools(ctx) : nav.tab === 'chat' ? Chat(ctx) : nav.tab === 'activity' ? Activity(ctx) : nav.tab === 'global' ? Global(ctx) : Home(ctx)
  const line = rule(ctx.ui, surface, width)
  const roomy = surface === 'terminal' ? 0 : 1
  // Where this tab's changes land, in one line under the tabs: the project, everywhere, or (when the
  // chat has no project folder of its own) the fact that everything is everywhere.
  const project = core.project
  const where =
    nav.tab === 'global' || nav.tab === 'chat'
        ? flow(ctx.ui, [<Text color={C.info}>{'●'}</Text>, <Text bold>{t('scope.global')}</Text>])
        : project
          ? flow(ctx.ui, [<Text color={C.info}>{'●'}</Text>, <Text bold>{t('scope.project', { name: project.name })}</Text>, <Text dimColor wrap="wrap">{t('scope.projectHint')}</Text>])
          : <Text dimColor wrap="wrap">{t('scope.none')}</Text>

  return (
    <Box flexDirection="column">
      {flow(
        ctx.ui,
        [
          <Text color={C.brand} bold>
            {'◆'}
          </Text>,
          ...TABS.map(item =>
            nav.tab === item.id ? (
              <Button
                key={`tab:${item.id}`}
                label={surface === 'terminal' ? t(item.label) : `• ${t(item.label)}`}
                variant={primary(surface)}
                onPress={() => ctx.act.tab(item.id)}
              />
            ) : (
              <Button key={`tab:${item.id}`} label={t(item.label)} plain dimColor onPress={() => ctx.act.tab(item.id)} />
            ),
          ),
        ],
        1,
      )}
      {line}
      {where ? <Box marginTop={roomy}>{where}</Box> : null}
      <Box flexDirection="column" marginTop={roomy}>
        {body}
      </Box>
      {line}
      {busy && <Text color={C.info} wrap="wrap">{`◌ ${busy}`}</Text>}
      {!busy && core.digesting && <Text dimColor wrap="wrap">{`◌ ${t('digest.working')}`}</Text>}
      {!busy && notice && <Text wrap="wrap">{`● ${trunc(notice, Math.max(60, width * 2))}`}</Text>}
      {pending.length > 0 && (
        <Text color={C.warn} wrap="wrap">
          {`▲ ${t('foot.pending', { n: pending.length })}`}
        </Text>
      )}
      <Box marginTop={roomy} flexWrap="wrap" columnGap={1}>
        <Box>
          <Text color={C.accent}>{'↶ '}</Text>
          <Button key="undo" label={t('foot.undo')} plain dimColor onPress={() => ctx.act.undo()} />
        </Box>
        <Text dimColor wrap="wrap">{t('foot.undoHint')}</Text>
      </Box>
    </Box>
  )
}

