// Sorts a tool (an add-on or one of the person's skills) into a set by what it is for, so the
// panel can show "Writing and tone" or "Images and vision" instead of one long list. Pure and
// local: it reads the words a tool uses about itself, with no model call. A tool that matches
// nothing goes to "Everything else", and the assistant in Chat can still reorganise on request.

export const CATEGORY_IDS = ['writing', 'code', 'design', 'vision', 'research', 'web', 'docs', 'security', 'organize', 'setup', 'business', 'other'] as const
export type CategoryId = (typeof CATEGORY_IDS)[number]

/**
 * Word stems per set. A stem of four letters or more matches any word that starts with it
 * ("humaniz" matches "humanizer"); a shorter one must match the whole word. When a word fits
 * stems of several sets, the longest stem wins ("marketplace" is setup, "market" is web).
 */
const STEMS: Record<Exclude<CategoryId, 'other'>, string[]> = {
  writing: ['writ', 'prose', 'tone', 'humaniz', 'human', 'slop', 'edit', 'copy', 'copywrit', 'grammar', 'translat', 'voice', 'essay', 'blog', 'article', 'rewrit', 'style', 'terse', 'concise', 'verbos', 'speak', 'caveman', 'letter', 'draft', 'sentence', 'paragraph', 'wording'],
  code: ['code', 'coding', 'debug', 'bug', 'test', 'refactor', 'git', 'github', 'commit', 'typescript', 'javascript', 'python', 'rust', 'api', 'develop', 'programm', 'tdd', 'lint', 'compil', 'script', 'function', 'repo', 'pull', 'engineer', 'software', 'senior', 'react', 'node', 'sql', 'database', 'backend', 'frontend'],
  design: ['design', 'ui', 'ux', 'interface', 'layout', 'brand', 'logo', 'css', 'figma', 'typograph', 'color', 'colour', 'animat', 'scroll', 'landing', 'diagram', 'architect', 'mockup', 'prototype', 'gsap', 'theme', 'visual'],
  vision: ['image', 'imag', 'vision', 'video', 'ocr', 'photo', 'picture', 'camera', 'diffusion', 'segment', 'screenshot', 'draw', 'pixel', 'multimodal', 'illustrat', 'render', 'graphic'],
  research: ['research', 'scien', 'data', 'dataset', 'analys', 'statist', 'paper', 'literatur', 'biolog', 'chemi', 'genom', 'genes', 'genetic', 'cell', 'cells', 'protein', 'molecul', 'clinical', 'medic', 'physic', 'quantum', 'math', 'citation', 'academ', 'thesis', 'arxiv', 'pubmed', 'learning', 'neural', 'forecast', 'bioinformat', 'graph', 'knowledge', 'experiment', 'lab', 'drug', 'health'],
  web: ['seo', 'web', 'website', 'site', 'search', 'market', 'ads', 'social', 'sitemap', 'schema', 'backlink', 'analytic', 'content', 'keyword', 'browser', 'scrap', 'crawl', 'ecommerce', 'page', 'audience', 'campaign', 'newsletter'],
  docs: ['document', 'docx', 'pdf', 'pptx', 'slide', 'powerpoint', 'excel', 'xlsx', 'spreadsheet', 'word', 'markdown', 'report', 'office', 'latex', 'poster', 'presentation', 'table'],
  security: ['secur', 'vulnerab', 'exploit', 'malware', 'forensic', 'threat', 'pentest', 'penetration', 'attack', 'incident', 'ransomware', 'phish', 'soc', 'siem', 'cyber', 'crypto', 'encrypt', 'firewall', 'intrusion', 'hardening', 'detect'],
  organize: ['plan', 'task', 'todo', 'memory', 'rememb', 'goal', 'loop', 'schedul', 'routine', 'workflow', 'brainstorm', 'focus', 'adhd', 'habit', 'project', 'wayfind', 'grill', 'note', 'organiz', 'productiv', 'calendar', 'remind', 'session', 'decision', 'priorit'],
  setup: ['setup', 'configur', 'config', 'install', 'plugin', 'skill', 'hook', 'setting', 'stack', 'audit', 'registry', 'radar', 'marketplace', 'mcp', 'tune', 'observ', 'vet'],
  business: ['job', 'career', 'cv', 'resume', 'interview', 'sale', 'customer', 'crm', 'financ', 'invoice', 'legal', 'contract', 'hiring', 'recruit', 'startup', 'pricing', 'budget', 'trading', 'invest', 'support', 'ticket', 'account', 'negotiat', 'proposal', 'compliance', 'operations', 'enterprise'],
}

const words = (text: string): string[] => text.toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 1)

/** The set whose longest stem fits the word, or nothing. */
function setOf(word: string): CategoryId | undefined {
  let best: CategoryId | undefined
  let length = 0
  for (const id of CATEGORY_IDS) {
    if (id === 'other') continue
    for (const stem of STEMS[id]) {
      const fits = word === stem || (stem.length >= 4 && word.startsWith(stem))
      if (fits && stem.length > length) {
        best = id
        length = stem.length
      }
    }
  }
  return best
}

/**
 * The set a tool belongs to. Words in its name count triple, so `seo-audit` is about the web
 * even when its description talks about checking things.
 */
export function categorize(name: string, description = '', extra = ''): CategoryId {
  const score = new Map<CategoryId, number>()
  const add = (list: string[], weight: number) => {
    for (const word of new Set(list)) {
      const id = setOf(word)
      if (id) score.set(id, (score.get(id) ?? 0) + weight)
    }
  }
  add(words(name), 3)
  add(words(extra), 1)
  add(words(description), 1)
  let best: CategoryId = 'other'
  let top = 0
  for (const id of CATEGORY_IDS) {
    const s = score.get(id) ?? 0
    if (s > top) {
      top = s
      best = id
    }
  }
  return best
}

/** What a kind of work needs: the sets to keep on. Setup and planning stay on for every job. */
export const JOBS = {
  coding: ['code', 'organize', 'setup'],
  writing: ['writing', 'docs', 'organize', 'setup'],
  research: ['research', 'docs', 'writing', 'organize', 'setup'],
  design: ['design', 'vision', 'code', 'organize', 'setup'],
  web: ['web', 'writing', 'code', 'design', 'organize', 'setup'],
  security: ['security', 'code', 'organize', 'setup'],
  business: ['business', 'docs', 'writing', 'organize', 'setup'],
  all: CATEGORY_IDS as readonly CategoryId[],
} as const
export type JobId = keyof typeof JOBS
export const JOB_IDS = Object.keys(JOBS) as JobId[]

