// One place for every color.
//
// The panel is drawn inside Claude Code's terminal and desktop app, in a light or a dark theme, and
// a theme key such as "success" is not the same green everywhere: a terminal in ANSI mode turns it
// into a pure, glaring green. So the colors that carry meaning (good, careful, bad, information)
// are fixed mid-tones, chosen to read on a near-black background as well as on white: soft, a
// little muted, never neon. The neutrals (the card edge, dimmed text) and the brand color stay theme
// keys, so they follow the person's theme. Text is never colored white or black: it keeps the
// theme's own.
//
// The palette is small on purpose: one warm brand color for what you make and for the main action,
// one cool blue for what you build or check, green / amber / red only for status, grey for the rest.
export const C = {
  brand: 'claude',
  ok: '#22A06B',
  warn: '#C98A1B',
  bad: '#DB4B4B',
  quiet: 'inactive',
  info: '#4F7DF0',
  accent: '#4F7DF0',
  // The quiet grey of a card's edge and of the empty part of a meter.
  line: 'subtle',
} as const

/**
 * A set's color says what family it is, so a glance finds it: warm for what you create, blue for
 * what you build or analyse, none for the plumbing. Status colors (on, off, big) are separate.
 */
export const FAMILY: Record<string, string | undefined> = {
  writing: C.brand,
  design: C.brand,
  vision: C.brand,
  docs: C.brand,
  code: C.info,
  research: C.info,
  security: C.info,
  web: C.info,
  organize: undefined,
  setup: undefined,
  business: undefined,
  other: undefined,
}

