// The few shapes every view is drawn from, so the whole panel reads as one design: a rounded card,
// a heading, a row that wraps, a split row, a column, a meter and a bar. Colors come from theme.ts.
// A card has no fill: its edge is all that is drawn.
//
// Two things decide how a view is drawn, and both are about not breaking when the pane changes size.
//
// 1. The font. The terminal prints in one fixed-width font, so a line made of characters is as wide
//    as its count and columns made with spaces line up. A desktop, VS Code or a phone does not: its
//    font is proportional, a row of "─" is as wide as the font makes it and wraps at random, and
//    padding with spaces does not line up. So off the terminal nothing is drawn with characters: a
//    bar is a Box with a background and a width in percent, a rule is left out, and a column is as
//    wide as its content.
// 2. The width. A pane can be dragged to any width and `bodyColumns` is only a hint there. So no row
//    adds up fixed widths and hopes: a row that may not fit is a `flexWrap` row, whose last items
//    drop to the next line, and two things at opposite ends are a `split`, which does the same.

import { stackBar } from '../format'
import { C } from '../theme'

const fixedFont = (surface: string): boolean => surface === 'terminal'

/** A rounded card. A quiet grey edge by default; a color says what the card is about. */
export const card = (ui: any, body: any, tone: string = C.line) => {
  const { Box } = ui
  return (
    <Box flexDirection="column" borderStyle="round" borderColor={tone} paddingX={1}>
      {body}
    </Box>
  )
}

/** A card's title, with a quieter line of explanation under it. */
export const heading = (ui: any, text: string, hint?: string) => {
  const { Box, Text } = ui
  return (
    <Box flexDirection="column">
      <Text bold>{text}</Text>
      {hint ? (
        <Text dimColor wrap="wrap">
          {hint}
        </Text>
      ) : null}
    </Box>
  )
}

/** A hairline across the pane. Only a fixed-width font can draw one that is the right length. */
export const rule = (ui: any, surface: string, width: number) => {
  const { Text } = ui
  return fixedFont(surface) ? <Text color={C.line}>{'─'.repeat(Math.max(10, width))}</Text> : null
}

/** Items side by side that drop to the next line instead of running off the edge. */
export const flow = (ui: any, items: any, gap = 1) => {
  const { Box } = ui
  return (
    <Box flexWrap="wrap" columnGap={gap}>
      {items}
    </Box>
  )
}

/** Something at the left and something at the right; when they do not both fit, the right one wraps below. */
export const split = (ui: any, left: any, right: any) => {
  const { Box } = ui
  return (
    <Box flexWrap="wrap" justifyContent="space-between" columnGap={1}>
      <Box flexShrink={1}>{left}</Box>
      <Box flexShrink={0}>{right}</Box>
    </Box>
  )
}

/**
 * A column. On the terminal it is `width` cells wide, so rows line up; elsewhere it is as wide as
 * its content, because a proportional font has no cells to line up on.
 */
export const col = (ui: any, surface: string, width: number, body: any, right = false) => {
  const { Box } = ui
  if (!fixedFont(surface)) return <Box flexShrink={1}>{body}</Box>
  return (
    <Box width={Math.max(1, Math.floor(width))} flexShrink={0} justifyContent={right ? 'flex-end' : 'flex-start'}>
      {body}
    </Box>
  )
}

/** One part of a bar: how much of the whole it is, as a percent, and its color. */
export type Part = { share: number; tone: string }

/**
 * A bar of colored parts over a grey track. `cells` is its width on the terminal; elsewhere it is
 * the width of its card (`full`) or `cells` wide.
 */
export const bar = (ui: any, surface: string, parts: Part[], cells: number, full = false) => {
  const { Box, Text } = ui
  const used = parts.filter(p => p.share > 0)
  if (fixedFont(surface)) {
    return (
      <Box>
        {stackBar(
          used.map(p => ({ tokens: p.share, color: p.tone })),
          100,
          Math.max(1, cells),
        ).map(s => (
          <Text color={s.color}>{s.t}</Text>
        ))}
      </Box>
    )
  }
  let left = 100
  const pieces = used.map(p => {
    const pct = Math.max(0, Math.min(left, Math.max(1, Math.round(p.share))))
    left -= pct
    return { pct, tone: p.tone }
  })
  return (
    <Box width={full ? '100%' : Math.max(1, cells)} height={1} backgroundColor={C.line}>
      {pieces
        .filter(p => p.pct > 0)
        .map(p => (
          <Box width={`${p.pct}%`} height={1} backgroundColor={p.tone} />
        ))}
    </Box>
  )
}

/** A bar for one value out of a maximum. A value that is not zero always shows. */
export const meter = (ui: any, surface: string, value: number, max: number, cells: number, tone: string, full = false) => {
  const share = value <= 0 || max <= 0 ? 0 : Math.min(100, (value / max) * 100)
  return bar(ui, surface, [{ share, tone }], cells, full)
}

