// How a main action is drawn depends on where it is drawn.
//
// The terminal draws a primary button in the accent color: one soft highlight.
// The desktop draws its own primary button instead, which is a stark white block
// in a dark theme and turned out too loud next to the quiet text around it. So
// there the main action is an ordinary button, and its place and its words carry
// the emphasis. The desktop also puts a white chip with the hotkey on a button,
// so a hotkey is only given on the terminal, where it is a hint in the label.

export type Surface = 'terminal' | 'desktop' | 'vscode' | 'mobile' | string

export const primary = (surface: Surface): 'primary' | undefined => (surface === 'terminal' ? 'primary' : undefined)

export const hotkey = (surface: Surface, key: string): string | undefined => (surface === 'terminal' ? key : undefined)

