// "Activity": what you actually use, what you do not, and what Pitwall changed. Counted on this computer.

import { ago } from '../format'
import { top, unused } from '../ledger'
import { friendlyName } from '../items'
import { C } from '../theme'
import type { ViewContext } from './context'
import { card, flow, split } from './kit'
import { primary } from './style'

const DAY = 86_400_000

export function Activity({ ui, data, act, t, surface }: ViewContext) {
  const { Box, Text, Button } = ui
  const { snap } = data.core
  const { ledger, now } = data
  const { recent } = data.live
  const watched = Math.floor((now - ledger.since) / DAY)
  const idle = snap ? unused(snap.skills, ledger, now) : []
  const dimmed = snap ? snap.skills.filter(s => s.isOwn && s.mode !== 'on').length : 0
  const days = Math.min(30, watched)

  // The skills and helpers you reach for, together: raw tool names like "Bash" mean nothing to most people.
  const most = [...top(ledger, 'skills', 5), ...top(ledger, 'agents', 5)].sort((a, b) => b.n - a.n).slice(0, 5)
  const changes = recent.filter(r => r.kind === 'change').slice(-5).reverse()

  const unusedCard = card(
    ui,
    <Box flexDirection="column">
      <Text bold>{t('act.unusedTitle')}</Text>
      {watched < 7 ? (
        <Text dimColor wrap="wrap">{t('act.needWeek', { left: t('n.days', { n: 7 - watched }) })}</Text>
      ) : idle.length === 0 ? (
        <Text dimColor wrap="wrap">{dimmed > 0 ? t('act.nothingMore', { n: dimmed }) : t('act.allUsed', { days })}</Text>
      ) : (
        <Box flexDirection="column">
          <Text wrap="wrap">{t('act.unused', { n: idle.length, days })}</Text>
          {idle.slice(0, 6).map(s => (
            <Text color={C.warn} wrap="wrap">{`○ ${friendlyName(s.name)}`}</Text>
          ))}
          {idle.length > 6 && <Text dimColor>{t('act.more', { n: idle.length - 6 })}</Text>}
          <Box marginTop={1}>
            {flow(ui, [
              <Button key="dim" label={t('act.make', { n: idle.length })} variant={primary(surface)} onPress={() => act.dim()} />,
              <Text dimColor wrap="wrap">{t('act.makeHint')}</Text>,
            ])}
          </Box>
        </Box>
      )}
    </Box>,
    idle.length > 0 && watched >= 7 ? C.warn : C.line,
  )

  const mostCard = card(
    ui,
    <Box flexDirection="column">
      <Text bold>{t('act.most')}</Text>
      {most.length === 0 ? (
        <Text dimColor wrap="wrap">{t('act.none')}</Text>
      ) : (
        most.map(r =>
          split(
            ui,
            <Box>
              <Text color={C.brand}>{'● '}</Text>
              <Text wrap="wrap">{friendlyName(r.name.split(':').pop() ?? r.name)}</Text>
            </Box>,
            <Text dimColor>{t('n.times', { n: r.n })}</Text>,
          ),
        )
      )}
    </Box>,
  )

  const changesCard = card(
    ui,
    <Box flexDirection="column">
      <Text bold>{t('act.changes')}</Text>
      {changes.length === 0 ? (
        <Text dimColor wrap="wrap">{t('act.noChanges')}</Text>
      ) : (
        changes.map(r => (
          <Box flexWrap="wrap" columnGap={1}>
            <Text dimColor>{t('act.ago', { t: ago(r.at, now) })}</Text>
            <Text wrap="wrap">{r.label}</Text>
          </Box>
        ))
      )}
    </Box>,
  )

  return (
    <Box flexDirection="column">
      <Text dimColor wrap="wrap">{t('act.watching', { span: watched < 1 ? t('act.lessThanDay') : t('n.days', { n: watched }) })}</Text>
      {unusedCard}
      {mostCard}
      {changesCard}
    </Box>
  )
}

