// "Configure": paste a link, a tool name, or what you need, and the assistant checks it and says
// whether to add it. A separate conversation: nothing said here reaches the main chat, and nothing
// in the main chat reaches it. The question goes at the top, where a paste lands.

import { trunc } from '../format'
import { C } from '../theme'
import type { ViewContext } from './context'
import { card } from './kit'
import { primary } from './style'

/** The verdict line the assistant starts a check with, and the rest of its answer. */
export function splitVerdict(text: string): { verdict?: 'add' | 'careful' | 'avoid'; body: string } {
  const m = text.match(/^\s*VERDICT:\s*(add|careful|avoid)\b[^\n]*\n?/i)
  return m ? { verdict: m[1].toLowerCase() as 'add' | 'careful' | 'avoid', body: text.slice(m[0].length).trim() } : { body: text }
}

const VERDICT_COLOR = { add: C.ok, careful: C.warn, avoid: C.bad } as const

export function Chat({ ui, width, data, act, t, surface }: ViewContext) {
  const { Box, Text, Button, Input, Markdown } = ui
  const { chat, isChatBusy, trace, sent } = data.talk
  // The button appears when the assistant asked for a go, which is how its brief tells it to ask.
  const last = chat[chat.length - 1]
  const asksGo = !isChatBusy && last?.role === 'assistant' && /\bgo\b/i.test(last.text)

  const ask = card(
    ui,
    <Box flexDirection="column">
      <Text wrap="wrap">{t('chat.intro')}</Text>
      <Box marginTop={1}>
        {Input ? (
          <Input key={`chat-input-${sent}`} placeholder={t('chat.placeholder')} submitLabel={t('chat.send')} onSubmit={(text: string) => act.ask(text)} />
        ) : (
          <Text dimColor wrap="wrap">{t('chat.noInput')}</Text>
        )}
      </Box>
    </Box>,
    C.accent,
  )

  const starters =
    chat.length === 0
      ? card(
          ui,
          <Box flexDirection="column">
            <Text dimColor>{t('chat.try')}</Text>
            <Button key="try-check" label={t('chat.try.check')} onPress={() => act.ask(t('chat.ask.check'))} />
            <Button key="try-find" label={t('chat.try.find')} onPress={() => act.ask(t('chat.ask.find'))} />
            <Button key="try-work" label={t('chat.try.work')} onPress={() => act.ask(t('chat.ask.work'))} />
            <Button key="try-free" label={t('home.free')} onPress={() => act.lighter()} />
          </Box>,
        )
      : null

  return (
    <Box flexDirection="column">
      {ask}
      {starters}

      <Box flexDirection="column">
        {chat.slice(-6).map(l => {
          if (l.role === 'user') {
            return card(
              ui,
              <Box>
                <Text color={C.brand} bold>{`${t('chat.you')}  `}</Text>
                <Text wrap="wrap">{l.text}</Text>
              </Box>,
            )
          }
          if (l.role === 'assistant') {
            const { verdict, body } = splitVerdict(l.text)
            return card(
              ui,
              <Box flexDirection="column">
                {verdict ? <Text color={VERDICT_COLOR[verdict]} bold>{t(`verdict.${verdict}`)}</Text> : <Text color={C.accent} bold>{`◆ ${t('chat.assistant')}`}</Text>}
                <Markdown text={body} />
              </Box>,
              verdict ? VERDICT_COLOR[verdict] : C.line,
            )
          }
          return <Text color={C.warn} wrap="wrap">{l.text}</Text>
        })}
      </Box>

      {isChatBusy && (
        <Box flexDirection="column" marginTop={1}>
          <Text color={C.info}>{`◌ ${t('chat.working')}`}</Text>
          {trace.map(line => (
            <Text dimColor wrap="truncate">{`  ${trunc(line, width - 4)}`}</Text>
          ))}
        </Box>
      )}
      <Box marginTop={1} flexWrap="wrap" columnGap={1}>
        {asksGo && <Button key="chat-go" label={t('chat.goAhead')} variant={primary(surface)} onPress={() => act.ask('go')} />}
        {isChatBusy ? (
          <Button key="chat-stop" label={t('chat.stop')} plain dimColor onPress={() => act.cancel()} />
        ) : (
          chat.length > 0 && <Button key="chat-clear" label={t('chat.clear')} plain dimColor onPress={() => act.clear()} />
        )}
      </Box>
    </Box>
  )
}

