// "Home": one answer to "is Claude's memory full, and what should I do about it?", for this chat
// and this project, as a few cards: the state of the memory, the project's own setup and its
// Optimize, what to turn off first, a kind of work to set up for, the plan limits, and a tip.
// Every row is built to survive any pane width (see kit.tsx): nothing here adds up fixed widths.

import { fmtPct, until } from '../format'
import { JOB_IDS } from '../categories'
import { buildItems, jobChange } from '../items'
import { C } from '../theme'
import type { ViewContext } from './context'
import { bar, card, flow, heading, meter, split } from './kit'
import { optimizeCard } from './optimize'
import { primary } from './style'

/** The engine's categories folded into the five rows a person can follow. */
const ROW: Record<string, 'chat' | 'tools' | 'connections' | 'instructions' | 'core'> = {
  Messages: 'chat',
  Skills: 'tools',
  'Custom agents': 'tools',
  'MCP tools': 'connections',
  'Memory files': 'instructions',
  'System prompt': 'core',
  'System tools': 'core',
}
const ROW_COLOR = { chat: C.ok, core: C.quiet, tools: C.brand, connections: C.info, instructions: C.warn } as const
type RowId = keyof typeof ROW_COLOR

export function Home(ctx: ViewContext) {
  const { ui, width, data, act, t, surface, scope } = ctx
  const { Box, Text, Button } = ui
  const { snap, layers, project } = data.core
  if (!snap) return <Text dimColor>{t('home.measuring')}</Text>
  if (!snap.hasUsage) {
    return (
      <Box flexDirection="column">
        <Text color={C.warn} wrap="wrap">{t('home.noUsage')}</Text>
        <Text dimColor wrap="wrap">{t('home.needVersion')}</Text>
      </Box>
    )
  }

  const total = snap.window > 0 ? snap.window : snap.usedTokens
  const pct = Math.round(snap.percent)
  const level = pct >= 85 ? 'high' : pct >= 60 ? 'mid' : 'low'
  const tone = level === 'high' ? C.bad : level === 'mid' ? C.warn : C.ok
  const inner = Math.max(10, width - 4)

  const sums: Record<RowId, number> = { chat: 0, core: 0, tools: 0, connections: 0, instructions: 0 }
  for (const c of snap.categories) {
    const row = ROW[c.name]
    if (row && c.kind === 'used') sums[row] += c.tokens
  }
  const rows = (Object.keys(sums) as RowId[]).filter(id => sums[id] > 0).sort((a, b) => sums[b] - sums[a])

  const items = buildItems(snap, data.names, data.core.digest, { scope, layers })
  const heavy = items
    .filter(i => i.isOn && i.kind === 'plugin' && i.share >= 1)
    .sort((a, b) => b.share - a.share)
    .slice(0, 3)

  const inProject = scope === 'project' && project !== null
  const own = layers ? Object.keys(layers.local.plugins).length + Object.keys(layers.local.skills).length : 0
  const guess = project?.guess
  const kind = guess ? t(`job.${guess.job}` as 'job.coding') : ''

  // What the project says about itself: a starting profile from what the folder looks like, or the
  // fact that it already has its own setup and a way back to the global one.
  const lead = !inProject ? null : own > 0 ? (
    <Box flexDirection="column">
      <Text wrap="wrap">{t('proj.own', { tools: t('n.tools', { n: own }) })}</Text>
      {flow(ui, [<Button key="proj-back" label={t('proj.back')} plain dimColor onPress={() => act.inherit()} />])}
    </Box>
  ) : guess && !project!.declined ? (
    <Box flexDirection="column">
      <Text wrap="wrap">{t('proj.guess', { kind, files: guess.evidence.join(', ') })}</Text>
      {flow(ui, [
        <Button key="proj-start" label={t('proj.start', { kind })} variant={primary(surface)} onPress={() => act.set({ ...jobChange(items, guess.job as never), label: kind, profile: guess.job })} />,
        <Button key="proj-no" label={t('proj.notThis')} plain dimColor onPress={() => act.decline()} />,
      ])}
    </Box>
  ) : null

  const hero = card(
    ui,
    <Box flexDirection="column">
      <Text color={tone} bold wrap="wrap">{t('home.title', { pct })}</Text>
      {bar(
        ui,
        surface,
        rows.map(id => ({ share: (sums[id] / total) * 100, tone: ROW_COLOR[id] })),
        inner,
        true,
      )}
      <Text dimColor wrap="wrap">{t(`home.level.${level}`)}</Text>
      <Box marginTop={1} flexDirection="column">
        {rows.map(id =>
          split(
            ui,
            <Box>
              <Text color={ROW_COLOR[id]}>{'● '}</Text>
              <Text wrap="wrap">{t(`home.row.${id}`)}</Text>
            </Box>,
            <Text dimColor>{`${fmtPct((sums[id] / total) * 100)}%`}</Text>,
          ),
        )}
      </Box>
    </Box>,
    tone,
  )

  const { node: optimize, plan } = optimizeCard(ctx, items, { project: inProject, lead })

  const biggest =
    heavy.length > 0
      ? card(
          ui,
          <Box flexDirection="column">
            {heading(ui, t('home.biggest'), t('home.biggestHint'))}
            {heavy.map(item =>
              split(
                ui,
                <Box>
                  <Text color={C.warn}>{'● '}</Text>
                  <Text wrap="wrap">{`${item.name}  `}</Text>
                  <Text dimColor>{`${fmtPct(item.share)}%`}</Text>
                </Box>,
                <Button key={`off:${item.id}`} label={t('home.turnOff')} onPress={() => act.plugin(item.id, false)} />,
              ),
            )}
          </Box>,
        )
      : null

  const jobs = card(
    ui,
    <Box flexDirection="column">
      {heading(ui, t('home.modes'), t(inProject ? 'proj.modesHint' : 'home.modesHint'))}
      {flow(
        ui,
        JOB_IDS.map(job => <Button key={`job:${job}`} label={t(`job.${job}`)} onPress={() => act.set({ ...jobChange(items, job), label: t(`job.${job}`), profile: job })} />),
      )}
    </Box>,
  )

  const limits =
    snap.limits.length > 0
      ? card(
          ui,
          <Box flexDirection="column">
            <Text bold>{t('home.plan')}</Text>
            {snap.limits.map(l => {
              const key = `home.limit.${l.kind}`
              const known = t(key as 'home.limit.other') !== key
              const name = known ? t(key as 'home.limit.other') : t('home.limit.other', { kind: l.kind.replace('_', ' ') })
              const color = l.percent >= 85 ? C.bad : l.percent >= 60 ? C.warn : C.ok
              const reset = until(l.resetsAt, data.now)
              return (
                <Box flexDirection="column" marginTop={1}>
                  {split(ui, <Text wrap="wrap">{name}</Text>, <Text bold>{`${Math.round(l.percent)}%`}</Text>)}
                  {meter(ui, surface, l.percent, 100, inner, color, true)}
                  {reset ? <Text dimColor wrap="wrap">{t('home.resets', { time: reset })}</Text> : null}
                </Box>
              )
            })}
          </Box>,
        )
      : null

  // The tip is for the quiet case: when there is something to tidy, Optimize says so.
  const tip =
    plan.steps.length === 0 && heavy.length === 0
      ? card(
          ui,
          <Box flexDirection="column">
            <Text bold>{`✦ ${t('home.tip')}`}</Text>
            <Text dimColor wrap="wrap">{t('home.tip.fine')}</Text>
          </Box>,
        )
      : null

  return (
    <Box flexDirection="column">
      {hero}
      {optimize}
      {biggest}
      {jobs}
      {limits}
      {tip}
    </Box>
  )
}

