// "Global": the one tab for everything that is not about a single project. What is set here is what
// every project inherits until it sets its own; the usage behind its tune-up is counted across all
// projects. Below it, Pitwall's own preferences and the advanced corner, which is one button until
// it is pressed.

import { ago, fmtTok, trunc } from '../format'
import { buildItems } from '../items'
import { LANGS } from '../i18n'
import { C } from '../theme'
import type { ViewContext } from './context'
import { card, col, flow, split } from './kit'
import { optimizeCard } from './optimize'
import { Tools } from './tools'

export function Global(ctx: ViewContext) {
  const { ui, width, data, act, t, surface } = ctx
  const { Box, Text, Button, Select, Link } = ui
  const { snap, prefs, layers, projects } = data.core
  const { nav } = data
  const textWidth = Math.max(20, width - 14)

  const langOptions = [
    { value: 'auto', label: t('lang.auto', { name: t(`lang.${data.autoLang}` as 'lang.en') }) },
    ...LANGS.map(l => ({ value: l, label: t(`lang.${l}` as 'lang.en') })),
  ]

  const Row = (label: string, control: any, hint?: string) => (
    <Box flexDirection="column">
      <Box flexWrap="wrap" columnGap={1}>
        {col(ui, surface, 24, <Text bold wrap="wrap">{label}</Text>)}
        {control}
      </Box>
      {hint && <Text dimColor wrap="wrap">{hint}</Text>}
    </Box>
  )

  const Switch = (key: string, on: boolean, onWord: string, offWord: string, press: () => void) => (
    <Button key={key} label={on ? `● ${onWord}` : `○ ${offWord}`} plain dimColor={!on} onPress={press} />
  )

  const Section = (id: string, title: string, about: string, count: number, body: any) =>
    card(
      ui,
      <Box flexDirection="column">
        {flow(ui, [
          <Button key={`adv:${id}`} label={`${nav.adv === id ? '▾' : '▸'} ${title}`} plain onPress={() => act.adv(id)} />,
          <Text dimColor>{count}</Text>,
        ])}
        <Text dimColor wrap="wrap">{about}</Text>
        {nav.adv === id && <Box flexDirection="column" marginTop={1}>{body}</Box>}
      </Box>,
      nav.adv === id ? C.accent : C.line,
    )

  const none = <Text dimColor wrap="wrap">{t('adv.none')}</Text>

  const optimize = snap && snap.hasUsage ? optimizeCard(ctx, buildItems(snap, data.names, data.core.digest, { scope: 'global', layers }), { project: false }).node : null

  const known = card(
    ui,
    <Box flexDirection="column">
      <Text bold>{t('glob.projects')}</Text>
      {projects.length === 0 ? (
        <Text dimColor wrap="wrap">{t('glob.noProjects')}</Text>
      ) : (
        projects.slice(0, 8).map(p =>
          split(
            ui,
            <Box>
              <Text color={C.brand}>{'● '}</Text>
              <Text wrap="wrap">{p.name}</Text>
            </Box>,
            <Text dimColor>{t('act.ago', { t: ago(p.last, data.now) })}</Text>,
          ),
        )
      )}
    </Box>,
  )

  return (
    <Box flexDirection="column">
      {card(ui, <Text dimColor wrap="wrap">{t('glob.about')}</Text>)}
      {optimize}
      <Box marginTop={1}>
        <Button key="gtools" label={`${nav.gtools ? '▾' : '▸'} ${t('glob.tools')}`} onPress={() => act.gtools()} />
      </Box>
      {nav.gtools && Tools(ctx)}
      {known}

      {card(
        ui,
        <Box flexDirection="column" gap={1}>
          {Row(t('set.language'), <Select key="pref:lang" options={langOptions} value={prefs.lang} onSelect={(v: string) => act.lang(v)} />)}
          {Row(t('set.autopilot'), Switch('pref:autopilot', prefs.autopilot, t('set.hintsOn'), t('set.hintsOff'), () => act.pref('autopilot', !prefs.autopilot)), t('set.autopilotHint'))}
          {Row(t('set.band'), Switch('pref:band', prefs.showBand, t('set.shown'), t('set.hidden'), () => act.pref('showBand', !prefs.showBand)), t('set.bandHint'))}
          {Row(t('set.summaries'), Switch('pref:summaries', prefs.summaries, t('set.hintsOn'), t('set.hintsOff'), () => act.pref('summaries', !prefs.summaries)), t('set.summariesHint'))}
          {Row(t('set.hints'), Switch('pref:hints', prefs.hints, t('set.hintsOn'), t('set.hintsOff'), () => act.pref('hints', !prefs.hints)), t('set.hintsHint'))}
        </Box>,
      )}

      <Box marginTop={1}>
        <Button key="adv:all" label={`${nav.advOn ? '▾' : '▸'} ${t('set.advanced')}`} onPress={() => act.advAll()} />
      </Box>
      {nav.advOn && <Text dimColor wrap="wrap">{t('set.advancedHint')}</Text>}
      {nav.advOn && snap && (
        <Box flexDirection="column">
          {Section(
            'connections',
            t('adv.connections'),
            t('adv.connections.about'),
            snap.mcp.length,
            snap.mcp.length === 0 ? (
              none
            ) : (
              <Box flexDirection="column">
                {snap.mcp.map(m => (
                  <Box flexWrap="wrap" columnGap={1}>
                    {col(ui, surface, 23, <Text wrap="wrap">{m.server}</Text>)}
                    <Text dimColor wrap="wrap">{m.deferred > 0 ? t('adv.onDemand', { tools: t('n.tools', { n: m.tools }), deferred: m.deferred }) : t('n.tools', { n: m.tools })}</Text>
                  </Box>
                ))}
                <Text dimColor wrap="wrap">{t('adv.removeHint')}</Text>
              </Box>
            ),
          )}
          {Section(
            'automations',
            t('adv.automations'),
            t('adv.automations.about'),
            snap.hooks.length,
            snap.hooks.length === 0 ? (
              none
            ) : (
              <Box flexDirection="column">
                {snap.hooks.slice(0, 12).map(hook => (
                  <Box flexWrap="wrap" columnGap={1}>
                    {col(ui, surface, 17, <Text dimColor wrap="wrap">{hook.event}</Text>)}
                    <Text dimColor wrap="wrap">{trunc(hook.command, Math.max(8, textWidth - 20))}</Text>
                  </Box>
                ))}
              </Box>
            ),
          )}
          {Section(
            'instructions',
            t('adv.instructions'),
            t('adv.instructions.about'),
            snap.memory.length,
            snap.memory.length === 0 ? (
              none
            ) : (
              <Box flexDirection="column">
                {snap.memory.map(m => (
                  <Box flexWrap="wrap" columnGap={1}>
                    {col(ui, surface, Math.max(12, textWidth - 12), <Text wrap="wrap">{m.path.split(/[\\/]/).pop() ?? m.path}</Text>)}
                    <Text dimColor>{fmtTok(m.tokens)}</Text>
                  </Box>
                ))}
              </Box>
            ),
          )}
          {Section(
            'helpers',
            t('adv.helpers'),
            t('adv.helpers.about'),
            snap.agents.length,
            snap.agents.length === 0 ? (
              none
            ) : (
              <Box flexDirection="column">
                {snap.agents.slice(0, 12).map(a => (
                  <Text wrap="wrap">{a.name}</Text>
                ))}
                {snap.agents.length > 12 && <Text dimColor>{t('act.more', { n: snap.agents.length - 12 })}</Text>}
              </Box>
            ),
          )}
        </Box>
      )}

      <Box marginTop={1} flexWrap="wrap" columnGap={1}>
        <Text dimColor wrap="wrap">{t('about.text', { version: data.version || '' }).replace('  ', ' ')}</Text>
        {Link ? <Link href="https://github.com/rlpb/pitwall" label={t('about.link')} /> : <Text color={C.info}>github.com/rlpb/pitwall</Text>}
      </Box>
    </Box>
  )
}

