// "My tools": every add-on and skill, gathered into sets by what it is for. One set is open at a
// time and a tool's details open under it, so the panel stays a short page, not a long list.
// Color says what matters at a glance: a set's family on its dot, green for on, grey for off,
// blue for the in-between states, amber for the big ones. Descriptions are written out in full.
// A search finds a tool by name or by what it does. Rows wrap instead of overflowing (see kit.tsx).

import type { SkillMode } from '../../types'
import { fmtPct, trunc } from '../format'
import { buildItems, groupItems, tally, type Group, type Item } from '../items'
import { unused } from '../ledger'
import { C, FAMILY } from '../theme'
import type { ViewContext } from './context'
import { card, col, flow, meter, split } from './kit'
import { primary } from './style'

const MODES: SkillMode[] = ['on', 'name-only', 'user-invocable-only', 'off']
const SHOWN = 10
const DAY = 86_400_000
const noGlyph = (text: string): string => text.replace(/^[●○◐]\s*/, '')
/** The first sentence, written out in full, but never a wall: past 240 characters it stops at a word. */
const lead = (text: string): string => {
  const one = text.replace(/\s+/g, ' ').trim().split(/(?<=[.!?。！？])\s/)[0] ?? ''
  return one.length <= 240 ? one : `${one.slice(0, 237).replace(/\s+\S*$/, '')}…`
}

export function Tools({ ui, width, data, act, t, surface, scope }: ViewContext) {
  const { Box, Text, Button, Select, Link, Input } = ui
  const { snap, digest, layers, project } = data.core
  const inProject = scope === 'project' && project !== null
  const { nav } = data
  if (!snap) return <Text dimColor>{t('home.measuring')}</Text>

  const items = buildItems(snap, data.names, digest, { scope, layers })
  const groups = groupItems(items)
  const { on, total } = tally(items)
  const query = nav.find.toLowerCase()
  const matches = query ? items.filter(i => [i.name, i.id, i.description, i.original].some(s => (s ?? '').toLowerCase().includes(query))) : []
  // Own skills nobody has opened for a month: say so on their row, so it is clear why they could go.
  const idleNames = new Set(unused(snap.skills, data.ledger, data.now).map(s => s.name))
  const idleDays = Math.min(30, Math.max(1, Math.floor((data.now - data.ledger.since) / DAY)))

  const stateOf = (item: Item): { word: string; dot: string; color: string | undefined } => {
    if (!item.isOn) return { word: noGlyph(t('item.off')), dot: '○', color: C.quiet }
    if (item.mode === 'name-only') return { word: noGlyph(t('item.light')), dot: '◐', color: C.info }
    if (item.mode === 'user-invocable-only') return { word: noGlyph(t('item.request')), dot: '◐', color: C.info }
    return { word: noGlyph(t('item.on')), dot: '●', color: C.ok }
  }
  const shareColor = (share: number): string => (share >= 3 ? C.bad : share >= 1.2 ? C.warn : C.quiet)

  const toggle = (item: Item) => (item.kind === 'plugin' ? act.plugin(item.id, !item.isOn) : act.skill(item.id, item.isOn ? 'off' : 'on'))

  const setAll = (group: Group, isOn: boolean) =>
    act.set({
      plugins: group.items.filter(i => i.kind === 'plugin').map(i => ({ id: i.id, isOn })),
      skills: group.items.filter(i => i.kind === 'skill').map(i => ({ name: i.id, mode: (isOn ? 'on' : 'off') as SkillMode })),
      label: `${t(`cat.${group.id}`)}: ${t(isOn ? 'word.on' : 'word.off')}`,
    })

  const Technical = (item: Item) => (
    <Box flexDirection="column" marginTop={1}>
      <Text dimColor wrap="wrap">{`${t('tech.id')}: ${item.id}`}</Text>
      <Text dimColor wrap="wrap">{`${t('tech.size')}: ${item.weight > 0 ? `${item.weight} tokens` : '—'}`}</Text>
      <Text dimColor wrap="wrap">{`${t('tech.source')}: ${item.source ?? item.kind}`}</Text>
      <Text dimColor wrap="wrap">{`${t('tech.original')}: ${item.original || '—'}`}</Text>
    </Box>
  )

  const Details = (item: Item) => {
    const takes =
      item.size === 'unknown'
        ? t('item.sizeUnknown')
        : t(item.isOn ? 'item.takes' : 'item.wouldTake', { pct: fmtPct(item.share), size: t(`size.${item.size}`) })
    const carries = item.kind === 'plugin' && item.isOn && (item.skills > 0 || item.agents > 0)
    return (
      <Box flexDirection="column" marginLeft={2} marginBottom={1}>
        <Text wrap="wrap">{item.description || t('info.noDescription')}</Text>
        <Text color={item.size === 'large' && item.isOn ? C.warn : undefined} dimColor={!(item.size === 'large' && item.isOn)} wrap="wrap">
          {takes}
        </Text>
        {carries && <Text dimColor wrap="wrap">{t('item.contains', { skills: t('n.skills', { n: item.skills }), agents: t('n.agents', { n: item.agents }) })}</Text>}
        {item.repo ? (
          flow(ui, [
            <Text dimColor>{`${t('info.repository')}:`}</Text>,
            Link ? <Link href={item.repo} label={trunc(item.repo.replace('https://', ''), Math.max(20, width - 24))} /> : <Text color={C.info}>{item.repo}</Text>,
          ])
        ) : (
          <Text dimColor wrap="wrap">{t('info.noRepository')}</Text>
        )}
        {item.kind === 'plugin' ? (
          flow(ui, [
            <Text dimColor wrap="wrap">{`${item.version ? `${t('info.version', { v: item.version })} · ` : ''}${t('info.from', { source: item.source ?? '' })}`}</Text>,
            <Button key={`update:${item.id}`} label={t('item.update')} plain dimColor onPress={() => act.update(item.id)} />,
          ])
        ) : (
          <Box flexDirection="column">
            <Text dimColor wrap="wrap">{t('info.ownSkill')}</Text>
            {flow(ui, [
              <Text>{t('item.how')}</Text>,
              <Select
                key={`skill:${item.id}`}
                options={MODES.map(m => ({ value: m, label: t(`mode.${m}`) }))}
                value={item.mode ?? 'on'}
                onSelect={(v: string) => act.skill(item.id, v as SkillMode)}
              />,
            ])}
            <Text dimColor wrap="wrap">{t('mode.legend')}</Text>
          </Box>
        )}
        {inProject && item.origin === 'project' && (
          <Box marginTop={1}>
            <Button key={`inherit:${item.key}`} label={t('item.inherit')} plain dimColor onPress={() => act.inherit([item.key])} />
          </Box>
        )}
        <Box marginTop={1}>
          <Button key={`tech:${item.key}`} label={`${nav.tech === item.key ? '▾' : '▸'} ${t(nav.tech === item.key ? 'item.techHide' : 'item.tech')}`} plain dimColor onPress={() => act.tech(item.key)} />
        </Box>
        {nav.tech === item.key && Technical(item)}
      </Box>
    )
  }

  const Row = (item: Item) => {
    const state = stateOf(item)
    const blurb = lead(item.description)
    const big = item.size === 'large' && item.isOn
    const idle = item.kind === 'skill' && idleNames.has(item.id)
    return (
      <Box flexDirection="column">
        <Box flexWrap="wrap" columnGap={1}>
          <Box flexGrow={1} flexShrink={1} minWidth={12}>
            <Text color={state.color}>{`${state.dot} `}</Text>
            <Text bold={item.isOn} dimColor={!item.isOn} wrap="wrap">{item.name}</Text>
          </Box>
          {col(ui, surface, 12, <Text color={big ? C.warn : undefined} dimColor={!big} wrap="truncate">{t(`size.${item.size}`)}</Text>)}
          {col(ui, surface, 11, <Button key={`sw:${item.key}`} label={state.word} plain dimColor={!item.isOn} onPress={() => toggle(item)} />)}
          <Button key={`i:${item.key}`} label={t('item.more')} plain dimColor onPress={() => act.info(item.key)} />
        </Box>
        {blurb !== '' && nav.info !== item.key && (
          <Box marginLeft={2}>
            <Text dimColor wrap="wrap">{blurb}</Text>
          </Box>
        )}
        {idle && item.isOn && nav.info !== item.key && (
          <Box marginLeft={2}>
            <Text color={C.warn} wrap="wrap">{`○ ${t('item.idle', { days: idleDays })}`}</Text>
          </Box>
        )}
        {inProject && item.origin === 'project' && nav.info !== item.key && (
          <Box marginLeft={2}>
            <Text color={C.info} wrap="wrap">{`◆ ${t('item.here')}`}</Text>
          </Box>
        )}
        {nav.info === item.key && Details(item)}
      </Box>
    )
  }

  const Card = (group: Group) => {
    const isOpen = nav.open === group.id
    const allOn = group.on === group.items.length
    const family = FAMILY[group.id]
    const count = allOn ? C.ok : group.on === 0 ? C.quiet : undefined
    return card(
      ui,
      <Box flexDirection="column">
        {split(
          ui,
          flow(ui, [
            <Box>
              <Text color={family} dimColor={!family}>{'● '}</Text>
              <Button key={`set:${group.id}`} label={`${isOpen ? '▾' : '▸'} ${t(`cat.${group.id}`)}`} plain onPress={() => act.open(group.id)} />
            </Box>,
            <Text color={count} dimColor={!count}>{t('group.state', { on: group.on, n: group.items.length })}</Text>,
            ...(group.share >= 1 ? [meter(ui, surface, Math.min(group.share, 5), 5, 5, shareColor(group.share))] : []),
          ]),
          <Button key={`all:${group.id}`} label={t(allOn ? 'group.allOff' : 'group.allOn')} plain dimColor onPress={() => setAll(group, !allOn)} />,
        )}
        <Box marginLeft={2}>
          <Text dimColor wrap="wrap">{`${t(`cat.${group.id}.about`)}${group.share >= 0.3 ? ` · ${t('group.takes', { pct: fmtPct(group.share) })}` : ''}`}</Text>
        </Box>
        {isOpen && (
          <Box flexDirection="column" marginTop={1}>
            {(nav.more === group.id ? group.items : group.items.slice(0, SHOWN)).map(item => Row(item))}
            {group.items.length > SHOWN && (
              <Box marginLeft={2}>
                <Button
                  key={`more:${group.id}`}
                  label={nav.more === group.id ? t('group.showFewer') : t('group.showAll', { n: group.items.length })}
                  plain
                  dimColor
                  onPress={() => act.more(group.id)}
                />
              </Box>
            )}
          </Box>
        )}
      </Box>,
      isOpen ? family ?? C.accent : C.line,
    )
  }

  const header = card(
    ui,
    <Box flexDirection="column">
      <Text bold wrap="wrap">{t('tools.title', { on, total })}</Text>
      <Text dimColor wrap="wrap">{t('tools.intro')}</Text>
      {Input && (
        <Box marginTop={1}>
          <Input key={`find-${nav.find}`} placeholder={t('find.placeholder')} submitLabel={t('find.go')} onSubmit={(text: string) => act.find(text)} />
        </Box>
      )}
      <Box marginTop={1}>
        {flow(ui, [
          <Button key="update-all" label={t('tools.update')} variant={primary(surface)} onPress={() => act.update()} />,
          <Text dimColor wrap="wrap">{t('tools.updateHint')}</Text>,
        ])}
      </Box>
    </Box>,
  )

  const results = query
    ? card(
        ui,
        <Box flexDirection="column">
          {split(ui, <Text bold wrap="wrap">{t('find.results', { q: nav.find })}</Text>, <Button key="find-clear" label={t('find.clear')} plain dimColor onPress={() => act.find('')} />)}
          {matches.length === 0 ? (
            <Text dimColor wrap="wrap">{t('find.none', { q: nav.find })}</Text>
          ) : (
            <Box flexDirection="column" marginTop={1}>
              {matches.slice(0, 20).map(item => Row(item))}
            </Box>
          )}
          {matches.length > 20 && <Text dimColor>{t('act.more', { n: matches.length - 20 })}</Text>}
        </Box>,
        C.accent,
      )
    : null

  return (
    <Box flexDirection="column">
      {header}
      {results}
      {!query && groups.length === 0 && (
        <Box marginTop={1}>
          <Text dimColor wrap="wrap">{t('tools.empty')}</Text>
        </Box>
      )}
      {!query && groups.map(group => Card(group))}
    </Box>
  )
}

