// The Optimize card: what Pitwall proposes to tidy, from what is installed and what is really used.
// It is drawn twice, with the same plan logic: on Home for the project (usage counted in this
// project, changes written to its own settings) and on the Global tab for everywhere (usage across
// all projects, changes written to the global settings). The tab that draws it decides, through
// `ctx.scope` and the ledger it was given; this file only draws.

import { fmtPct } from '../format'
import type { Item } from '../items'
import { planChange, planOptimize, type Plan, type Step, type StepKind } from '../optimize'
import { C } from '../theme'
import type { ViewContext } from './context'
import { card, flow, split } from './kit'
import { primary } from './style'

const KINDS: StepKind[] = ['off', 'light', 'on']
const KIND_COLOR: Record<StepKind, string> = { off: C.quiet, light: C.info, on: C.ok }
/** Rows shown per group of the plan; the rest are still applied, and counted in a line. */
const PREVIEW_ROWS = 6

export function optimizeCard(ctx: ViewContext, items: Item[], opts: { project: boolean; lead?: any }): { node: any; plan: Plan } {
  const { ui, data, act, t, surface } = ctx
  const { Box, Text, Button } = ui
  const { snap, prefs } = data.core
  const { nav } = data
  const plan = planOptimize({ items, snap: snap!, ledger: data.ledger, names: data.names, now: data.now, keep: nav.keep })
  const hasSteps = plan.steps.length > 0

  // One row of the plan: what changes, why, what it is worth, and a button to leave it out.
  const stepRow = (step: Step) =>
    split(
      ui,
      <Box flexDirection="column">
        <Box>
          <Text color={KIND_COLOR[step.kind]}>{'● '}</Text>
          <Text wrap="wrap">{step.name}</Text>
        </Box>
        <Box marginLeft={2}>
          <Text dimColor wrap="wrap">{t(`opt.why.${step.why}`, { days: step.days })}</Text>
        </Box>
      </Box>,
      flow(ui, [
        <Text dimColor>{`${step.tokens < 0 ? '+' : ''}${fmtPct(Math.abs(step.pct))}%`}</Text>,
        <Button key={`keep:${step.key}`} label={t('opt.keep')} plain dimColor onPress={() => act.keep(step.key)} />,
      ]),
    )

  const apply = () => {
    act.set({ ...planChange(plan.steps), label: t('opt.label') })
    act.opt(false)
  }

  const advice = plan.advice.map(a => (
    <Text color={a.id === 'compact' ? C.warn : undefined} dimColor={a.id !== 'compact'} wrap="wrap">
      {`▸ ${t(`opt.advice.${a.id}`, { pct: fmtPct(a.pct), names: a.names.join(', ') })}`}
    </Text>
  ))

  const node = card(
    ui,
    <Box flexDirection="column">
      <Text bold color={C.brand}>{`✦ ${t(opts.project ? 'proj.title' : 'opt.title')}`}</Text>
      <Text dimColor wrap="wrap">{t(opts.project ? 'proj.about' : 'opt.about')}</Text>
      {opts.lead ? <Box flexDirection="column" marginTop={1}>{opts.lead}</Box> : null}

      {nav.opt && hasSteps ? (
        <Box flexDirection="column" marginTop={1}>
          {KINDS.map(kind => {
            const steps = plan.steps.filter(s => s.kind === kind)
            if (steps.length === 0) return null
            return (
              <Box flexDirection="column" marginBottom={1}>
                <Text bold>{t(`opt.group.${kind}`)}</Text>
                {steps.slice(0, PREVIEW_ROWS).map(stepRow)}
                {steps.length > PREVIEW_ROWS && <Text dimColor>{t('act.more', { n: steps.length - PREVIEW_ROWS })}</Text>}
              </Box>
            )
          })}
          {flow(ui, [
            <Button key="opt-apply" label={t('opt.apply', { n: plan.steps.length })} variant={primary(surface)} onPress={apply} />,
            <Button key="opt-cancel" label={t('opt.cancel')} plain dimColor onPress={() => act.opt(false)} />,
          ])}
        </Box>
      ) : (
        <Box flexDirection="column" marginTop={1}>
          {hasSteps ? (
            <Box flexDirection="column">
              <Text bold wrap="wrap">{t('opt.ready', { n: plan.steps.length, pct: fmtPct(plan.freePct) })}</Text>
              {plan.addPct >= 0.05 && <Text dimColor wrap="wrap">{t('opt.adds', { pct: fmtPct(plan.addPct) })}</Text>}
            </Box>
          ) : plan.waitDays > 0 ? (
            <Text wrap="wrap">{t('opt.learning', { left: t('n.days', { n: plan.waitDays }) })}</Text>
          ) : (
            <Text color={C.ok} wrap="wrap">{`● ${t('opt.lean')}`}</Text>
          )}
          <Box marginTop={1}>
            {flow(ui, [
              ...(hasSteps ? [<Button key="opt" label={t('opt.review')} variant={primary(surface)} onPress={() => act.opt(true)} />] : []),
              ...(opts.project ? [] : [<Button key="tighten" label={t('opt.tighten')} onPress={() => act.tighten()} />]),
            ])}
          </Box>
          {opts.project ? null : <Text dimColor wrap="wrap">{t('opt.tightenHint')}</Text>}
          {!prefs.autopilot && (hasSteps || opts.project) && (
            <Box marginTop={1}>
              {flow(ui, [<Text dimColor>{t('set.autopilot')}</Text>, <Button key="tip-auto" label={t('home.tip.auto')} onPress={() => act.pref('autopilot', true)} />])}
            </Box>
          )}
        </Box>
      )}

      {advice.length > 0 && !nav.opt && <Box flexDirection="column" marginTop={1}>{advice}</Box>}
      <Box marginTop={1}>
        <Text dimColor wrap="wrap">{t('opt.checked', { tools: t('n.tools', { n: plan.checked.tools }), span: t('n.days', { n: Math.max(1, plan.checked.days) }) })}</Text>
      </Box>
    </Box>,
    hasSteps ? C.brand : C.line,
  )
  return { node, plan }
}

