// "Optimize": what to switch, worked out from what is installed, what each part costs and what the
// person really uses. It is pure and it is free: it reads numbers Pitwall already holds, asks no
// model, sends nothing anywhere and changes nothing by itself. The screen shows the plan, and one
// press applies it as a single change with a single Undo.
//
// The rules are conservative on purpose, because a tool switched off by mistake costs more than a
// tool left on:
//
// - Nothing is judged from less than a week of watching (a month for a whole add-on), and "unused"
//   always means "not opened in the last thirty days, as far as Pitwall has been watching".
// - An add-on is switched off only when none of the skills and helpers it carries was used in that
//   time. One that carries only automations or connections cannot be judged, so it is left alone.
// - A skill of the person's own that is on and unused becomes *light*: Claude still knows its name
//   and can find it, it just does not carry the description in every chat.
// - A skill the person keeps using but that is light or off becomes fully available again: Claude
//   uses a skill better when it can read what it does. So the plan also adds, not only removes.
// - An older copy of an add-on that is also installed is switched off.
// - What cannot be switched here (a long conversation, heavy instructions, an unused connection) is
//   advice: one plain line, no button that acts by itself.

import type { Snapshot, UsageLedger } from '../types'
import { friendlyName, type Item } from './items'

const DAY = 86_400_000
/** How far back "used" looks, and how long Pitwall must have been watching before it judges. */
export const WINDOW_DAYS = 30
export const MIN_SKILL_DAYS = 7
export const MIN_ADDON_DAYS = 14
/** A used-often skill: opened at least this many times in the window. */
const BUSY_USES = 3
/** An add-on smaller than this is not worth a line. */
const MIN_ADDON_PCT = 0.3
/** What a light skill still takes, as a share of what it took: its name only. A stated estimate, not a measurement. */
const LIGHT_KEEPS = 0.2

export type StepKind = 'off' | 'light' | 'on'
export type Why = 'idle' | 'busy' | 'duplicate'

export type Step = {
  /** `plugin:<id>` or `skill:<name>`, the same key an Item has. */
  key: string
  kind: StepKind
  type: 'plugin' | 'skill'
  id: string
  name: string
  why: Why
  /** Days since it was last used, for an idle one; the uses in the window, for a busy one. */
  days: number
  /** What it frees (positive) or adds (negative) in Claude's memory, in tokens, and as a percent of it. */
  tokens: number
  pct: number
}

export type Advice = { id: 'compact' | 'instructions' | 'servers'; pct: number; names: string[] }

export type Plan = {
  steps: Step[]
  /** Freed by the steps that switch off or lighten, and added by the ones that bring a tool back, as percents. */
  freePct: number
  addPct: number
  advice: Advice[]
  checked: { tools: number; days: number }
  /** Days of watching still missing before the usage can be judged; 0 once it can. */
  waitDays: number
}

type Input = {
  items: Item[]
  snap: Snapshot
  ledger: UsageLedger
  /** The skill names each add-on carries, as Pitwall remembers them. */
  names: Record<string, string[]>
  now: number
  /** Steps the person chose to keep: left out of the plan. */
  keep?: string[]
}

const pctOf = (tokens: number, window: number): number => (window > 0 ? (tokens / window) * 100 : 0)

/** Whether any skill or helper of an add-on was used since `since`. */
function addonUsed(id: string, carried: string[], ledger: UsageLedger, since: number): boolean {
  const short = id.split('@')[0].toLowerCase()
  const mine = new Set(carried.map(s => s.toLowerCase()))
  const hit = ([key, row]: [string, { last: number }]) => {
    if (row.last < since) return false
    const low = key.toLowerCase()
    const tail = low.split(':').pop() ?? low
    return low.split(':')[0] === short || mine.has(low) || mine.has(tail)
  }
  return Object.entries(ledger.skills).some(hit) || Object.entries(ledger.agents).some(hit)
}

export function planOptimize({ items, snap, ledger, names, now, keep = [] }: Input): Plan {
  const window = snap.window > 0 ? snap.window : snap.usedTokens
  const watched = Math.max(0, Math.floor((now - ledger.since) / DAY))
  const days = Math.min(WINDOW_DAYS, watched)
  const since = now - days * DAY
  const canJudgeSkills = watched >= MIN_SKILL_DAYS
  const canJudgeAddons = watched >= MIN_ADDON_DAYS
  const skip = new Set(keep)
  const steps: Step[] = []

  for (const item of items) {
    if (skip.has(item.key)) continue

    if (item.kind === 'plugin') {
      if (!item.isOn || item.id.startsWith('pitwall@')) continue
      const row = snap.plugins.find(p => p.id === item.id)
      if (row?.isDuplicate) {
        steps.push({ key: item.key, kind: 'off', type: 'plugin', id: item.id, name: item.name, why: 'duplicate', days: 0, tokens: item.tokens, pct: pctOf(item.tokens, window) })
        continue
      }
      // An add-on with no skill and no helper (only automations or connections) cannot be judged by what is opened.
      if (!canJudgeAddons || (item.skills === 0 && item.agents === 0) || item.share < MIN_ADDON_PCT) continue
      if (!addonUsed(item.id, names[item.id] ?? [], ledger, since)) {
        steps.push({ key: item.key, kind: 'off', type: 'plugin', id: item.id, name: item.name, why: 'idle', days, tokens: item.tokens, pct: pctOf(item.tokens, window) })
      }
      continue
    }

    // A skill of the person's own.
    const used = ledger.skills[item.id]
    if (!canJudgeSkills) continue
    if (item.isOn && item.mode === 'on' && item.tokens > 0 && (!used || used.last < since)) {
      const freed = Math.round(item.tokens * (1 - LIGHT_KEEPS))
      steps.push({ key: item.key, kind: 'light', type: 'skill', id: item.id, name: item.name, why: 'idle', days, tokens: freed, pct: pctOf(freed, window) })
    } else if ((!item.isOn || item.mode !== 'on') && used && used.last >= since && used.n >= BUSY_USES) {
      steps.push({ key: item.key, kind: 'on', type: 'skill', id: item.id, name: item.name, why: 'busy', days: used.n, tokens: -item.weight, pct: pctOf(-item.weight, window) })
    }
  }

  const order: Record<StepKind, number> = { off: 0, light: 1, on: 2 }
  steps.sort((a, b) => order[a.kind] - order[b.kind] || b.tokens - a.tokens || a.name.localeCompare(b.name))

  const advice: Advice[] = []
  const messages = snap.categories.find(c => c.name === 'Messages' && c.kind === 'used')
  if (messages && pctOf(messages.tokens, window) >= 50) advice.push({ id: 'compact', pct: pctOf(messages.tokens, window), names: [] })
  const memory = [...snap.memory].sort((a, b) => b.tokens - a.tokens)
  const memoryPct = pctOf(memory.reduce((n, m) => n + m.tokens, 0), window)
  if (memoryPct >= 1.5) advice.push({ id: 'instructions', pct: memoryPct, names: memory.slice(0, 3).map(m => m.path.split(/[\\/]/).pop() ?? m.path) })
  if (canJudgeAddons) {
    const calls = Object.entries(ledger.tools).filter(([, row]) => row.last >= since).map(([k]) => k.toLowerCase())
    const idle = snap.mcp.filter(m => m.tokens >= 1500 && !calls.some(k => k.startsWith(`mcp__${m.server.toLowerCase().replace(/[^a-z0-9]+/g, '_')}__`)))
    if (idle.length > 0) advice.push({ id: 'servers', pct: pctOf(idle.reduce((n, m) => n + m.tokens, 0), window), names: idle.slice(0, 4).map(m => friendlyName(m.server)) })
  }

  const freed = steps.filter(s => s.tokens > 0).reduce((n, s) => n + s.tokens, 0)
  const added = steps.filter(s => s.tokens < 0).reduce((n, s) => n - s.tokens, 0)
  return {
    steps,
    freePct: pctOf(freed, window),
    addPct: pctOf(added, window),
    advice,
    checked: { tools: items.length, days },
    waitDays: Math.max(0, MIN_SKILL_DAYS - watched),
  }
}

/** The one change a plan makes, in the shape the controller applies with one backup and one Undo. */
export function planChange(steps: Step[]): { plugins: { id: string; isOn: boolean }[]; skills: { name: string; mode: 'on' | 'name-only' | 'off' }[] } {
  return {
    plugins: steps.filter(s => s.type === 'plugin').map(s => ({ id: s.id, isOn: s.kind === 'on' })),
    skills: steps.filter(s => s.type === 'skill').map(s => ({ name: s.id, mode: s.kind === 'light' ? ('name-only' as const) : s.kind === 'on' ? ('on' as const) : ('off' as const) })),
  }
}

