// Type contract of Pitwall's session state. Every value is plain JSON so that
// the host can hold it across hot reloads. See hooks/register.tsx.

export type Tab = 'home' | 'tools' | 'chat' | 'activity' | 'global'

/** Where a change is written: the project's own settings, or the global ones every project inherits. */
export type Scope = 'project' | 'global'

/** The add-ons and skills one settings source sets, as Claude Code reads it. */
export type Layer = { plugins: Record<string, boolean>; skills: Record<string, string> }
/** What each source sets on its own; the merged result is what the chat gets. */
export type Layers = { user: Layer; project: Layer; local: Layer }

/** The folder a chat runs in, and what Pitwall knows about it. */
export type ProjectInfo = {
  root: string
  name: string
  key: string
  /** What kind of work the files in the folder suggest. */
  guess?: { job: string; evidence: string[] }
  /** The kind of work the project was last set up for, and when. */
  profile?: { job: string; at: number }
  /** The person said the starting profile does not fit this one. */
  declined?: boolean
}
export type KnownProject = { key: string; name: string; last: number }

/** The four states Claude Code's `skillOverrides` setting knows. */
export type SkillMode = 'on' | 'name-only' | 'user-invocable-only' | 'off'

export type Category = { name: string; tokens: number; kind: string }

export type PluginRow = {
  /** `name@marketplace`, as settings.json keys it. */
  id: string
  name: string
  marketplace: string
  version: string
  /** True when `enabledPlugins` turns it on; plugins that are not listed are off. */
  isOn: boolean
  skills: number
  agents: number
  /** Tokens it adds to every session while on; 0 while off (not measured). */
  tokens: number
  /** Another installed plugin has the same name (a stale copy). */
  isDuplicate: boolean
  /** What it cost the last time it was on, so an off plugin shows what turning it on would add. */
  lastTokens?: number
  /** What its plugin.json says it does, and where its repository is (one https URL). */
  description?: string
  repo?: string
  /** Names of the skills it carries, while it is on: what its set is worked out from. */
  skillNames?: string[]
}

export type SkillRow = {
  name: string
  /** `userSettings`, `projectSettings`, `plugin`, `built-in`, ... */
  source: string
  plugin?: string
  tokens: number
  mode: SkillMode
  /** True for a skill whose files Pitwall may switch with `skillOverrides`. */
  isOwn: boolean
  /** What its SKILL.md says it does, and its repository when the frontmatter names one. */
  description?: string
  repo?: string
  /** What it cost the last time it was listed, so one that is off can say what turning it on adds. */
  lastTokens?: number
}

/** `tokens` counts only tools whose schema is in the window; `deferred` tools load on demand. */
export type McpRow = { server: string; tools: number; tokens: number; deferred: number }
export type MemoryRow = { path: string; kind: string; tokens: number }
export type HookRow = { event: string; matcher: string; command: string }
export type LimitRow = { kind: string; percent: number; resetsAt?: string }

export type Snapshot = {
  at: number
  model: string
  window: number
  usedTokens: number
  percent: number
  categories: Category[]
  plugins: PluginRow[]
  skills: SkillRow[]
  skillTotals: { total: number; listed: number; tokens: number }
  agents: { name: string; source: string; tokens: number }[]
  mcp: McpRow[]
  memory: MemoryRow[]
  hooks: HookRow[]
  limits: LimitRow[]
  costUsd?: number
  /** False when Claude Code gave no usage report, so no number is shown instead of 0. */
  hasUsage: boolean
  /** Things Pitwall could not read, shown instead of guessed. */
  errors: string[]
}

export type ChatLine = { role: 'user' | 'assistant' | 'system'; text: string; at: number }

export type ActivityKind = 'tool' | 'skill' | 'agent' | 'turn' | 'change'
export type ActivityItem = { at: number; kind: ActivityKind; label: string }

export type Hint = {
  id: string
  /** `plugin` or `skill`. */
  kind: 'plugin' | 'skill'
  target: string
  text: string
}

/** What was used and when, kept across sessions in `$.store`. */
export type UsageLedger = {
  since: number
  skills: Record<string, { n: number; last: number }>
  agents: Record<string, { n: number; last: number }>
  tools: Record<string, { n: number; last: number }>
}

/** What the person can switch off in Pitwall itself. */
export type Prefs = { showBand: boolean; hints: boolean; summaries: boolean
  /** Make tools nobody opened for a month light, by itself, when a chat starts. */
  autopilot: boolean; lang: 'auto' | 'en' | 'it' | 'es' | 'fr' | 'de' | 'pt' | 'zh' | 'ja' | 'ru' | 'ko' | 'hi' }

/** Where the person is in the panel: the tab, and the one set, tool and advanced section opened. */
export type Nav = { tab: Tab; open: string | null; info: string | null; adv: string | null; /** the tool whose technical details are shown */ tech: string | null; /** the set shown in full */ more: string | null; /** the advanced part of Settings is expanded */ advOn: boolean; /** what the search in My tools looks for; empty when it is not used */ find: string; /** the Optimize plan is open on Home */ opt: boolean; /** the steps of the plan the person chose to keep as they are */ keep: string[]; /** the tools of every project are shown on the Global tab */ gtools: boolean }

/** What most drawings read: the measurement and the small facts around it. */
export type Core = {
  snap: Snapshot | null
  /** Changes made this session that take effect on the next one. */
  pending: string[]
  prefs: Prefs
  /** The last result of an action. */
  notice: string | null
  /** A running background action, shown as a line. */
  busy: string | null
  hint: Hint | null
  /** The plain summary and set of each tool, in the language in use: what the model wrote, kept on this computer. */
  digest: Record<string, { s: string; c?: string }>
  /** True while the small model is writing summaries. */
  digesting: boolean
  /** What each settings source sets on its own: tells what a project sets from what it inherits. */
  layers: Layers | null
  /** The folder this chat runs in, or null when it cannot have settings of its own (the home folder). */
  project: ProjectInfo | null
  /** The projects Pitwall has seen, newest first. */
  projects: KnownProject[]
}

/** The conversation with the assistant. */
export type Talk = {
  chat: ChatLine[]
  isChatBusy: boolean
  /** How many messages were sent; the chat field gets a fresh key per send so it empties. */
  sent: number
  /** What the assistant is doing right now. */
  trace: string[]
}

/** What Pitwall changed lately. */
export type Live = { recent: ActivityItem[] }

declare module 'claude-code' {
  interface PluginState {
    pitwall: {
      nav: Nav
      core: Core
      talk: Talk
      live: Live
    }
  }
}
